INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1166922', 'stk-guest', 'ENGL 101', 'info', '{"desc": "للمعلومية الكورس هذا ستاندرد، 95 وفوق a+ وكل خمس درجات بقريد ، صعب جدا انك تاخذ b+ وفوق من غير دف فنصيحة دور المدرس اللي مايكرف ويدف", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/8", "user": "Guest", "ts": 1358729832000, "tid": 120478, "pn": 8}}', 1358729832000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1252226', 'stk-practice', 'ENGL 101', 'info', '{"desc": "بس اختار دكتور كويس ولا راح تحس بالكورس ذا نهائيا\n\nانصح بـ jonathan marquies", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/11", "user": "Practice", "ts": 1376193478000, "tid": 120478, "pn": 11}}', 1376193478000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1267447', 'stk-user5272', 'ENGL 101', 'info', '{"desc": "كان عندكم اختبار رايتنق ثاني اسبوع\n\nبعدين تغير النظام وحطوا معه كتاب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/13", "user": "user5272", "ts": 1379921175000, "tid": 120478, "pn": 13}}', 1379921175000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1295414', 'stk-abdulrahman_n', 'ENGL 101', 'info', '{"desc": "انا الحمدلله انجليزيتي طيبة\nلكن الكورس ذا غثيث !\nكل شويا اطبع وجيب وكل كم يوم اختبار !\nبس زي ماقالو الشباب على حسب مدرسك يكرفك ولا لا\nاعتقد النجاح فيه مضمون بإذن الله لكن القريد المرتفع ! مرة صعب الصراحة\nانا ذاكرت مذاكرة طبيعية للميدتيرم وجبت c+\n\nموفقين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/16", "user": "Abdulrahman_N", "ts": 1385547146000, "tid": 120478, "pn": 16}}', 1385547146000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1317233', 'stk-user8581', 'ENGL 101', 'info', '{"desc": "كورس سهل جدا وحاول تنزل عند دكتور مايظلم الطلاب عشان سياسة القسم في القريدات …\nاذا كنت ماخذ بروموشن نزله في الاوريا احسن وافتك منه لأنه الصراحة اشوفه كورس ماله داعي وماتستفيد شي منه .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/18", "user": "user8581", "ts": 1389180164000, "tid": 120478, "pn": 18}}', 1389180164000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1321736', 'stk-medoalkebsi', 'ENGL 101', 'info', '{"desc": "اكثر كورس بالجامعه انظلمت فيه 😭 .\n\nجدآ جدآ جدآ جدآ جدآ جدآ جدآ سسههههههههههههههل , بس مليان كوزات .\n\nمافيه شي صعب , والمهم انك تشبك الدكتورررررررررررررر . سواء 101 ولا 102 .\n\nوبالتوفيق ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/19", "user": "Medoalkebsi", "ts": 1390526381000, "tid": 120478, "pn": 19}}', 1390526381000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1371942', 'stk-mhm14', 'ENGL 101', 'info', '{"desc": "Term 131\n\nالكورس عن مهارات اللغة الإنجليزية بشكل عام، قراءة-كتابة-قرامر-إلقاء\nيكاد يكون الكتابة أكثر شيء مركز عليه\nكان فيه 4 رايتنغ تاسك :\nDefinition\nCompare & Contrast\nCause & Effect\nArgument\nو كل وحده ليها طريقة و خطوات للكتابة\n\nو في 4 كوزات ريدنغ و حسيتهم صعب شوي\nو كوزين قرامر و فوكاب\nالفوكاب يكون من الـ Academic word list تقريبا 6 مجموعات و كل مجموعة 60 كلمة قالوا لازم نحفظهم و في الميدترم و الفاينل يختبرك على 3 نصوص، نصين يكون يعطيك إياهم قبل يوم من الإختبار و الثالث تشوفه في الإختبار، و كذلك يختبرك على كم فقرة في القرامر مع كم سؤال من الكلمات\n\nما كان فيه كتاب للكورس إلا الجزء حق القرامر يكون محدد الأقسام اللي بتجيك في الإختبار و كان كل الشغل على البلاكبورد\nوكان في آخر الترم تقدم برزنتيشن عن موقع إلكتروني مفيد للطلاب و تشرح عنه\nعموما ما حسيت بثقلها بس فيها أشياء متنوعة و حسيته كورس متوسط\n\nالقريد النهائي : C+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/21", "user": "MHM14", "ts": 1401098094000, "tid": 120478, "pn": 21}}', 1401098094000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1376706', 'stk-abo-da7m', 'ENGL 101', 'info', '{"desc": "Term 132\n\nجودة المقرر بشكل عام\n\nجيدة\n\nالمواضيع التي يغطيها المقرر\n\nالمقرر عبارة عن أربع وحدات :\n\nالأولى … التعريف وكيف تكتب تعريف ( definition )\nالثانية … التحليل السببي (causal analysis )\nالثالثة … المقارنة ( comparison )\nالرابعة … ( argument ) مدري شلون اترجمه 😆 عموما تتبنى وجة نظر وتدافع عنه بأسباب مقنعة\n\nكل وحدة له ملف وورد حول 30 صفحة فيه 1 ريدنق 2 رايتينق 3 قرامر 4 فوكاب\n\nمعظم الوحدة ( وعنوانه ) عن الرايتنق\n\nالريدينق مقالة وحدة حول صفحتين\n\nوالقرامر سهل وعبارة عن مراجعة\n\nالكتاب المستخدم للمقرر\n\nمثل ما ذكرت فوق كل وحدة له ملف وورد + يعطونك كتاب مفردات وياخون منه وحدات بسيطة\n\nتقسيم الدرجات :\n15 % 4 كويزات ريدينق ( من عند المدرس وهو حر بالنص اللي يجيبه )\n\n10 % اختبارين فوكاب وقرامر من ملف الوورد تبع الوحدة + ( بعض الفوكاب من الكتاب اللي يعطونك )\n\n35 % 4 رايتنق تاسك، كل رايتنق مثل عنوان الوحدة\n\n5 % برزنتيشن\n\n15 % ميدتيرم ( ريدينق + فوكاب وقرامر ) ( مشترك )\n\n20 % فاينل ( ريدينق + فوكاب وقرامر ) ( مشترك )\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nتعتمد على الدكتور إلا الاختبارات المشتركة ( ميترم وفاينل ) صعبة نوعا ما لكن تقدرتجيب درجة اذا حضرت كويس خصوصا قسم الفوكاب\n\nمدى فائدته في الناحية التطبيقيةمتوسط الفائدة\n\nأخرى :* برأيي الشخصي … درجتك بهالكورس تعتمد كثير على مستوى لغتك قبل تاخذه فإذا كان عندك فرصة تأخره أخره وطور لغتك قبل تاخذه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/22", "user": "abo-da7m", "ts": 1401804540000, "tid": 120478, "pn": 22}}', 1401804540000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1383606', 'stk-aziz99', 'ENGL 101', 'info', '{"desc": "بالنسبة لي كنت ماخذ هالكورس في 132 وكنت منزل عند سكوت سوران\nوهذا تقييمي\n\nجودة المقرر بشكل عام : مقرر مهم جداً بس سهل\nالمواضيع التي يغطيها المقرر : يعطونك كلمات أكاديمية ويختبرونك عليها VG1&VG2 بالإضافة الى قرامر و4 كويزات ريدنق و5 رايتنق تاسك(دفنشن, كومباريسن,ارقيومنت,كوز اند إفكت)\nالكتاب المستخدم للمقرر: يرسلوا لك عالبلاك بورد أوراق وتدرس منها\nالأسئلة والأمثلة المستخدمة في المقرر: بالنسبة للفوكاب يفضل تشترك في موقع QUIZLET وتدور على Acadimic word list تبع جامعتنا وتحاول تتدرب هناك\nمدى فائدته في الناحية التطبيقية : صراحة أفادني بموسوعة كبيرة من الكلمات الأكاديمية بس من ناحية الكتابة ما استفدت لأاني كنت مهمل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/23", "user": "aziz99", "ts": 1404121648000, "tid": 120478, "pn": 23}}', 1404121648000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1439402', 'stk-user9534', 'ENGL 101', 'info', '{"desc": "كورس يعتمد على المدرس بشكل كبير 😆\n\nكورس سهل ولا فيه اشياء صعبة 😆 دور مدرس مايكرف وخلاص وضعك سمبتيك 😆", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/25", "user": "user9534", "ts": 1453073305000, "tid": 120478, "pn": 25}}', 1453073305000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1449529', 'stk-walo0od', 'ENGL 101', 'info', '{"desc": "Term 152\nجودة المقرر بشكل عام\nأحسه غير مفيد بشكل عام خاصةً أنه نسخة من انقليزي الأوريا\nعندك AWL اللي هي Academic Word List هذي إذا حفظتها ممكن تزيد حصيلتك بس أنت تقدر تحفظها من دون الكورس هذا فما يعتبر شيء خاص بالكورس\nالمواضيع التي يغطيها المقرر\n* أربع تاسكات رايتنق كل واحدة 10%:\n- Definitions: اللي هي التعاريف وهو الشي الوحيد المختلف عن الأوريا في الرايتنق. يعلمك كيف تكتب تعريف لكلمة محددة وكأنك تصفها لواحد ما يعرف ايش الشيء هذا بالمرة، تقريباً زي القاموس وفي الرايتنق تاسك WT1 يعطيك ثلاث كلمات (أشياء - أشخاص - مشاعر) تعرفها في 200-250 كلمة، ثنتين منها يعطيك اياها قبل 24 ساعة والثالثة اللي هي حق المشاعر مفاجأة 🙂\n- Cause and Effect: زي الأوريا تقريباً، يعطيك موضوع معين وأنت تتكلم عنه من ناحية الأسباب والآثار وفي النهاية تكتب رأيك واقتراحك للحد من المشكلة هذي وكذا … سهل\n- Compare and Contrast: تقارن بين شيئين مع أمثلة\n- Argument: هذي تعرض فيها آراء متضادة. يعني في قطعة الFor تعطي الآراء اللي تؤيد هذا الموضوع والقعطة الثانية Against تطرح الآراء المعارضة\n\n* ريدنق كويزيز:\nعندك كوزين كل واحد عليه 5% اختيارات ومن القسم يعني مو من المدرس (كان من المدرس بس الترم هذا غيروا)\nواحد قبل الميدتيرم وواحد قبل الفاينل، يعني تقدر تقول يجهزك قبل الاختبارات الرئيسية\n\n* عرض سبيكنق:\nتطلع قدام الطلاب وتتكلم عن موضوع في 2-3 دقايق وعليه 5% … بسيط جداً\n\n* الميدتيرم (20%) والفانيل(25%):\nالميدتيرم:\nثلاث قطع ريدنق (30 سؤال) + 15 سؤال فوكاب وقرامر والWord Formation اللي هو تركيب الكلمات\nالفوكاب من AWL يكون عندك ثلاث قوائم اللي هي\nAWL1 + AWL2 + AWL3\nأما الريدنق فيه ملفات يعطيك اياها الدكتور تتدرب عليها + قبل الاختبار ب24 ساعة ينزلوا قطعتين من القطع اللي بتجي في الاختبار\nالفاينل:\nنفس المدتيرم اللهم إن القوائم بتزيد إلى ست + عدد الأسئلة 55 يعني ثلاث قطع والباقي فوكاب وقرامر وأشياء ثانية تبع الفواصل ما الفواصل\n\nالكتاب المستخدم للمقرر\nأخذت الكتاب بس صراحة ما فتحته فبالتالي ما راح أفتي فيه\n\nمدى فائدته في الناحية التطبيقية\nزي ما قلت أشوف ما منه فايدة (بالنسبة لي على الأقل)\n\nإضافات\n\nالكورس سهل جداً ولا تهمك السمعة المخيفة اللي منتشرة عنه … ترى إذا تبغى تجيب A+ تقدر تجيبها ولا يهمك اللي يقول حدك B أو C+\nهذي درجات شعبتنا\nتلاحظ إن الA وB+ كثيرة صح ؟ فعشان كذا أقولك لا يهمك الكلام اللي منتشر\nأهم شي:\n1- سجلها مع مدرس ممتاز (أنا أنصح ب Keith Ford أو Jonathan Marquis)\n2- سو اللي يقول لك عليه المدرس بالحرف وأمورك في السليم\nولو طموحك الA+ فحاول تتدرب على الرايتنق والريدنق والفوكاب كثير حتى من دون ما يقولها لك الدكتور\n\nعلى فكرة مدرسي هو Keith Ford والدرجات في الصورة هي درجاته فعشان كذا أنصحك فيه + يفضل تكون عارف المدرس أو على الأقل سمعته كويسة لأنه راح يضبطك إذا كان ممتاز\n.\n.\n.\nبالتوفيق لكل من ياخذ الكورس … الكورس كورس قريد فلا تضيعه 😉", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/26", "user": "Walo0od", "ts": 1463581241000, "tid": 120478, "pn": 26}}', 1463581241000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466975', 'stk-abdullah2015', 'ENGL 101', 'info', '{"desc": "ترم 161\n\nمواضيع المقرر غطوها الأخوة اللي قبلي فما يحتاج أعيد، كل اللي بقوله هو إن المقرر يعتمد بشكل كبير على لغتك الإنجليزية بشكل عام قبل ما تأخذ الكورس (ومستواك في الWriting والReading بشكل خاص حيث إن 40% من درجة الكورس عبارة عن Writing ، وأغلب الدرجات في الميد تيرم والفاينل عبارة عن قطع Reading وكذلك عندك 2 ريدنق كويزز كل واحد فيهم عليه 5 % من درجات الكورس)\n\nقد ما لغتك الإنجليزية قوية تقدر تتنبأ بالقريد التقريبي اللي بتاخذه، غالبًا القريد اللي بتطلع به (كطالب أفرج) هو C, C+ , B إلا لو كان مستواك مرة عالي ولغتك مرة قوية راح توصل للA أو الA+\n\nولو كانت لغتك مرة نازلة وما بذلت جهد في الكورس راح تطلع ب D, D+ هذا إذا ما طلعت ب F\n\nفي السكاشن اللي يدرسها دكتوري كان فيه واحد فقط اللي جاب A+ في الكورس والباقي زي ما ذكرت أغلبهم ما بين الD إلى B\n\nلو حصلت قريد عالي في الكورس فهو 100% بسبب قوة لغتك قبل ما تدخل الكورس موب بسبب جهدك\n\nلتقريب الفكرة، الوضع شبيه جداً بإنجلش الأوريا، أغلب الطلاب في اللفل درجاتهم حول الأفرج ( بين 70 - 80) واللي درجته فوق ال80 عادة يكون لغته إنجليزية قوية (فوق مستوى اللفل) قبل ما يدرس اللفل.\n\nلذلك الطلاب اللي يجيبون A في إنجلش الأوريا نادرين ، كذلك الوضع في إنجلش الجبل، لكن معايير التقييم تختلف 🙂\n\nفعلى أساس هذا أنصح الأوريات اللي خلصوا الإنجليزي الترم الأول إنه ما ينزل ENGL101 الترم الثاني، ويظل يقرأ ويشاهد أفلام ويطور لغته قد ما يقدر قبل ما يدخل الكورس\n\nإلا لو كان واثق من لغته بشكل كبير ويشوف إنه واصل درجة عالية من الFluency أو يبي يفتك من الكورس هنا بهالحالة ينزل الكورس …\n\nوبالتوفيق 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/27", "user": "Abdullah2015", "ts": 1485345378000, "tid": 120478, "pn": 27}}', 1485345378000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518652', 'stk-mr.power', 'ENGL 101', 'info', '{"desc": "بسم الله الرحمن الرحيم …\n\nكورس يعتبر أساس وركن أساسي نحو الطقس الاكاديمي للغة ، الكورس من بدايته إلى نهايته عبارة عن كيف تمسك قلم وتكتب أي شيء يجيك بالانجليزي ، هذي هي ببساطة .\n\nطبعاً التحديات اللي راح تواجهك وش هي ؟ هي واضحة وشارحه نفسها …\n\nعشان تكتب تحتاج كمية كلمات كبيرة وأهم شيء تكون لها علاقة بالموضوع اللي قاعد تكتب عنه\n\nوكذلك تكون عندك كمية كلمات اكاديمية كويسة مو لازم كثير بس كلما كثرت من كتابتهم كلما كان حصولك على الدرجة أعلى …\n\nبالإضافة إلى كتابتك للكلمات بالطريقة السليمة ولو أن معظم الدكاترة أحس يتغاضون عنها لو كانت الكلمة اللي كتبتها في جملة أو فقرة جداً ممتازة أو الكلمة كانت في موقعها المناسب في الجملة …\n\nوأخيراً طريقة ربطك للجمل والفقرات ، وهالشيء مهم جداً …\n\nعموماً كل هالاشياء تتطلب مجهود عالي وممارسة للكتابة من أول السمستر ، بدون ممارسة ماراح تمشي ، والأهم من هذا كله أن يكون فيه أحد يصححلك أخطائك والأفضل طبعاً دكتورك …\n\nأذكر كان معنا طالب كتب تقريباً فوق الـ٦٠ ورقة خلال السمستر ماشاءالله عليه ، وهذا هو المطلوب وبالعكس المفروض أعلى وأعلى", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/28", "user": "Mr.power", "ts": 1577953695000, "tid": 120478, "pn": 28}}', 1577953695000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p789197', 'stk-student_nz', 'ENGL 101', 'info', '{"desc": "انجلش 101\n\nمن اسهل الكورسات\n\nالكورس يتكوون تقريبا من 4 رايتنق تساك كل واحد منهم عليه تقريبا 10 %\nميد تيرم ( ريدنق 10%(\nفاينل ( رايتنق(\nبريزنتايشن تقريبا عليه 10 %\nمشاركة الظاهر عليها 5%\nكوزات تقريبا 10 %\n\nهذا اللي اذكره\n\nالمهم\nهذا الكورس من اسهل الكورسات\nما فيه كرف كثير>> يعتمد على المدرس طبعا\nكورس يعتبر خفيف\n\nوهذا الكورس ما ينزل بالصيف", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/101-102-214/102863/1", "user": "student_NZ", "ts": 1297628617000, "tid": 102863, "pn": 1}}', 1297628617000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p897920', 'stk-equal', 'ENGL 101', 'info', '{"desc": "101 عندك 4 writing tasks هذي زبدة الكورس … مقدمة الى أساسيات الكتابة الأكاديمية … كورس خفيف وأقدر أقول انه “لعب عيال” …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/101-102-214/102863/42", "user": "equal", "ts": 1315632218000, "tid": 102863, "pn": 42}}', 1315632218000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p582353', 'stk-phenomenon', 'ENGL 101', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nحياكم الله يا من تقرؤون الموضوع 🌹\n\nقبل ساعه ونصف كان اختبار منتصف الفصل لـEngl101\n\nوكان ريدينغ … ثلاث قطع وكل قطعه 10 أسئله\nوالوقت : ساعه كامله\n\nأنا أشوف أن الاختبار كان متوسط\nوفيه كم سؤال صعبه شوي أو بالأصح مبهمه !\nوالوقت كافي ومناسب تماما 👍\n\nأنتظر آراءكم 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl101-midterm/86478/1", "user": "Phenomenon", "ts": 1270397790000, "tid": 86478, "pn": 1}}', 1270397790000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p961211', 'stk-scorbion', 'ENGL 101', 'srcU', '{"html": "السلام عليكم<br>ياشباب هذي القطع ترجمت الكالمات الصعبة فيها و قلت خلني احطها في المنتدى ليستفيد منها الجميع<br><br>​<span data-fid=\"stk-f961211-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f961211-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f961211-0": {"name": "The Science Behind Diet and Cancer(Tran).doc", "v": "data:application/msword;base64,"}, "stk-f961211-1": {"name": "Omega Oil(Trans) .doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/readings-engl101/117681/1", "user": "scorbion", "ts": 1325959741000, "tid": 117681, "pn": 1}}', 1325959741000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1009369', 'stk-user7909', 'ENGL 101', 'srcU', '{"html": "من المرفقات<br>هنا رابط لأماكن الجلوس<br><br>​<span data-fid=\"stk-f1009369-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1009369-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1009369-0": {"name": "READING Mosquitos.doc", "v": "data:application/msword;base64,"}, "stk-f1009369-1": {"name": "READING Osteoporosis.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101/123055/8", "user": "user7909", "ts": 1331897742000, "tid": 123055, "pn": 8}}', 1331897742000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p919138', 'stk-opalmax', 'ENGL 101', 'srcU', '{"html": "وعليكم السلام ,<br><br>والله يا خوي , ما أدري أيش تقصد بالورد لست ؟!؟<br>لكن , حمل الملف اللي في المرفقات , يمكن هو اللي تقصده ,<br><br>هذي الكلمات أعطاني إياها (أ.جوش بيلام) , 🤠<br><br>بالتوفيــق , 🌹<br><br>​<span data-fid=\"stk-f919138-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f919138-0": {"name": "Words.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/word-list-english-101/113856/3", "user": "Opalmax", "ts": 1318609630000, "tid": 113856, "pn": 3}}', 1318609630000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1199763', 'stk-exuse_me', 'ENGL 101', 'srcU', '{"html": "ُُEnglish101 mid-term text ( TRANSLATED) d<br><br>**السلام عليكم ورحمة الله وبركاته …<br><br>اليوم اطلقو قطعة من قطع الاختبار وترجمتها ، وان شاء الله الكل يستفيد<br><br>best of luck<br><br>​<span data-fid=\"stk-f1199763-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>**", "files": {"stk-f1199763-0": {"name": "ENGLISH 101 MIDTERM EXAMINATION.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl101-midterm/141950/8", "user": "Exuse_Me", "ts": 1363360984000, "tid": 141950, "pn": 8}}', 1363360984000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p617674', 'stk-abu_3zzoz', 'ENGL 101', 'srcU', '{"html": "طلعت كلاسميتي عند دونوفان 😍 بالنسبة للبورتفوليو مايمديك تسوي شي لان اليوم موعد التسليم بس شوف المرفقات يمكن يفيدك 😦<br><br>​<span data-fid=\"stk-f617674-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f617674-0": {"name": "PORTFOLIO.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/88996/10", "user": "Abu_3zzoz", "ts": 1275137122000, "tid": 88996, "pn": 10}}', 1275137122000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1047430', 'stk-isengineer210', 'ENGL 101', 'srcU', '{"html": "هذا ملف توزيع الدررجات ان شاء الله يفيدكم 🌹<br><br>نصيحة للي بياخذون هالكورس دوروا على المدرس اللي (( ما يكررف ))<br><br>لان بالاخير القريدات بتطلع هي هي B, Cs, Ds !<br><br>بالتوفيق جميعاً ❤️<br><br>​<span data-fid=\"stk-f1047430-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1047430-0": {"name": "101 Course Components - Sem 112.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/5", "user": "ISEngineer210", "ts": 1338288333000, "tid": 120478, "pn": 5}}', 1338288333000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p960525', 'stk-user7562', 'ENGL 101', 'srcU', '{"html": "GRAMMAR<br>The exam will test points covered in the Remedial Work component<br>relative clauses in formal definition,<br>sentence fragment<br>subject-verb agreement<br>run on sentences<br>pronoun-antecedent agreement<br>structures arising from the compositions (ie structures in definition, causal analysis,<br>comparison and argument)<br><br>===<br><br>شباب الي عنده ملفات او اوراق عن القرامر يرفعه<br>واذا كانت في الكتاب يعلمنا …<br>تكفوووووووووون يا عياااااال العووووون", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/101-eng/117533/4", "user": "user7562", "ts": 1325882118000, "tid": 117533, "pn": 4}}', 1325882118000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p960692', 'stk-ll_m_ll', 'ENGL 101', 'srcU', '{"html": "فيه موقع حلو يعطيك شرح ثم بالاخير يعطيك كويزات ويصحح لك<br><br>• relative clauses in formal definitions<br>http://grammar.ccc.commnet.edu/grammar/clauses.htm<br><br>• sentence fragments,<br>http://grammar.ccc.commnet.edu/grammar/fragments.htm<br><br>• subject-verb agreement<br>http://grammar.ccc.commnet.edu/grammar/sv_agr.htm<br><br>• run on sentences<br>http://grammar.ccc.commnet.edu/grammar/runons.htm<br><br>• pronoun-antecedent agreement<br>http://grammar.ccc.commnet.edu/grammar/pronouns.htm<br><br>هذي فقط المواضيع اللي قدرت عليها<br><br>بالتوفيق ان شاءالله", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/101-eng/117533/9", "user": "ll_M_ll", "ts": 1325907022000, "tid": 117533, "pn": 9}}', 1325907022000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1008904', 'stk-nasser_9x', 'ENGL 101', 'srcU', '{"html": "مــن واقــع تجــربة<br><br>1- افهـــم كل مــا في القطعتيــن … \" لمـا تحس أنـــك بتجــاوب دون مــا تقــرأ 🙂 \" .<br><br>2- احفـــظ الوورد لســـت .<br><br>3 - الوحــدات المحــددة في كتــاب Vocabulary in Use .<br><br>وإن شـــاء اللـــه من 43 - 45 / 45 🌹", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/eng101/122997/14", "user": "NASSER_9X", "ts": 1331831086000, "tid": 122997, "pn": 14}}', 1331831086000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1009059', 'stk-3loole', 'ENGL 101', 'srcU', '{"html": "زي ماقالوا الشباب<br>1- القطعتين فهم مو بس ترجمة<br>2- الوورد لست 1و2و3 … موجوده بموقع الانجلش<br>3- من كتاب English Vocabulary in Use … units 8,9,23,26<br><br>وهادي الوورد لست مترجمة (ترجمة google)<br>http://www.mediafire.com/?s1sabvbdn24v12q<br><br>فالكم الفل مارك", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/eng101/122997/17", "user": "3loole", "ts": 1331845545000, "tid": 122997, "pn": 17}}', 1331845545000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1008583', 'stk-brilliant_accountant', 'ENGL 101', 'srcU', '{"html": "عليكم بالقطعتين … مو بس تقرأهم بل أقرا وافهم المحتوى كاملا واعرف كل الكلمات<br>وهذا بيخليك تحل اسئلة القطعتين بدون ما تضيع وقتك وتقرأ القطعتين في الاختبار<br><br>و ذاكروا الورد لست<br><br>موفقين", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/eng101/122997/5", "user": "Brilliant_Accountant", "ts": 1331808753000, "tid": 122997, "pn": 5}}', 1331808753000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1199587', 'stk-user9537', 'ENGL 101', 'srcU', '{"html": "وعليكم السلام ورحمة الله.<br>أنا أختبرت الترم الماضي والحمدلله أخذت A بالميدتيرم وطريقة مذاكرتي هي كالتالي.<br>ذاكرت ال AWL وحليت الأسئلة اللي بالموقع اللي مستوى صعوبتها a و b و c جميعها. ذاكرت القرامر اللي بالويبسيتي وحليت الأمثلة، ذاكرت اللي مطلوب علينا من كتاب English Vocabulary in Use، راجعت الـ practice tests اللي أعطانها المدرس بالكلاس، ذاكرت old exam اعطاناه المدرس، وأخيرا ذاكرت القطع اللي اعطوناها وترجمتها ومخمخت عليها.", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl101-midterm/141950/2", "user": "user9537", "ts": 1363293481000, "tid": 141950, "pn": 2}}', 1363293481000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1336381', 'stk-mountine_man', 'ENGL 101', 'srcU', '{"html": "بيعطوكم قطعتين ريدينق قبل الميد تيرم بيوم<br>افضل شيء تسوونه انكم تقرؤون كل قطعة وتقسمونها الى اجزاء اصغر وتعرفون المعلومات المهمة مثل التعاريف والأرقام والنسب والأمثلة وحاولوا يكون عندكم فكرة كاملة عن كل قطعة (الهدف الأساسي ) ولخصوها في نقاط اساسية<br><br>وبالتوفيق", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl101/157782/3", "user": "mountine_man", "ts": 1393863447000, "tid": 157782, "pn": 3}}', 1393863447000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1278124', 'stk-user8581', 'ENGL 101', 'srcU', '{"html": "الـ unit 2 الي في ملف الريدينغ فيها غرامر معانا في الميدتيرم \" صفحة 34 -35<br>والجرامر الاول relative clauses موجود في الملف<br><br>وهذي معلومات عن الميدتيرم<br><br>101 Mid-Term Exam.<br>Two of the three exam passages will be made available to students about 24 hours before the exam. They will be posted on the 101 students’ course Blackboard page and will be made available to 101 teachers to upload onto their sections’ BB page.<br><br>MIDTERM EXAMINATION 15% (MTE)<br><br>The 101 MTE is multiple-choice and tests reading, vocabulary and grammar. (Typically, there are 45 questions to be answered in 75 minutes.)<br><br>PART A: READING<br><br>The exam will contain three reading passages two of which will be pre-released shortly before the examination to give students the opportunity to familiarize themselves with the content. One of the exam readings will therefore be previously unseen. Questions will be those used in the teacher’s own reading quizzes, such as comprehension, reference, identifying main and secondary ideas, skimming, scanning, and so on.<br><br>PART B: VOCABULARY &amp; GRAMMAR<br><br>The vocabulary to be tested will be derived from three sources:<br><br>(1) The Academic Word List (sub-lists 1 to 3); (2) selected chapters from the 2nd ed. of McCarthy &amp; O’Dell’s vocabulary book (chapters 8, 9, 23 and 26) which correspond to 61, 64, 69 and 70 in the new 3rd edition; and (3) any vocabulary arising from the pre-midterm composition component (ie definition and causal analysis).<br><br>For grammar, probable test items include those points covered in the Remedial Work component before the midterm, ie relative clauses as used in sentence-length definitions, subject-verb agreement, and pronoun-antecedent agreement. In addition, structures arising from the rhetorical modes dealt with before the midterm in the composition component (definition and causal analysis) could also be included in the exam.", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/150792/9", "user": "user8581", "ts": 1382784201000, "tid": 150792, "pn": 9}}', 1382784201000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1096389', 'stk-abu_khaled', 'ENGL 101', 'srcU', '{"html": "البريزنتيشن اجباري عليه 5% من الكورس و يكون بنهاية السمستر , كل واحد يختار موضوع معين, ممكن تبدأ تفكر لك بموضوع من الحين على رواقه, عندك فتره طويله , لكن لا تعطيه إهتمام كبير حاليا<br><br>حاليا ركز على التاسكات هي المهمه , أول ثلاثه كل واحد عليه 10% والرابع 15%", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-101-oral-presentation/132327/5", "user": "abu_khaled", "ts": 1348220518000, "tid": 132327, "pn": 5}}', 1348220518000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p812604', 'stk-ca2oom', 'ENGL 101', 'srcP', '{"html": "السلام عليكم ورحمة الله وبركاته<br>هذي ياشباب حلول اول ثلاث كويزات ( ويب سي تي )<br>وترى هالدرجات بيدكم لا تضيعونها …<br>وانشالله لا فتحوا لكم الخمسة الباقية ننزل لكم حلولها … بس ذكرونا<br>بالتوفيق 🌹<br><br>​<span data-fid=\"stk-f812604-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f812604-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f812604-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f812604-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f812604-4\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f812604-5\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f812604-6\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f812604-0": {"name": "Water Resources Vocabulary.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/bb1ec53af4ac63960582f1d1444206f75e13de3c01286870acb387cdbd7283b1"}, "stk-f812604-1": {"name": "Water Resources Comp 1.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/491427948dac7554f1bb7db16710c1500da23537fb8d2b78ddc2cbe3c84ea128"}, "stk-f812604-2": {"name": "Water Resources Comp 2.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/773e164505a87bd1bad9628b5446f84dc2504728f4916343ee8f8d6bb30dd9cc"}, "stk-f812604-3": {"name": "CO2 Capture and Storage - Vocab Quiz.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/fa594963680bdb7f0d9c2ebf59cd64b122a48307ceacf4ef19fbb39cb7e103a9"}, "stk-f812604-4": {"name": "Biodiversity Comp 1.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/9fba05121346a99977f1d6e6933d4294c9fdeacefc3258a39a1a1df4e0951661"}, "stk-f812604-5": {"name": "Facts on Biodiversity Vocab Quiz.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/a509ac0a5d0d4e1857eae5a4d08c86e0c257d856526b7bc0fb3dd493a9a21bb6"}, "stk-f812604-6": {"name": "Agriculture and Development Vocab Quiz.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/580ff67bb8b6f62c2cc4b6d6225214327519aed9334b26994886040ff661ff9d"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/104715/1", "user": "Ca2oom", "ts": 1299960008000, "tid": 104715, "pn": 1}}', 1299960008000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p843910', 'stk-user4591', 'ENGL 101', 'srcP', '{"html": "4th Agriculture and Development: Comp 1<br><br>​<span data-fid=\"stk-f843910-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f843910-0": {"name": "4th Agriculture and Development Comp 1.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/94f1dc7b4cb8a9a43dd7f01f55f8ccf2169a0073c5289ec542fb23877b74be64"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/104715/29", "user": "user4591", "ts": 1305295363000, "tid": 104715, "pn": 29}}', 1305295363000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p930805', 'stk-user7909', 'ENGL 101', 'srcP', '{"html": "أولا ملف يحتوي على نبذة عن الاختبار<br><br>ثانيا بالنسبة ل reading<br>الاختبار عبارة عن ثلاث قطع اثنتان منهما مرئية وأخرى مخفية<br>المرئية هنا الأولى عن Fire safety at motor fuel dispensing facilities<br>والثانية عن Disease<br>((على كلام الاستاذ سوف تأتي نفسها في الاختبار))<br><br>ثالثا بالنسبة ل VOCABULARY<br>ملف يحتوي على الكلمات المهمة وهو Academic Word List<br><br>3 ملفات تحتوي على تمارين على الكلمات المهمة وهي SUB-LIST 1 QUIZ<br>و SUB-LIST 2 QUIZ و SUB-LIST 3 QUIZ<br><br>رابعا بالنسبة لل GRAMMAR<br>ملف ل Relative clauses<br>ملف ل Agreement errors<br><br>الرابط من هنا http://www.mediafire.com/?68510kc3r55n687<br><br>لا تنسونا من صالح دعائكم<br>​<span data-fid=\"stk-f930805-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f930805-0": {"name": "Midterm English 101 term 111.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/653d4941781b65935cb296e91b31a12408b3c3fb66d0ae44de6fb5fc403a4204"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/101-111/114904/1", "user": "user7909", "ts": 1321263447000, "tid": 114904, "pn": 1}}', 1321263447000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1190937', 'stk-7_m_o_o_d', 'ENGL 101', 'srcP', '{"html": "تفضل اخي الكريم ،، بس تأكد ان الريدنق تكست على كل السكاشن ، ممكن فيه اختلاف .<br><br>دعواتك …<br><br>في المرفقات 🌹<br><br>​<span data-fid=\"stk-f1190937-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1190937-0": {"name": "101-RQ2txt.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/4b26e61df1aaca2ba88e07514e6aed6ed09a95cb91d0e3dbfb35a40252ce4420"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-101-reading-quize/141082/2", "user": "7_M_o_o_D", "ts": 1361818103000, "tid": 141082, "pn": 2}}', 1361818103000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-grade-p1047430', 'stk-isengineer210', 'ENGL 101', 'grade', '{"method": "avg", "items": [{"name": "REFLECTIONS ON ENGLISH LEARNING", "pct": 5}, {"name": "VOCABULARY QUIZZES", "pct": 5}, {"name": "READING TESTS", "pct": 10}, {"name": "WRITING TASKS", "pct": 40}, {"name": "ORAL PRESENTATIONS", "pct": 10}, {"name": "MIDTERM EXAMINATION", "pct": 15}, {"name": "FINAL EXAMINATION", "pct": 15}], "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-101-an-introduction-to-academic-discourse/120478/5", "user": "ISEngineer210", "ts": 1338288333000, "tid": 120478, "pn": 5}}', 1338288333000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_golden_boy-engl101', 'stk-the_golden_boy', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68428", "n": "Mr. Paul Nicholas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "101 ترم 091 ، درس سكشنين ،، أعلى واحد أخذ b+\n\nوواحد أخذ f ،،\n\nالميزة الوحيدة اللي فيه هي إنه ما يكرف أبد ،،\n\nأذكر الشباب كانوا يكرفون وأنا فاضي على الآخر ،،", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p542136", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nicholas-paul-arthur-bernard/68428/16", "user": "The_Golden_Boy", "ts": 1265997161000, "tid": 68428, "pn": 16}}]}', 1265997161000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-practice-engl101', 'stk-practice', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68428", "n": "Mr. Paul Nicholas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سيء جدا\n\nنزلت معاه 101 وحذفت والله الحمد\n\nاسلوبه سيء وقليل ادب ويحرج الطلاب في وسط قاعة الميدتيرم (سحب ورقة من طالب ونافخ عليه والوقت باقي ما انتهى)\n\nقريدات اححححححححححححححححححححلم والله ما تشم الـc اذا كان مستواك عادي\n\nيخسف خسف مو طبيعي\n\nغثيث وصوته ما ينسمع\n\nالحمد لله ما كملت معاه\n\nوخرو عنه\n\nموفقين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1252230", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nicholas-paul-arthur-bernard/68428/50", "user": "Practice", "ts": 1376194071000, "tid": 68428, "pn": 50}}, {"id": "stk-dr-en94806", "n": "Mr. Jonathan Marquis", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 122 - Engl101\nTerm 123 - Engl102\nTerm 142 - Engl214\n\n1- يشرح شرح مبسط ويعطيك الزبدة ويهمه انك تتعلم وعادي يقعد معاك لين تفهم\n2- ما يهتم بعدد غياباتك ، ما عنده Dn الا لو فليتها بزيادة ( هذا الترم 142 معانا طالب غايب ثلاثة شهور ولا حضر ولا تاسك ، الدكتور اتصل عليه يقول له تعال وقله سوي الريبورت وبنجحك على الاقل وفعلا اعطاه D )\n3- حبيب جدا ولا عمره زعق\n4- متفهم للظروف ويحذف كلاسات كثير اوقات المياجر ويغير اوقات التاسكات اذا طلبنا منه وغالبا يطلعنا بدري\n5- ما تحس بالمادة معاه ابدا\n6- قريداته جدا حلوة وافرج الكلاس 75 في كل التاسكات\n7- انا اشوفه افضل دكتور انقلش بحكم تجربة غيره بترم 131 و 132 و 133 و 141 وكلها دروب ! يمكن لاني جربته قبل عشان كذا ما جازو لي الباقين\n8 - انصح به وبشدة ولا راح تندم بس سوي زي ما يقولك بالملي وبتطلع بقريد ما تتوقعه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1423113", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marquis-jonathan/94806/34", "user": "Practice", "ts": 1438166059000, "tid": 94806, "pn": 34}}]}', 1376194071000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemical_man-engl101', 'stk-chemical_man', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68428", "n": "Mr. Paul Nicholas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "151 term\nEngl101\n\nانحش منه وبالفم المليان اقول لك اذا مافيه الا هو منزل المادة لاتنزلها معاه سيء جدا بخيل بالدرجات D عنده حلاوة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1432046", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nicholas-paul-arthur-bernard/68428/55", "user": "chemical_man", "ts": 1446633566000, "tid": 68428, "pn": 55}}]}', 1446633566000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3628-engl101', 'stk-user3628', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68435", "n": "Mr. Ahmed Daud Ismail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا اخذت معه 101 و 102 وبصراحة ارتحت معاه الرجال فاهم بس يبيلك تعرف وش يبي بالضبط\n\nوحاول انه يعرف انك طالب مجتهد و بين له حرصك و رح له في المكتب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p349932", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ismail-ahmed-daud/68435/4", "user": "user3628", "ts": 1231438171000, "tid": 68435, "pn": 4}}]}', 1231438171000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a7madd-engl101', 'stk-a7madd', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68435", "n": "Mr. Ahmed Daud Ismail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "نزلت عنده eng101 في 091 والتاسك دايم في الكلاس يعطيك الموضوع العام قبل بفتره، ويعطيك الـPrompt في نفس المحاضره اللي تكتبون فيها التاسك… أفشل طريقه في العالم،، يعني اقرا عن موضوع كبير مره وفي الأخير يجيب جزئية غريبة وتافهة نكتب عنها.\nوزيادة على كذا المواضيع دايم تكون غبيه غباء مو طبيعي وراح تشوفون وش أقصد إذا نزلتوا عنده.\n\nما تعرف وش يبغى منك بالضبط، الشرح مشتت وإذا سألته سؤال ما يعجبه راح يعطيك إجابه بايييييخه مره مامنها فايده.\n\nاعطيه C+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p695143", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ismail-ahmed-daud/68435/25", "user": "A7madd", "ts": 1283277626000, "tid": 68435, "pn": 25}}]}', 1283277626000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5891-engl101', 'stk-user5891', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68435", "n": "Mr. Ahmed Daud Ismail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Engl_101 Term:101\n\nبنود التقييم :\n\nالتحضير :\n\nيحضّر كل يوم لكن اذكر مره او مرتين نسى التحضير\n\nطريقة الشرح :\n\nفي البداية بتحس انك ضااااايع في خرايطها 🤪 🤪>>لأنه بعض الأحيان يقول اشياء مهمة عن الأختبار لكن في لحضات يكون الطلاب مو منتبهين جدا لذا الطالب اللي بينتبه معاه ويركز من اول دقيقة لآخر دقيقة في الكلاس هو الطالب اللي بينجح إن شاء الله يعني بعض الأحيان يقول شي يمكن ماتفهمه بالتفصيل لا تسكت روح انت واسأله هل تقص كذا او كذا لما يعطيك بالضبط وش تسوي لأنه بعض الأحيان مايقول كل شي لكن بسؤالك تقدر تأخذ منه كل شي وتقدر تعرف حتى وش بيجيك في الأختبار.\n\nالكويزات :\n\nهذي عاد يبغا لها لأنه يعمل مايقارب 5 كوزات طوال الترم والزين فيه انه يقول لك ترا بكره فيه كوز ومع ذلك بعض الطلاب يجو الكلاس مايدرون انه فيه كوز اليوم لذلك اكرر ركز من اول ثانيه إلى آخر ثاني في الكلاس >> الكوزات تعتبر في بعض الأحيان صعبه شوي يعني فيها تركات لكنها غالبا مايكون مستواها متوسط.\nبس لاتخاف حتى لو جبت العيد في الكوزات >> لأنه يعطيك واجبين (2 Homeworks) في الويب ستي وعندك اربع محاولات لحل الهومورك وعادة ما تكوون سههههههههلة وعن متيريل المدترم >>والمهم هنا انك لو حصلت على درجة حلوه يعدل لك الكوزز لكن بشرط تحصل على درجة طيبه في الفاينل كمان\n\nوهناك التاسكات >>مجرد توضيح لأوريات الفرش مان >>مع إحترامي للجميع 👍 👍\nالتاسكات هي:4 تاسكات يعني اربع إختبارات رايتنق\nوالجميل ايضا ان الدكتور راح يضل يتكلم عن التاسك الأول من بداية الكلاس إلى يجي يوم التاسك\nوتكون الفترة مابين التاسكات فترة مسموح لك تسأل فيها عن أي شي يخطر في بالك عن التاسك الجاي >>وانا من عندي اقول لك كثر أسألة إلى أن تعرف ما هو المطلون وكأنك جالس تناظر إلى ورقة الأختبار لأنه مع هذا الدكتور راح تفلح بس إذا عرفت وش يبي منك\n\nالمياجر:\n\nكومون >> والماتيريال يكون معروف من اول يوم في الكلاس\n\nقطعتين يحددهم الدايركتر للأنجلش من بداية الترم من موقع الجرين فاكتس >>http://www.greenfacts.org<<\n\nوالقطعة الثالثة تكون مجهولة\n\nلأنه هناك ثلاث قطع للأختبار في المدترم>>وطبعا الأختبار كله ريدنق >>Reading\n\nالفاينلات :\n\nثلاث قطع والتفاصيل نفس اللي فوق>> حتى الفاينل المتيريل حقه معروف من اول يوم\n\nوالأختبار Reading فقط\n\nالقريد النهائي:\n\nالقريد النهائي للمدرس:B+ ويستاهل حتى A\nالقريد النهائي حقي :B\n\nالصوت:\n\nالصوت ولله الحمد قوي و واضح لكن بما انه إمريكي >>نيو يورك>> يعني إمريكي اصلي يبغالك تتعود على لهجة الأمريكان لو انك معتاد تسمع للبريطانيين 😏 😏\n\n*** لكن هناك ملاحضة صغيره وهي انه دائما في فمه حلاوة نعناع>> ويتكلم وهي تحت لسانه لذلك بعض الأحيان تكون بعض مخارج الحروف مو واضحة بسبب الحلاوة سابقة الذكر 😆\n\nإضافات :\n\nهذا الدكتور على حسب معاملتي معه محترم جدا وأخلاق وبعض الاحيان يقولون له الشباب عندنا إختبار ويأجل التاسك إلى 3 أيام في بعض الأحيان\n\nومثل مايقولون الطريق إلى قلب الرجل معدته >> أنا القول الطريق إلى القريد الطيب مع الدكتور هو الأوفس اورز 😲 😲\n\n*** وفي الصورة اللي تحت درجات الطلاب في سكشننا والسكشن اللي بعدنا\nوبالتوفيق للجميع :\n\nhttp://up.arab-x.com/Sep11/5Du75342.jpg", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p893997", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ismail-ahmed-daud/68435/31", "user": "user5891", "ts": 1314911638000, "tid": 68435, "pn": 31}}]}', 1314911638000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4665-engl101', 'stk-user4665', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68435", "n": "Mr. Ahmed Daud Ismail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "صراحه انا نزلت عنده 101 ترم 101\nوكنت ليدر على القروب وقال لي الليدر بعطيه درجات اكثر اكيد\nواخرتها d كبر وجهي\nوقسسسم بالله قردياته مزاااجججججيه جدا\nهذا وانا شااد حيلي بعد .\nومره شفته يحوس بسيارته بالمواقف نتعت له ياها وقال لي بعطيك درجه بعد\nخخخخ\nالزبده انه سسسسيء -_-", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1049843", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ismail-ahmed-daud/68435/35", "user": "user4665", "ts": 1338714838000, "tid": 68435, "pn": 35}}]}', 1338714838000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-silver2012-engl101', 'stk-silver2012', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68435", "n": "Mr. Ahmed Daud Ismail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السمستر 132 : المادة انجلش 101\nالتحضير : يحضر يوميا بمناداة الاسماء بالسيريال نمبر وماينسى , واذا كان فيه كوز يحظر من الاوراق نفسها\nطريقة الشرح : المدرس تقريبا مايشرح شيء , واذا شرح يشرح بطريقة غير مفهومة وبتخبط وهو في ذلك يدخل الكثير من التنكيت والسخرية وليس لديه جدية بالشرح لدرجة انك تضيع في كلامه , ميزته الوحيدة انه مايكرفك كثير ولكن هذا قد يؤثر عليك كثير بقريدات الفاينل والمدتيرم .\nالكويزات : كوزاته نفس مستوى المدتيرم والفاينل وتحضرك لهما تحضيرا جيدا , دائما يقولك وش تدرس بالضبط للكويزات والدراسة للكوزات والكورس كامل من ملفات البلاكبورد اما الكتب التي تعطى لك فهي للمرجع وانصح بالرجوع اليها خصوصا في الرايتينق\nالمياجر: من الديبارتمنت\nالفاينلات : من الديبارتمنت\nالقريد النهائي: c+\nالصوت: واضح جدا\nإضافات : من مميزات المدرس انه يستخدم البلاكبورد لكل شيء حتى نتايج الكوزات وغيرها ينزلها اول بأول عن طريق البلاك بورد في اكسل شيت\nوهذي القريدات النهائية لافضل سكشن لاحمد اسماعيل\nGRADE\nB+\nC\nD+\nC\nWP\nB\nC\nW\nD+\nD+\nD\nD+\nC\nC+\nD+\nC\nC+\nC+\nA\nB\nB\nB\nF", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373340", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ismail-ahmed-daud/68435/48", "user": "silver2012", "ts": 1401288237000, "tid": 68435, "pn": 48}}]}', 1401288237000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo-da7m-engl101', 'stk-abo-da7m', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68435", "n": "Mr. Ahmed Daud Ismail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه ENGL 101 الفصل 132\n\nالتحضير :\n\nحسب المزاج بس ما يمر اسبوع الا محضر مرة على الأقل\n\nطريقة الشرح :\n\nماله أي طريقة 😆 كل يوم طريقة مختلفة مرة يعطيك أوراق ومرة يتكلم كلام كثير ولا تدري وش يبي بالضبط\n\nالكويزات :\n\nكويزات الريدينق صعبة شوي بس اذا فهمت تفكيره بتحل صح\n+\nأكثر من مرة جاب قطعة قريبة مرة من الريدينق اللي بالكتاب الأبيض ( ملف الوورد تبع الوحدة ) أدرسه زين وبتستفيد\n\nالمياجر:\n\nمشتركة\n\nالفاينلات :\n\nمشتركة\n\nالقريد النهائي:\n\nB\n\nالصوت:\n\nواضح إلى حد بعيد\n\nإضافات :\n\n* الرجال فاهم مرة ومفيد لو بتسأله سؤال محدد، يعني أحرص تسأله كثير عن أي شي\n\n* فوضوي درجة أولى وهذي أكبر مشاكله لدرجة مرة من الحصص قال أنا نفسي مدري وش قاعد أسوي !\n\n* لأنه فوضوي … اعتمد على نفسك بالاستعداد للميدتيروم والفاينل ( مكتوب بالسيلابس وش المطلوب ) ولا تنتظره يساعدك كثير\n\n* يحط عدد لا نهائي من الملفات بالبلاك بورد، به المفيد والغير مفيد ومهمتك تشوف الزين منهن وتتدرب عليه\n\n* يعطي واجبات بشكل عشوائي وما تدري الا يسألك وين الواجب ؟ بس ما اتوقع فيه ضرر اذا ما سلمت … يمكن يزودك آخر الفصل اذا انت تسلم واجباتك بانتظام\n\n* آخر الفصل يحدد يوم عشان تناقشه بالقريد … نصيحة … لا تفوت اليوم حتى لو تأخر سفرك ورجعتك لديرتك لأنه عادي يصير مخطي وعاطيك قريد أقل من اللي تستحقه بعدين اذا رحتله ينتبه ويعدله !\n\n* هذي القريدات تبع الشعبتين اللي درسهم فصل 132\n\nB\\+ C D\\+ C WP B C W D\\+ D\\+ D D\\+ C C\\+ D\\+ C C\\+ C\\+ A B B B F والشعبة الثانية\n\nF C\\+ D\\+ C\\+ C\\+ C\\+ D\\+ D D C\\+ D C\\+ B\\+ D C D\\+ C\\+ D\\+ W C D\\+ C D B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1376797", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ismail-ahmed-daud/68435/49", "user": "abo-da7m", "ts": 1401817471000, "tid": 68435, "pn": 49}}]}', 1401817471000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mfalkhalifah-engl101', 'stk-mfalkhalifah', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68435", "n": "Mr. Ahmed Daud Ismail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "دكتور درست عنده سمستر 142 …\nEnglish-101\nبصرراحه … كثير كلاام من النوع اللي ماله داعي.\nو يعتمد اعتماد كلي على البلاكبورد . و مواضيع ال writing حقته مو سسهله …\nالحمدلله طلعت منه ب C\n\nSent from my SM-N910C using Tapatalk", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1423986", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ismail-ahmed-daud/68435/51", "user": "mfalkhalifah", "ts": 1439628293000, "tid": 68435, "pn": 51}}]}', 1439628293000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5023-engl101', 'stk-user5023', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68438", "n": "Mr. Christopher Morris", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا درست معه 101 شرحه ممتاز بس شديد في التصحيح مع ملاحظة عدم التحضير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p349884", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/morris-christopher-olsen/68438/3", "user": "user5023", "ts": 1231427638000, "tid": 68438, "pn": 3}}]}', 1231427638000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4251-engl101', 'stk-user4251', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68438", "n": "Mr. Christopher Morris", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انجلش 101\nبالنسبة للتاسكات يقسمها فرست درافت و فاينل درافت خمسين خمسين\nالفرست درافت في الفصل تكتبو\nتقدرتجي قبل الكلاس بكم دقيقة و تبدأ تكتب و نهاية الكلاس تسلم\nو يرجعها الكلاس اللي بعدو و تشوف درجتك و يتكلم عن الاخطاء المشتركة\nو تقدر تاخذ منو feedback\nو الفاينل درافت تسلمو على الويب سيتي\n\nمافي كويزات ولا هوموركات ((غير الكويزات حقت الويب سيتي الكومون))", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p527338", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/morris-christopher-olsen/68438/13", "user": "user4251", "ts": 1264186835000, "tid": 68438, "pn": 13}}]}', 1264186835000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali_easa-engl101', 'stk-ali_easa', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68438", "n": "Mr. Christopher Morris", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أشوف العيال اللي تحت قاموا يتهاوشون ,\nخذوا العلم الأكيد من واحد درس عنده هالترم ,\n\nEnglish 101\nترم 101\n\nالتحضير :\nكل يوم عن طريق الـ Excel , ما أدري كيف بعض الشباب هنا يقولون ما يحضر , يمكن في كورسات الإنقلش الثانية\n\nطريقة الشرح :\nممتعة و كلها تنكيت , بس يقولك إيش يبغى بالضبط و خاصة في الرايتينق تاسك ,\nطبّق اللي يقوله و بتاخذ قريد جميل\n\nالصوت :\nمسموع , لاهو مرتفع و لا هو منخفض , مسموع للكل\n\nالكويزات :\nمتوسطة و تعمد بشكل كلي على قراءتك وفهمك للسورس , ما فهمت السورس ما بتقدر تحل\nو تكون خمس أسئلة أو أقل علما أن هذا السمستر كان موزع الدرجات بحيث يكون على كل كويز 5% و مجموع الكويزات 4 مدري 3 , ناسي والله\n\nGroup Presentation and Discussion Leader :\nفي الكورس 4 سورسات , لكل سورس , يطلب Group Presentation لكل السورسات ما عدا الأول و كل طالب بيقدم بريزينتيشن لوحده غير البريزينتيشنات حقت السورسات\nيعني بـ مجموع : 3 بريزينتيشن مع قروب + 1 لحالك و لك حرية إختيار موضوعك\n\nكتابة الـ writing tasks :\nكل سورس عليه 2 رايتينق تاسك , واحد في الكلاس و غالبا يكون الوقت ضيق و واحد\nتسلمه عن طريق الويت سي تي طبعا بعد ما يعطيك الرايتينيق التاسك الأولى مصححة .\nمجموع كل رايتينق تاسك 10 % , 5% على الرايتينيق اللي في الكلاس و الخمسة الباقية على اللي تسلمها في عن طريق الويب سي تي\n\nالتصحيح :\nلا تنتظر غير حقك و هذا الصح و هذا برضو اللي يضايق بعض الطلاب ,\nيعني ال f عنده و ال D عادي عنده سواء في البريزينتيشن أو الرايتينق تاسك\nو ال A , نادرة لكن موجودة\n\nإضافات :\nموريس يكرف كرف غير طبيعي مقارنة مع بقية المدرسين لكن بتطلع من عنده ممتاز\nفي الكتابة , إذا أنت منزل كورسات دسمة مثل محدثكم , ما أنصح فيه أبدا ,\nإذا تبي ترتاح لا تنزل عنده أبدا , لكن إذا تبي تنكرف نزل عنده , إذا عندك ظروف مثل سفر أو مياجر و كذا ممكن يطول الdeadline لتسليم الرايتينق تاسك الثانية و أذكر مرة سافرت و كلمته قبل ما أسافر عشان كويز , قالي ما عندك مشكلة , بـ أرسله لك على الويب سي تي\n\nالقريد النهائي :\nB\nThank you Mr.Morris for everything\n🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p777922", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/morris-christopher-olsen/68438/27", "user": "Ali_Easa", "ts": 1296271611000, "tid": 68438, "pn": 27}}]}', 1296271611000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_d12-engl101', 'stk-_d12', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68438", "n": "Mr. Christopher Morris", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "101\n\nEnglish 101\n\nالتحضير :\nعن طريق ملف آكسل … بس مآفي شئ عنده أسمة لييت … يعني يآ حآظر يآغآيب 🙂\n\nطريقة الشرح :\nتنكيت + يعطيك الزبدة بالأخير !!\nالصوت :\nمسموع\n\nالكويزات :\nتقرآ آلسورس … تحلهآ بالرآحة آتذكر كل درجآتي فيهآ كآنت حلوه …\nبس بصرآحة عليهآ نسبة كبيييره 15% !!\n\nكتابة الـ writing tasks :\nفي درآفتين … آلآول فالسكشن والثاني على الويب سيتي\nومقسمة 5% 5%\n\nالتصحيح :\nآمم آحسهآ دقيقة شوي آو بالعربي آحلم يمشيلك هههه\nيعني لو آنك مبدع معآه وفي واحد جبت العيد عآدي تشوف F\n\nإضافات :\nبصرآحة … يكرف المدرس مقارنة بمدرسين أخويآي …!\nمثال على كرفة !\nالسورس أنت والقروب الي معآك تبحثون وتجيبونه !\nتسون عليه بريزنتيشن … عآده آوقآتهآ تتداخل مع ميآجر 😦\nآخويآي متسدح على مقآرنة بين كآمري هايبرد وكامري العادية\nوآنآ آكتب عن تأثير الزرآعة في الهند على القلوبل ورمنق !!\nالقريد النهائي :\nبصرآحة آنآ جبت العيييد بالفاينل … وأعطآني آكثر من مآ آستحق !!\nبس آنت وره آنك تشتغل … وهو بيقدر !\n\nوبالتوفيق\n\n3>", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p777959", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/morris-christopher-olsen/68438/28", "user": "_d12", "ts": 1296279765000, "tid": 68438, "pn": 28}}]}', 1296279765000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mahmoud_10-engl101', 'stk-mahmoud_10', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68438", "n": "Mr. Christopher Morris", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "والله يا شباب انا معاه الحين في 101\nبخيييييييييييييييييييييييل جدا في القريدات\nوكويزاته صعبة جدا\nلكن من ناحية الشرح فهو صراحة شريح واخلاق وينكت\nويحضر الى اختبار الميد ترم … بعد كذا ما يحضر نهائيا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p943453", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/morris-christopher-olsen/68438/38", "user": "Mahmoud_10", "ts": 1323185085000, "tid": 68438, "pn": 38}}]}', 1323185085000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3489-engl101', 'stk-user3489', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68439", "n": "Mr. Anthony Donovan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده 101\n\nالتحضير : يحضر كل كلاس في نص الوقت أو في الأخير ولا يدقق على التأخير واجد … وممكن تحضر ميك أب … على الغياب يسمح لك بــ4 غيابات وبداية من الغياب الخامس يبدا يخصم على كل غياب درجة كاملة … يقول هو : إنك إذا كنت قريب من قريد ممكن يرفعك له إذا ما كان عندك ولا غياب أو غياب واحد …\n\nطريقة الشرح : مافي شرح ولا شي … يقولك اكتب وورني وش كتبت ثم يكتب لك هو بارقراف من عنده ويرسله على الويب سيتي …\n\nالكويزات : صعبة نسبيا … وأحيانا للريدينق ما يعطي السورس …\n\nالمياجر: بالنسبة للرايتنق ما يقولك الموضوع عن ايش بس يقولك نوعه (( يعني letter…argument…comparing … الخ … )) وتجي الكلاس ويعطيك الورقة مكتوب فيها الموضوع وتحل … يعني مو مثل البعض يقولك سوها في البيت وجيبها …\n\nالفاينلات : إذا حطها هو تكون صعبة بالنسبة للباقي … لكن أحيانا تصير كومن …\n\nالقريد النهائي: C\n\nالصوت: واضح … ويتكلم عربي بشكل جيد ويعرف كلمات واجد …\n\nإضافات :\n-ماهو من النوع اللي يهتم مرة باللي تقوله أو يعطيك وجه إذا قلتله إن في شي مو عاجبني يقول كلمته المشهور :drop the course …\n\n- عنده ميزة إنه ما يكرف … يعني ممكن غيره يكرفك وبالنهاية نفس القريد …\n\n- يعطيك القريد اللي تستحقه أو أقل بشوي … ما يدف واجد …\n\n- ليس سيء لكن أعتقد أنه يوجد من هو أفضل منه …\n\nفيه شي نسيت أقوله …\n\nإن عنده نظام تحطيم مميز …\n\nوهو أنك مستحيل تشوف اي بلس على أي شي تاخذه …\n\nيعني في الرايتينق ممكن تقول ان ما في أحد مستواه اي بلس … نمشيها …\n\nلكن حتى لو كان الاختبار ريدينق و مالتيبال تشويز … وجبتهم كلهم صح…\n\nيحط لك A …\n\nما يعترف بالــA+ أبدا …\n\nفي حين إن عنده بي بلس وسي بلس ودي بلس …\n\nوأيضا هذا أول دكتور يمر علي في الجامعة يحط لك أحيانا قريد A- يقول هاذي يعني قريبة من البي بلس …\n\nبس مدري شلون يحسبها في الأخير :s …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p364075", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donovan-anthony-francis/68439/3", "user": "user3489", "ts": 1234128240000, "tid": 68439, "pn": 3}}]}', 1234128240000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3033-engl101', 'stk-user3033', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68439", "n": "Mr. Anthony Donovan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "تجربتي معاه فـ 101 أخذتها معاه فـ 081\n\nبنود التقييم :\n\nالتحضير : يومياً … ونادراً ينسى …\n\nطريقة الشرح : عادية جداً …\n\nالكويزات : بالنسبة لـ الريدنق يرسل لك القطعـة ع الإيميل و إنت تطبعها و يختبرك عليها فـ الكلاس … وبالنسبة لـ الرايتنق الموضوع يعطيك هو فـ الكلاس و تحله فـ الكلاس … يعني لازم تجي الكلاس متجهز …\n\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي :أعطيه c+\nالصوت: واضح\nإضافات : بالنسبة لتعاملـه فهو محترم … ولكـن هالمدرس بـارد شوي …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p507929", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donovan-anthony-francis/68439/9", "user": "user3033", "ts": 1261619208000, "tid": 68439, "pn": 9}}]}', 1261619208000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-momanso-engl101', 'stk-momanso', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68439", "n": "Mr. Anthony Donovan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني 101 …\nإذا تبغى قريد بدون ما تكرف , نزل عنده …بس ما يعطيك A+ لو ايش !!\n\nالتحضير : يومياً … بس ما يحاسب على التأخير … وبعض الأحيان ينسى\nطريقة الشرح: عادية … يتكلم حوالي 10 دقايق عن الموضوع وبعدين يخليك تكتب …ويرسل الـ Composition على الـWEB CT .\nالكويزات : كلها Reading و متوسطة الصعوبة\nالمياجر : متوسطة الصعوبة\nالفاينل : متوسطة الصعوبة\nالقريد النهائي : B+\nالصوت : واضح ومسموع\n\nإضافات : خلي معاك معقم لليدين لأنه موسوس من إنفلونزا الخنازير !!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p512043", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donovan-anthony-francis/68439/10", "user": "MoManSo", "ts": 1262174386000, "tid": 68439, "pn": 10}}]}', 1262174386000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4304-engl101', 'stk-user4304', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68439", "n": "Mr. Anthony Donovan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا الحين معاه 101\nمافيه كرف يعني ما كانك منزل انقلش << اتكلم عن نفسي ولا فيه كم دافور يشاركون ويجيبون مشاركاتهم\nمن جهة التحضير اهم شي انك تحضر يعني لدرجة اني يوم من الايام حضرت باقي على الحصة يمكن 10 دقايق بس وحضرني\nالشرح ما فيه لكن التاسكات الرايتنق يعطيك السورس قبلها بيومين ولا ثلاثه ويقول اكتب نوت بالبيت وتعال اكتب التعبير بالحصه\nالكويزات الريدينق انا اشوف ان ما هي صعبه وبعض الاوقات تقدر تساله معنى كلمه ويجاوبك\nالقريد النهائي انا اعطيه b بما انه ما يكرف ذاك الكرف\nالصوت واضح ومفهوم ومثل ما قالوا الشباب الرجال يتكلم عربي زي السلام عليكم يعني اول حصه بتشوف الطلاب مفهين مو مصدقين ان فيه اجنبي يتكلم كذا\nاخيرا\n* مره كان فيه طلاب عند عند باب الكلاس ومزعجين اهلنا كان يدعيهم يقول\"ياا وررع رح هناك\" ما تشوف الا قوة ضحك من الطلاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p512063", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donovan-anthony-francis/68439/11", "user": "user4304", "ts": 1262175960000, "tid": 68439, "pn": 11}}]}', 1262175960000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cortex-engl101', 'stk-cortex', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68439", "n": "Mr. Anthony Donovan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المدرس حبوب ., درست عنده 101\n\nالكلاس سواليف ., يقدّر اللي يتكلمون بطلاقة ., و خصوصاً بلهجة صحيحه ! .,\n\nما يعترف بالـ a+ و غالباً ما يعترف بالـ + .,\n\nطبعاً المادة ع الرايتنق تعتمد ., فبتكتب معاه كثير .,\n\nلكن بالنسبة للتاسكس كلها تكون سهله و المدرس مرة مرة مرة مهوب حق كرف !\n\nموفقين و أنصح به ^ـ^\n\nالمدرس حق سواليف ., تسولف معه و تكثر الكلام و يعطيك قريد ممتاز .,\n\nمتساعد بخصوص القريد ., ممكن تكلمه بالأوفس و يتساعد في أمور كثيرة .,\n\nهذا اللي عندي\n\nموفقين .,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p545172", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donovan-anthony-francis/68439/13", "user": "cortex", "ts": 1266391447000, "tid": 68439, "pn": 13}}]}', 1266391447000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_3zzoz-engl101', 'stk-abu_3zzoz', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68439", "n": "Mr. Anthony Donovan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كلامي عن 101\nباختصار اذا بتحس انك مانت منزل انقلش نزل عنده وانت مغمض\nعيبه الوحيد ان التاسكات تكون في الكلاس مو زي المدرسين الثانيين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p752095", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donovan-anthony-francis/68439/34", "user": "Abu_3zzoz", "ts": 1293349363000, "tid": 68439, "pn": 34}}]}', 1293349363000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-language-engl101', 'stk-language', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68439", "n": "Mr. Anthony Donovan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Engl 101 - term 091\n\nمميزاته : ماتحس انك منزل انقلش ابدا ،، يسامح المتاخرين اغلب الاحيان\nمايعترف بشي اسمه هوموورك ،، التاسكات تكتبها في كلاسه موب عن طريق الويب سيتي\nتنام او تلعب بالجوال ما يقولك شي ،،\n\nعيوبه : خفس جباار في درجات الطلاب ،، اغلب السكشن d و d+ للاسف\n\nوما يشزح الدرس الا في 15 دقيقه باقي الكلاس طقطقه وسوالف بالعربي ولا براكتس\nالنقطه هذي ناس تشوفها ميزه وناس تشوف انه عيب في المدرس\n🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p841582", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donovan-anthony-francis/68439/35", "user": "Language", "ts": 1304773060000, "tid": 68439, "pn": 35}}]}', 1304773060000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar.s-engl101', 'stk-omar.s', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68439", "n": "Mr. Anthony Donovan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اكتشفت انه كان يلعب علينا … وهو نظامه في 102 طلع نفس نظامه في 101\n\nطلع الكوزيات اللي يعطينا اياها هي نفسها ل 101 و 102 هههههههههههههه 😆\nواحد اعرفه نزل عنده الكورسين يقول نفس الكويزات بالضبط\n\nمن ناحية القريدات المدرس زي اغلب المدرسين السكشن اغلبه c و c+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p842202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donovan-anthony-francis/68439/36", "user": "OMAR.S", "ts": 1304881971000, "tid": 68439, "pn": 36}}]}', 1304881971000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6332-engl101', 'stk-user6332', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68439", "n": "Mr. Anthony Donovan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده … 101\n\nما تزهق من حصته … مدرس لسانه طويل لكن حبوب\n\nالصدق انه ساعدني في الدرجات لو انه ما دفني كان عدت المادة\n\nميزته/ انك بترتاح في حصته\nعيبه/ ما فهمت واجد معه يعني احس ان الحصة تروح سوالف …مدري يمكن لان انقلش 101 ما يبغالها شرح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p945342", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donovan-anthony-francis/68439/40", "user": "user6332", "ts": 1323534881000, "tid": 68439, "pn": 40}}]}', 1323534881000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6686-engl101', 'stk-user6686', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68439", "n": "Mr. Anthony Donovan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لا بارك الله بالشيطان …\n\nاخذت معه قبل سنة ونص 101\n\nالكلاس فلة لانه ما يبي شي فـ يقضيه سواليف وتنكيت …\n\nالتاسكات بالكلاس تكتبهن …\n\nاخر الترم 3 طلاب b واحد f والباقين بينهم\n\nبحر الـ c على ما قالوا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p985761", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donovan-anthony-francis/68439/46", "user": "user6686", "ts": 1329226743000, "tid": 68439, "pn": 46}}]}', 1329226743000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s2010xxxxx-engl101', 'stk-s2010xxxxx', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68439", "n": "Mr. Anthony Donovan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بحسب تجربتي معه في انقلش 101 كان سيء جدا … لا شرح ولا درجات … اذا كان ما يهمك القريد نزل عنده لانه ما يكرف ابدا … لكن بالدرجات ما يدف … والشرح ما حولك احد … القريد النهائي : D +", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1030356", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donovan-anthony-francis/68439/47", "user": "s2010xxxxx", "ts": 1335739090000, "tid": 68439, "pn": 47}}]}', 1335739090000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-industrialawi-engl101', 'stk-industrialawi', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68439", "n": "Mr. Anthony Donovan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا عنده الحين انجلش 101 ترم 121\n\nمن الاخير اذا تبغى تتعلم انجليزي ابعد عنه ولا تخليه الا اخر خياراتك … واذا تبغى واحد ما تحس انك منزل انجليزي اساسا نزل وبقوووة هههههههه\n\nشرحه تعبااااااان لدرجة ماحد جاب في السكشنين حقه b في المدتيرم وسكاشن مدرسين ثانية عندهم b كثيييير 😦\n\nالتقييم : C", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1141580", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donovan-anthony-francis/68439/48", "user": "Industrialawi", "ts": 1355564340000, "tid": 68439, "pn": 48}}]}', 1355564340000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-asmarica-engl101', 'stk-asmarica', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68439", "n": "Mr. Anthony Donovan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "141 - ENGL 101\n\nبنود التقييم :\n\nالتحضير :\n\nيوميا في نهاية المحاضرة\n\nطريقة الشرح :\n\nسيء جدا تقريبا ما في شرح و دائما يقول للطلاب اعتمدوا على نفسكم\n\nالكويزات :\n\nمتوسطة , ما يعطيك القطعة قبل الكويز على عكس مدرسين ثانيين و نفس الشي في الرايتنج تاسك ما تعرف المواضيع غير وقت الاختبار\n\nالمياجر: common\n\nالفاينلات : common\n\nالقريد النهائي: C+\n\nإضافات : المدرس حبيب و حصته حلوة و دمه خفيف و يحب يساعد الطلاب اللي يحسهم مهتمين والكورس معاه خفيف جدا لكن مشكلته بالقريدات , ما يعترف بال A+ ابدا يعني لو تجيب فل مارك راح تاخذ A , بالنسبة لي المدرس مو سيء لكن ما اتوقع اني اسجل معاه مرة ثانية , خليه اخر الاحتمالات!\n\nهذه درجات سكشنا\n\nD\nD+\nD\nC+\nC\nD+\nC\nD+\nD\nD+\nD\nD\nW\nC\nC\nD+\nC\nC+\nC\nD\nB\nB+\nA\nB+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420512", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donovan-anthony-francis/68439/58", "user": "Asmarica", "ts": 1421662961000, "tid": 68439, "pn": 58}}]}', 1421662961000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3554-engl101', 'stk-user3554', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68440", "n": "Mr. Roger Horn", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "والله انا درست عنده 101 وكان يكرفنا بالهوموركات يعني ما ترتاح معه ,\n\nوبالنسبة للتحضير طبعا يحضر , والشرح يجيب النوووووم وصوته هادئ وضعيف …\n\nبالنسبة للقريدات انا اشوف انه يعطيك حقك وبس …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p379338", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/horn-roger-alan/68440/5", "user": "user3554", "ts": 1236727248000, "tid": 68440, "pn": 5}}]}', 1236727248000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mmkhoj-engl101', 'stk-mmkhoj', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68440", "n": "Mr. Roger Horn", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنصحكم لحد ينزل عنده 101\n\nسلبياته اكثر من ايجابياته ويلخبط بكلامه …مثلا يكون بيتكلم في شي مهم تلاقيه شوي غير الموضوع وتكلم في شي ثاني\n\nلكن اللي ما يلاقي الا هو …انا اعتبره يمشي الحال\n\nلكن نشوف القريد ؟!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p528104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/horn-roger-alan/68440/11", "user": "mmkhoj", "ts": 1264330239000, "tid": 68440, "pn": 11}}]}', 1264330239000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_28-engl101', 'stk-_28', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68440", "n": "Mr. Roger Horn", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني 101 وكنت خايف منه على كلام الشباب\nيعيك حقك واذا كنت قريب من القريد اللي بعده يعطيك اياه\nيحب التواصل عن طريق الايميل >>>> بس انها فاتتني\nما يكرف بالحيل\nكتابة التاسك عنده بالكلاس بس تجيب معك نوت\n\nمشكلته كلاسه مايقفل ويجونك طلاب البروموشن ويرفعون ظغطك\n\nتقييمي له :b", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p546366", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/horn-roger-alan/68440/17", "user": "_28", "ts": 1266578315000, "tid": 68440, "pn": 17}}]}', 1266578315000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_hmh-engl101', 'stk-_hmh', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68440", "n": "Mr. Roger Horn", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معاه 101 في 091\n\nالتحضير : كل كلاس وما يحب احد اتأخر لكن احضرو\n\nطريقة الشرح : زي كل مدرس انقلش ممل ونكته بايخه\n\nالكويزات : ازا ذاكرت مذاكرة عادية تاخد الدرجة كاملة\n\nالمياجر: الربورتات في الكلاس اديك تلميح عن الموضوع او\nاديك 3 مواضيع اقلك وحده منهم تجي\n\nالقريد النهائي: B\nالصوت: لازم تركز عشان تفهم معاه صح\n\nإضافات : هو مو مرة ممتاز بس اذا كانت لغتك فوق المتوسطة بشوي\nواشتغلت معاه كويس بتاخذ b او اعلى", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p606334", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/horn-roger-alan/68440/21", "user": "_hmh", "ts": 1273852726000, "tid": 68440, "pn": 21}}]}', 1273852726000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4626-engl101', 'stk-user4626', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68440", "n": "Mr. Roger Horn", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "و الله إنه ابداع\nالترم الماضي جبت العيد في كل المواد باستثناء الانجلش101 معاه\nصراحة مع انه غثيث و ثقيل دم لكن شغله واضح و يقولك ايش لازم تسوي لا و يموت في الايميل\nكنت كل يومين أدور حجة و أرسله ايميل عشان يعرفني و فعلا طلعت بــــb\nمع اني جايب العيد في المدتيرم و الفاينل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p607261", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/horn-roger-alan/68440/22", "user": "user4626", "ts": 1273942848000, "tid": 68440, "pn": 22}}]}', 1273942848000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-al-matrafi-engl101', 'stk-al-matrafi', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68440", "n": "Mr. Roger Horn", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "هالمدرس نزلت معه 101 و102 المدرس ممتاز وتاخذ عنده قريد حسب شغلك بس حاول تشبكه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p747959", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/horn-roger-alan/68440/24", "user": "Al-matrafi", "ts": 1292850319000, "tid": 68440, "pn": 24}}]}', 1292850319000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3630-engl101', 'stk-user3630', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68440", "n": "Mr. Roger Horn", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انجلش 101 و 102\n\nالتحضير : يشيك على السريع بالاسم\nطريقة الشرح : يحط المعلومات في السبورة قبل لتجي ويشرح بالعموم\nالكويزات :متوسطة ويعطيك الماتيريال تاخذه للبيت\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:c\nالصوت:واضح\nإضافات : مدرس يعطيك حقك بالضبط وممكن يزيدك وممكن ينقصك على حسب حرصك معه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p782676", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/horn-roger-alan/68440/27", "user": "user3630", "ts": 1296992725000, "tid": 68440, "pn": 27}}]}', 1296992725000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5635-engl101', 'stk-user5635', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68440", "n": "Mr. Roger Horn", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "101\n\n102\n\n214\n\nاشوف انه من افضل السيئين واغلب الكرف اللي الشباب يشتكون منه بالكلااااس وبس طبعا ماعدا الريبورت لانه يبي له بحث وتدريب لكن برضو الدرافت حق الريبورت تكتبو في الكلاس ويقيمك على تعبك مو ع اساس انك متحدث فصيح على قولتهم .\n\nمثل ماقال واحد من الشباب اذا لغتك جيدة ((و عندك ثقافة او لقافة)) نزل معاه يحب السوالف واللي يعطيه جوه ويضحك على النكت اللي يقولها بس مو تسمجها وتخليه هو والكلاس كلو يكرهونك هههههههاي.\n\nشغله نظيييف ومرتب من اول السمستر تعرف وش بتسوي كل اسبوع ,وكل يوم تعرف بالضبط وش بتسوون الكلاسين الجاية.\n\nمو بس يحب الا يموت بالاوفيس اور والايميلات لو بس تستفسر عن شي وانت اصلا عارفو.\n\nانا كان يعطيني درجات مو بذاك الزود لكن مع الفاينلات الحمد لله ترتفع شوي .\n\nالقريد النهائي لكورساتي معاه +c\n\nاسف ع التاخير والعذر والسموحة .\n\nملاحظة اخيرة :: انا نزلت معاه عشان ارتاح والحمد لله كانت كورساته ممتعة لحد ما ومريحة جدا لانه متفهم ومرن نوعا ما . (( اعجبتني لحد ما ونوعا ما خخخخ )) واخر شي ما اشوف انو كريف ابدا .\n\nخذوه واهذرو معاه وتواصلو وسوو اللي يبي وفالكم +b بدون طمع .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p788812", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/horn-roger-alan/68440/29", "user": "user5635", "ts": 1297612703000, "tid": 68440, "pn": 29}}]}', 1297612703000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tryagain-engl101', 'stk-tryagain', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68440", "n": "Mr. Roger Horn", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "دكتور Roger Alan Horn\nEnglish 101 & 102\nTerm 151 & 152\n\nالتحضير : ما يحاسب على التأخير بشكل كبير ويحفظ الأسماء من ثالث حصة أو ثاني حصة وفي آخر السمستر يحذف غياب أو غيابين … بشكل عام متساهل من ناحية التحضير\n\nطريقة الشرح : لا يعلى عليها … يشرح بسلايدات خاصة فيه هو مسويها … مو سلايدات القسم … ومرتب ومنظم بشكل كبير … ويموت في الهانداوتات 🙂 … يعطيك ورق كثير مهم ويشرح عليه … وممكن تطلع بنهاية الكورس بأكثر من 40 ورقة …\n\nالكويزات والرايتينج تاسك :\nفي 101 كان يعطينا 3 مواضيع قبل 48 ساعة … وتحضر عليها وهو يقلك إنو رح يختار واحد ويجيبه … لكن كان دائماً يسوي نفس الحركة ويجيب الثلاث مواضيع وإنت إختار اللي يعجبك … فحاول تحضر بشكل ممتاز وتعال إلصق التاسك اللي كتبتو على الورقة وإطلع … وجبت معاه قريدات طيبة \" بين الـ A والـ A+\" في الأربع رايتينج تاسك … بالنسبة لـ 102 إختلف الوضع شوي لأن الكورس أصلا مختلف … وتصحيحه أشوفه متساهل ولا بأس به …\nبالنسبة لكويزات الريدينج … في 101 أتذكر كان يعطينا الكويز قبل الكويز نحضر عليه … وكانت كويزاته متوسطة مائلة للسهولة … ونظامه في القريدينج نوعا ما حلو لأنو ما عندو A …\nاللي ما يغلط ولا غلط A+ واللي يغلط غلط واحد برضو A+ لكن غلطين تصير B+ وثلاث أغلاط B وهكذا …\n\nالصوت : واطي شوي لكن رح تتعود عليه …\n\nإضافات خاصة بـ 101 :\n- الدكتور يحب الطالب المهتم … حاول ترسل رسائل على إيميله الخاص مو إيميل الجامعة عشان يعرف إنك مهتم …\n- الدكتور يحب الطالب اللي يجيب معاه هايلايتير 🙂\n- نظام الدكتور خطر شوي … لأنو ما عندو طلاب في الوسط … تلاقي السكشن مقسم قسمين … قسم A و A+ … وقسم C و C+ … وصورته عنك ما تتغير طول السمستر … ياخذ عنك فكرة في البداية … فحاول إنها تكون فكرة طيبة … بمعنى آخر قريدات الرايتينج تاسك قد لا تتغير بشكل كبير طول السمستر … فحاول تبدع بأول رايتينج تاسك …\n- الواجبات \" أعتقد \" ما عليها شي … لكن حاول إنك تسلمها بوقتها وحاول إنها تكون خالية من الأخطاء لأنو رح يحطك ببالو إنك طالب ممتاز …\n- ركز بشكل كبير على الميد والفاينال وحاول إنك تجيب فيهم A أو A+ … لأنو مهما كانت درجاتك سيئة في التاسكات أو الريدينج كويز … لو شافك ممتاز في الميد و الفاينال … رح يساعدك بشكل كبير في الفاينال قريد …\n\nإضافات خاصة بـ 102 :\nنفس الملاحظات اللي فوق … لكن مع إضافة خاصة بالريبورت :\n- سجل كل شيء يقلك عليه … كل شيء … ورح تطلع بقريد يا A او ِA+ من الريبورت …\nالدكتور أحلى شي فيه إنو ما يخليك تضيع أبدأ … دائماً يقلك الأشياء اللي لازم تسويها بحذافيرها … ومتواصل بشكل كبير على الإيميل والبلاكبورد …\n\nخاتمة …\nأنصح فيه إذا كنت ناوي تاخذ الكورس بجد واجتهاد … وفالك الـ A او الـ A+ …\nلكن إذا لا … لا تستبعد إنك تطلع من الكورس بـ D+ أو C …\n\nحالياً انا مسجل عندو كمان 214 سمستر 161 …\nوحسب ما يقول إنو ترم 161 آخر ترم له …\n\n🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1451372", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/horn-roger-alan/68440/47", "user": "TryAgain", "ts": 1465395038000, "tid": 68440, "pn": 47}}]}', 1465395038000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a_o_s_ll-engl101', 'stk-a_o_s_ll', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68441", "n": "Mr. Timothy Nelson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لبيه يا نيلسون ❤️\n\nبنود التقييم :\n\nالكورس 101 …ترم 111\n\nالتحضير : يحضر باخر الكلاس وكثيرا ما يسحب\nطريقة الشرح : يفتح الويب سيتي ويشرح ويستخدم السبورة\nالكويزات : كويزاته ماهي سهله…صعبه حبتين .,لكنه ينزل كويزين\nعالويب سيتي واغلبنا سحب ولا يحلها وبالاخير اكتشفنا ان الكويزات منها خخخخخ\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح\nإضافات : مدرس كندي رهيييييييب …بعيد عن الكرف وبنفس الوقت يشرح وتستفيد منه\nتصحيحه تتعب وانت تقول بطل…واذا حس ان الشعب خبصوا بالتاسك …عطاهم فرصه للمراجعه والتصحيح من 3\nبس فيه نقطه…حاول تتبع رأيه بالتاسك… يعني هو يشرح ويقول فيه طريقتين للكتابه …وكلهم صح\nبس انت حاول تكتب باللي يفضلها …انا لاحظت انها تفرق معه بالتصحيح\n\n+\nتو اليوم صاقعني up grade", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p964743", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nelson-timothy-andrew/68441/22", "user": "A_O_S_ll", "ts": 1326297607000, "tid": 68441, "pn": 22}}]}', 1326297607000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-slooom-engl101', 'stk-slooom', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68441", "n": "Mr. Timothy Nelson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ENGL 101 - Term 121\n\nالتحضير : أول أسبوع يحضر ، و باقي الأسابيع أحيانا تمسك معه يحضر و الأغلب لا 😆 ، طبعا وقت المياجر ما يحضر 🤴 ، بالنسبة للتأخير لو تجي قبل ما يخلص الكلاس بخمس دقائق حضرك ❤️\n\nطريقة الشرح : سواليف 🤠 ، يشرح الـ Writing و غيرهـ نادراً ما يشرح ، يعطيك طريقة الكتابة من ناحية التنظيم و المطلوب و متشابهه الطريقة في جميع الـ Writings .\n\nالكويزات : Reading : أربع كويزات ، 2 unseen و 2 يعطيك اياها قبل الاختبار ، متوسطة الصعوبة.\n\nVG : أول كويز كان سهل جداا ، الفوكاب من الموقع اللي حاطه في Web CT و القرامر كان سهل ، بالنسبة للثاني كان أغلبه Grammer من التوفل ، سهلع نوعا ما إذا ذاكرت و الفوكاب كان سهل جدا ، بشكل عام الكويزين كانت سهلة . ❤️\n\nWriting tasks : هذا الأهم و عليه 40 % ، بالنسبة للتاسك الأول أتذكر عطانا ثلاث مواضيع و قال اختر واحد و إكتب عنه ، الثاني عطانا قبل الاختبار لستة مكونة من 10 مواضيع تقريبا و قال بيجي لكم اثنين في الاختبار اختاروا منها ، الثالث قال اكتبوا عن أي موضوع ، الرابع قال اكتبه في البيت و سلمه على دفعات ( intro - bodies ) و يعلمك الأخطاء ثم تعدلها ، و تسلمه مرة ثانية كامل بعد التعديل و يعطيك قريدين ( قبل التعديل و بعد التعديل ) . 🤠\n\nبالنسبة لطريقة تصحيحه فيدقق على الاخطاء الجوهرية مثل الأفعال او تحط جملة ناقصة ، إذا اتبعت نفس اللي شرحه لك فأقل شئ بتاخذه C و إن كانت كتابتك بسيطة مرة ، اما إذا أضفت أشياء بتزيد من درجتك بالتأكيد .\n\nPresentation : طالما إنك سويته ما أنت ماخذ F ، و يقيمك حسب انطلاقك في الكلام ، و يصور لك اياه في حالة إنك بتشوفه 🥰 .\n\nالمياجر: Common midterm\nالفاينلات : Common final\nالقريد النهائي: A\nالصوت: واضح جدا\nإضافات : الكلاس ممتع و المدرس فيه روح الفكاهة و خفيف دم 😆 ، طالما إنك بتسوي نفس ما يقول إن شاء الله بتطلع بقريد كويس 🤠\n\nبالتوفيق إن شاء الله ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1154107", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nelson-timothy-andrew/68441/28", "user": "Slooom", "ts": 1357236705000, "tid": 68441, "pn": 28}}]}', 1357236705000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ad0rs-engl101', 'stk-ad0rs', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68441", "n": "Mr. Timothy Nelson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده 101 سمستر 121\nالتحضير :\nاخر الكلاس ومعظم الأربعاءات ما يحضر\nطريقة الشرح :\nشرح بسيط بس الكورس اصلا ما يحتاج له شرح\nالكويزات :\nمتوسطة اقرب للسهولة\nالمياجر:\nكومون ميدترم\nالفاينلات :\nكومون\nالقريد النهائي:\nA+\nالصوت:\nكندي واضح\nإضافات :\nالدكتور ميزته انه ما يكرف ابد انا اخذت عنده b رغم اني كنت متوقع اكثر بس افرج كلاسنا كان عالي\n+\nدكتور الانجلش الوحيد اللي ما هو سامج مررة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1167464", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nelson-timothy-andrew/68441/30", "user": "ad0rs", "ts": 1358819912000, "tid": 68441, "pn": 30}}]}', 1358819912000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullatif1994-engl101', 'stk-abdullatif1994', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68441", "n": "Mr. Timothy Nelson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انجلش 101 سمستر 121\n\nالتحضير : يحضر نهاية الكلاس غالبا …\nطريقة الشرح : يشرح ومسوي فلاوي … بس هو سامج .\nالكويزات : عطانا 4 كويزات … من عنده … متوسطه\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: D+\nالصوت: واضح\nإضافات : قال بعطيكم اب قريد اذا غبتو اقل من 5 … غبت بس يوم واحد ونقصني ربع درجه ع القريد الي بعده ولا عطاني اياها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1298374", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nelson-timothy-andrew/68441/31", "user": "Abdullatif1994", "ts": 1385920513000, "tid": 68441, "pn": 31}}]}', 1385920513000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mhm14-engl101', 'stk-mhm14', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68441", "n": "Mr. Timothy Nelson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "English 101 - term 131\n\nالتحضير: يوميا توقع آخر الكلاس، لو جيت متأخر يحضرك عادي، متساهل بالتحضير\n\nطريقة الشرح: سوالف 🙂 … يشرح لك الأشياء المهمة في القراءة و الكتابة و القرامر … حسيته عادي بس استفدت منه\n\nالكويزات: كان في 4 رايتنغ تاسك و 4 كويزات ريدنينغ و 2 قرامر … كويزات الريدنغ ما يعطيك فكرة عن النص اللي بتختبره … كان بعض الأساتذة يعطوا طلابهم النص في الحصة اللي قبل الكويز بس هذا ما كان يعطينا و لا يلمح بشيء عنه\nو في الرايتنغ علشان تجيب درجة زينة أمشي على الخطوات اللي هو يقولها و الطريقة اللي تعجبه هو\nالقرامر من البلاكبورد بالنص تقريبا\n\nالمياجر و الفاينلات : لا شيء يُذكر\n\nالقريد النهائي: B\n\nالصوت: واضح و لهجتة حلوة\n\nإضافات: يحب شيء إسمه بلاكبورد و كل شغله عليه\nحسيت إنه سوا فينا مقلب، كان يقول اللي يتابع البلاكبورد و يشتغل عليه أول بأول و ما عنده غيابات بعطيه أب قريد و لما رحت له آخر الترم ما شفت شي\nيقول لو أعطي الطلاب كلهم A+ لازم أنزل درجاتهم للـ C+ - C\nيريحك واجد و ما تحس إنه عندك انجلش بس في النهاية بيعطيك C-C+\nأنصح فيه إذا ما يهمك القريد بشكل كبير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1370423", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nelson-timothy-andrew/68441/38", "user": "MHM14", "ts": 1400932649000, "tid": 68441, "pn": 38}}]}', 1400932649000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-breaktheunbreakable-engl101', 'stk-breaktheunbreakable', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68441", "n": "Mr. Timothy Nelson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 152 - أخذت عنده 101\n\nالتحضير : متساهل وتحضر بنفسك أي وقت وعادي الميك أب في كلاس ثاني وكثير من الشباب يحضرون أخوياءهم لأن الورقة تمر على الكل\n\nطريقة الشرح : يحب يستعمل البلاك بورد فكل شيء وينزل عليها أشياء كثير حيل. شرح حقيقي 5 أو 10 دقائق والباقي سوالف حول المنهج وخارجه ههههه. كلاسه خفيف وممتع وما تحس بالإنجليزي أصلا. مرات لو بيشرح شيء يستعمل السبورة برضو. نصيحتي لك الكلام اللي يقوله في الشرح مهم جدا لأن لو اتبعت طريقته بتحصل درجات عليها أما لو تكيس من عندك أو من التحضيري بتطير درجاتك.\n\nالكويزات : كومن. < ديبارتمت وسخ يحب يتدخل في درجات كل الطلاب.\nالمياجر: ميد كون\nالفاينلات : كومن\n\nالقريد النهائي: أعطيه b. درجتي اللي حصلتها عنده b 🙂\nهاي درجات سكشني\n\nالصوت: مسموع وجيد\nالدكتور يعطيك فكرة كاملة عن اللي بتكتبه في الرايتنغ تاسك فانتبه معه. حنا كنا نتعلم على كم موضوع طول الرايتنغ تاسك وبالأخير جتنا نفسها في الاختبار. تصحيحه ممتاز فحاول تكثر من التجارب معه عشان تعرف اللي يعجبه صح وتجيب درجات حلوة.\nيعطي أيام فاضية وإذا عند الطلاب مياجر متسامح ويمشيهم 🚬", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449826", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nelson-timothy-andrew/68441/39", "user": "BreakTheUnbreakable", "ts": 1463766606000, "tid": 68441, "pn": 39}}]}', 1463766606000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rytamu-engl101', 'stk-rytamu', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68442", "n": "Mr. Kevan Moore", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "101 , سمستر 071 …\n\n…\n\nالتحضير : أذكر إنه ينادي على الأسماء وأحيانا يحضركـ على شغلكـ اللي سلمته لإياهـ واللي بيرجعه لكـ …\n\n…\n\nطريقة الشرح : يفهمكـ كل شيء يبيه بشكل بسيط وواضح ما تحتاج بعدهـ للسؤال كما أنه متساهل , إضافة إلى إنه منظم جدا جدا جدا وهادئ , وهالشيء كوّن هيبة عند هالشخص , الشيء السلبي فيه إنه يقول اكتبوا بالكلاس وسلموهـ على طول …\n\n…\n\nالكويزات : ما أذكر …\n\n…\n\nالمياجر: أتوقع إنه كان كومن , بس إنه عطانا أوراق استعدادية …\n\n…\n\nالفاينلات : طلب مننا نقدم برزنتيشن كل شخص لحاله …\n\n…\n\nالقريد النهائي: أعطيه c …\n\n…\n\nالصوت: واضح وهادىء\n\n…\n\nإضافات : أنا أخذت d وكنت أنواع التنح ومع هذا ما كنت راضي لأن مستواي أفضل من كذا بكثير بس ما كنت معطي الكورس حقه وأنواع السحب , أحسبها مثل إنقلش الأوريا , فـلا تنظرون لحكمي عليه وتراني ناسي أشياء كثير بصراحة …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p543473", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/moore-kevan/68442/11", "user": "Rytamu", "ts": 1266205697000, "tid": 68442, "pn": 11}}]}', 1266205697000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6384-engl101', 'stk-user6384', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68442", "n": "Mr. Kevan Moore", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "هذا مزاجي جدا جدا\nالله لا يوفقه , انا عنده الان 101 وبصراحة تعامله في الاوريا يختلف عن الجبل\nاذا جاء للتدريس يكشر عن انيابه\nكل السكشن خاسف بهم\nانا واعوذ بالله من كلمة انا جبت a في ميدتيرم الريدينق\nما تقدر تحضر عنده في سكشن ثاني\nباختصار ------------------------------f---------------------", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p608295", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/moore-kevan/68442/16", "user": "user6384", "ts": 1274028553000, "tid": 68442, "pn": 16}}]}', 1274028553000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-student_nz-engl101', 'stk-student_nz', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68442", "n": "Mr. Kevan Moore", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "101\n\n^^^^^^^\nمعليش انت كذاب\nما عنده الا سكشن واحد 101\nوالشي الثاني ما في احد في السكشن اخذ في المد تيرم a\n\nشكرا\n\nالتحضير :\nكل حصة\n\nطريقة الشرح :\nيشرح عن ايش بيكون التاسك والعادة يقول لنا اقرى التعليمات وخليك معاها يعني اعرف عن ايش بتتكلم و ايش يبغى التاسك تكتب فيه يعني اقرى الورقة كلها ويكون في وقت الكلاس\n\nالكويزات :\nيعني يجي واحد سهل واحد صعب\n\nالمياجر والفاينلات\n\nكومن\nالقريد النهائي اعطيه b\n\nالصوت: واضح وهادي جدا\n\nوبعض الايام يقعد ينكت لكن مو الكل يضحك\n\nإضافات :\n\nاذا ما تبي تنكرف نزل عنده\nيعني ما في واجبات ما في اي حاجة تسويها في الغرفة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p641308", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/moore-kevan/68442/17", "user": "student_NZ", "ts": 1277148815000, "tid": 68442, "pn": 17}}]}', 1277148815000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5800-engl101', 'stk-user5800', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68442", "n": "Mr. Kevan Moore", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا الان منزل عنده 101 , ترم 101\nوالله استااذ رائع جداً , ومنظم\nيعني يعطيك الخطة اللي راح يمشي عليها السكشن من بداية الترم , لكل كلالاس\nويبين لك انه في اليوم الفلاني فيه كويز ريدينغ او رايتنغ , او اليوم الفلاني off … وهكذا\n\nكويزاته سهلة الى متوسطة , يعني بالراحة تجيب 80% اذا كان كويز ريدينج … لكن بشرط تقرأ التاااسك قبل\nاما كويزاته تبع الرايتنغ , سهله الى متوسطة ايضاً , لكن دقيق جدا في التصحيح .\nيعني تأخذ اذا حليت اي كلام d الى c\nواذا اجتهدت وراجعت في البيت , ممكن توصل a+ بالراااااااااااحة .\n\nالاستااذ هادئ في الكلاس\nمن بداية الترم الى الآن … يمكن اعطانا فقط 4 واجبااات ،،\nوكلها على ورق … يعني ما فيه شئ اسمه واجب على الويب ستي\n… اللي على الويب ستي يقول هذه لكم انتم عشاااان تقيمون انفسكم\nيقول : انا ما راااح اطالع فيها …\n\nاي سؤال , اي استفسار\nاحنا حاضرين ،،", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p743952", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/moore-kevan/68442/23", "user": "user5800", "ts": 1292330945000, "tid": 68442, "pn": 23}}]}', 1292330945000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-imported_kaka_22-engl101', 'stk-imported_kaka_22', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68442", "n": "Mr. Kevan Moore", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ُEngl 101\n\nالتحضير :\nيحضر يوميا بنفسه\n\nطريقة الشرح :\nشرح بسيط , جدا مااشوف شي مميز يعني\n\nالكويزات :\nشديد شوي بالتصحيح + اذا كتبت له قطعة بطريقة عادية (قرامر صحيح وسبلينق) يعطيك من دي الى سي لانه يبي فلسفة زايدة يعني مايبي الطرق التقليدية مثل\nA is bigger than B … الخ\n\nفيه الريدنق اشوفه يجي من سهل الى متوسط لانك اذا كنت قارئ الكور ريدنق وفاهمه تجيب درجة حلوه\n\nالقريد النهائي: C+\n\nالصوت: واضح\n\nإضافات : اذا جيته بالمكتب يتعاون معك لكن مرة او مرتين <<<< ماهي حلا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p764830", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/moore-kevan/68442/30", "user": "imported_KAKA_22", "ts": 1295226496000, "tid": 68442, "pn": 30}}]}', 1295226496000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moka_me-engl101', 'stk-moka_me', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68443", "n": "Mr. John Williams", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا عنده الحين 101\n\nالتحضير : بداية كل كلاس و اذا تتاخر فوق 10 دقايق يعتبرك غايب\nطريقة الشرح :ممتاة قبل كل تاسك يقول لك ايش الموضوع كامل و يشرح لك كيف تكتبه\nو اذا بس تتبع كلامه اعتبر الc في جيبك و الباقي عليك انك تبدع فيه\nالكويزات : متوسطة و قليلة بس هوموركاته تقريبا 10 طول السمستر\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي:a\nالصوت:واضح\nإضافات : صار له يدرس فوق 40 سنة!!!\nو تخليو صار له تقريبا 20 يدرس في الجامعة\nيعني يعرف كل صغيرة و كبيرة عدنا و يعرف ايش يحتاج الطالب\nومايحب الناس اللي تلف و تدور معاه اصلا\nيحب الطالب يكون منتظم في كل شي يعني لو مثل تنسى تجيب معاك سورس للكلاس يزعل عليك\nو يفكرك طالب مهما\nو احنا الحين على نهاية السمستر بس شغله احسه متوسط مو زي باقي الاساتذة يكرفو كرف مو طبيعي\nو فيه شي حلو و مميز انه يرجع التاسك للطالب بعد مايكتبه في الفصل و يحط عليه ملاحظات\nو يخلي الطالب يكتبه مرة ثانية بالكمبيوتر و اذا سوى الطالب اللي يبيه يزيده غريد\nو الحين انا منزل معاه 102 و ياريت اللي اخذو معاه 102 او 214 يعطونا معلومات اكثرعنه\nو بالتوفيق للجمع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p518435", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/williams-john-christopher/68443/11", "user": "Moka_ME", "ts": 1262868298000, "tid": 68443, "pn": 11}}]}', 1262868298000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-unbeatable-engl101', 'stk-unbeatable', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68443", "n": "Mr. John Williams", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : يحضر بداية كل محاضرة\nطريقة الشرح : { أخذت معه eng101 , أول ربع ساعة يقول لك وش يبي و الطريقة بعدين يبدأ يسولف , و سوالفة حلوه و ممتعة , هالشخص ذا كنز معلومات متحرك , يعرف كلش !! , و يشدد على الفورمات يعني ممكن مايعطيك قريد على شي سلمته لأنك ماسويتة مثل مايبي , ومريح مرره , مايتعامل بالويب سيتي كثير وكلش يتسلم بالأوراق }\nالكويزات : ما أذكرها =)\nالمياجر: كوممن\nالفاينلات : كوممن\nالقريد النهائي: B+\nالصوت: واضح\nإضافات : نزل عنده وبتستمتع بسواليفة <3 ,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p755258", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/williams-john-christopher/68443/30", "user": "Unbeatable", "ts": 1293755476000, "tid": 68443, "pn": 30}}]}', 1293755476000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abadymoon-engl101', 'stk-abadymoon', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68443", "n": "Mr. John Williams", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخدت معاه 101\nالتحضير :\nعلى الوقت وصارم في التحضير لدرجة أنه اول ما يبدأ الكلاس يحضر والا يقول اسمه وبعدين يدخل يعتبر نفسه اقل شي ليت !!! حتى لو دقيقة بسسس متأخر (الحمد لله اسمي ما كان من الأوائل في الكشف)\nوبعدد انا ما كان عندي ولا غياب بس آخر يوم كان مطرر قوي واتأخرت على الكلاس 7 دقائق وما سمح انه يدخلني !!! مع العلم ان قال (انا مستحيل اطرد اي طالب حتى لو كان متأخر , اسجله غائب بس يدخل ) !!!\nالشرح :\nيعطيك الزبدة وادا مشيت على كلامه بالحرف الواحد ابشر بالدرجات الحلوة .\nالقراد النهائي :\nc +\nومعظم درجات الطلاب ما بين c و c+ يعني ادا اخذت d يعني مهمل وادا اخدت b فما فوق يعني دافوور.\nإضافات :\nلا تغلط تروح له مكتبه في غير الاوفيس اورز بدون ما ترسل له رساله (تاخد موعد) ولازم يرد عليك انه موافق !!!\nغير كذا الله يعينك واسأل مجرب 😞 😞\nالهومرووكات سهلللة جدا ومو كثيرة بس اسمع كلامه وابتعد عن الفلسفة وابشر بالخير\n\nوأي سؤااال (حااااااااااااااااااااادضريييين) ^_____^", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p782196", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/williams-john-christopher/68443/34", "user": "abadymoon", "ts": 1296953475000, "tid": 68443, "pn": 34}}]}', 1296953475000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6202-engl101', 'stk-user6202', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68443", "n": "Mr. John Williams", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت عنده انجلش 101 في ترم 101 << يمديكم 🤠\n\nالتحضير : شديد جدا … اول خمس دقائق واذا حضرت بعدها ليت واذا حضرت بعد عشر دقائق أبسنت\n\nطريقة الشرح : منظمه جدا وواضحه ويستخدم تقريبا كل الوسائل المتوفرة في الشرح يعني لا تخاف من هاالناحية\n\nالكويزات : سهلة الى متوسطة وهي عموما تجي ريدينق أو قرمر أغلبها عليها 1% وبعضها عليها 2%\n\nالمياجر:كومن\n\nالفاينلات :كومن\n\nالقريد النهائي: B\n\nالصوت: تقريبا واضح لكن احرص على الاماكن الامامية\n\nإضافات : المدرس هذا ميزته مثقف جدا - اتوقع تخصصه انسانيات - يعني كلاسه ممتع جدا وما ينمل منه\n\nلـــــــــــــكـــــــــن\n\nيعيبه انه مايحب الطالب يزيد أشياء من عنده في التاسكس ولو كانت حلوه يعني بالعربي لا تجتهد عنده أبد سو اللي يقوله لك بالنانو واضمن لك ان شاء الله الـ B+ في التاسك\n\nأحيانا ينقص عليك أشياء هو قايل سوو مثلها ويعزف السبب في ذلك الى انها سخيفة !! فلا تستغرب\n\nنصيحه للي يبي ينزل عنده اذا جاء وقت التاسكات اكتب له عينه ورح له الاوفيس قبل التاسك وخله يصحح لك , انا أعرف شخص أخذ عنده في اول تاسك +D انصدم الرجال … لكن بعد كذا صار يروح له الاوفيس دايم ويكتب له وقريداته بعدها كلها B وفوق\n\nمن ناحية الدرجات الرجال يعطيك حقك لكن في نهاية الترم اذا افرج الكلاس نازل يحاول يرفعكم اب قريد , انا دفني درجة ونص واخذت القريد اللي بعده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p786053", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/williams-john-christopher/68443/35", "user": "user6202", "ts": 1297420578000, "tid": 68443, "pn": 35}}]}', 1297420578000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2685-engl101', 'stk-user2685', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68444", "n": "Mr. Jeffrey Jameson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا درسني 101 وحاليًا معاه 214\n\nبالنسبة ل101:\n\nالتحضير : يوميًا أحيانًا أول الكلاس وأحيانًا آخره\nطريقة الشرح : يفهمك اللي حتكتبه في الكومبزشن مزبوط ويهتم بالطالب ويحاول يساعده قدر المستطاع ويعطي تمارين مفيدة قبل الكومبزشن عشان تستعد مزبوط\nالكويزات : ريدنغ متوسطة المستوى\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A\nالصوت: عالي الكل يسمعه حتى لو كان الكلاس كبير\nإضافات: مدرس خلوق جدًا وفاهم تقاليدنا وعاداتنا وديننا حتى إنه يرد السلام ويشمت العاطس\nضروري تزوره على الأقل أسبوعيًا في ساعات المكتب حتى تصلح أغلاطك في الكومبزشن , بالإضافة إنه يعامل كل الطلاب بالمثل من ناحية حسن المعاملة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p347214", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jameson-jeffrey/68444/10", "user": "user2685", "ts": 1231001968000, "tid": 68444, "pn": 10}}]}', 1231001968000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_pirate-engl101', 'stk-the_pirate', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68444", "n": "Mr. Jeffrey Jameson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني انجليش 101 - سمستر 101 :\n\nالتحضير : اغلب الكلاسات ويهتم نوعا ما بالتحضير .\nطريقة الشرح : ممتاز جدا لانه مرتب ويوضح لك المطلوب من الكورس ، يعطيك ( مودل ) للريتينغ تاسك ولحاجات ثانيه حق تعرف كيف تسويها ، يعطيك اشياء تساعدك في الميد تيرم والفاينال ،، يعني بالعربي يجهزك تماما لكل حاجه في الكورس .\nالكويزات : فيه كويزات بس مو صعبه اغلبها في الكلاس ،، وقبل الميد تيرم او الفاينال ينزل كويزات اون لاين على الويب سيتي تساعدك لدخول الاختبار ،\nالمياجر: كومن .\nالفاينلات : كومن .\nالقريد النهائي: A +\nالصوت: واضح .\nإضافات : يحب يضحك مع الطلاب ويحب انك تروح له الوفيس اورس ويركز عليها ،، عيبه الوحيد انه كل كم يوم يقولك اطبع هالاوراق وجيبها الكلاس معاك وما يرسل الا اخر الليل يعني شيك الصبح قبل الكلاس على الويب سيتي !!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p775588", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jameson-jeffrey/68444/46", "user": "the_pirate", "ts": 1296071575000, "tid": 68444, "pn": 46}}]}', 1296071575000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-as2012sem-engl101', 'stk-as2012sem', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68444", "n": "Mr. Jeffrey Jameson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "151 English-101 Term\nالتحضير : بشكل يومي لكن يحذف غيابات في أخر الترم\nطريقة الشرح : يقعد يتكلم في الكلاس وينكت ويستخف دمه ويقرا البوربوينت\nالكويزات : الريدنق كويز حقه واحد كان سهل والثاني صعب\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B\nالصوت: عالي\nإضافات : المدرس طيب وحبوب ويتساعد معاك إذا رحت له الأوفيس لكن مشكلته مشكلة\nمرررة تقهرني الصراحة مهما شديت حيلك وغيرت من نفسك القريد حقك غصب يبقى زي ماهو أصلا بتحصل أغلب الكلاس درجاتهم نفسها الا كم طالب\nنصيحة للي بينزل عند جيمسون يسوي ذي الثلاث أشياء\n1- يشد حيله في أول إختبار\n2- يجيب أعلى درجة ممكنة في الميدتيرم\nاغلب الطلاب درجاتهم لطول الترم نفس درجة الميد تيرم + الطلاب اللي جابو درجة عالية فيهم رفعهم بالراينتق الأول ويتساهل معاهم بعدين ( بالعربي الميدتيرم تقريبا هو اللي بيحدد قريدك ونصيحة لاتهمل الميدتيرم و حاول تخليه ياخذ عنك فكرة انك طالب مجتهد وصدقني بتشوفه يرفعك\nالمدرس بشكل عام طيب وحبوب ونفسه يساعد كل الطلاب لكنه يساعد كم طالب وينكب الباقين 😦\n3- روح له أول ما تطلع درجة كل رايتنق وخذ منه ورقتك واكتبها مرة ثانية وهو راح يزيدك قريد في الاغلب بس حاول تكون من أول الناس اللي ياخذون الورقة ويرجعون يكتبونها مرة ثانية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437933", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jameson-jeffrey/68444/87", "user": "as2012sem", "ts": 1451854687000, "tid": 68444, "pn": 87}}]}', 1451854687000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9534-engl101', 'stk-user9534', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68444", "n": "Mr. Jeffrey Jameson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "نزلت عنده 101 & 102\n\nمدرس حبيب وكلاساته ممتعة ويحب يسولف ويشطح واجد 😆\nبخصوص تدريسه : والله تدريسه يعتبر جيد وتصحيح للرايتنق يعطيك حقك ومايزودك واجد 🙂\nياشباب لازم تعرف أن في الترم العادي يكون الافرج c وبالصيف يكون b يعني من الاخر دور مدرس يريح راسك وبس لانه سياسة القسم بتظلمك وهو بيطبقها\n\nحاول تشد في الميد تيرم لأنه بيأخذ فكرة عنك ,تاسكات الرايتنق روح راجعها معاه بالأوفيس عشان يزودك فيها (خله يشوف أنك انسان مهتم) 😆\n\nباختصار : تبي مدرس كلاساته ممتعة وضحك 😆 ولا يكرف وحبيب 😆 نزل عنده وريح رأسك 😆\n\nمن أفضل مدرسين الجامعة 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1439401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jameson-jeffrey/68444/89", "user": "user9534", "ts": 1453073057000, "tid": 68444, "pn": 89}}]}', 1453073057000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2728-engl101', 'stk-user2728', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68447", "n": "Mr. Thomas Telfer", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "يعطيك العافية أديداس وقته حلو\nوفيه اكثر من مدرس نفس وقته ابختار بينهم\n\n^ ^ ^\n\nمشكورين يا شباب ،، أنا نزلت عنده الترم القادم …\n\nبس لازلت أريد مفاضلة بينه وبين نيكولاس !\n\nبالتوفيق للجميــــــــــع\n\n101 كرف وقريد سيء و102 تمشي على المنهج بس قريد سيء أز أ ريزلت أت ذا ايند اوف ذا سيميستر\nما ادري عنه 214", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p348405", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/telfer-thomas-ronald/68447/7", "user": "user2728", "ts": 1231187220000, "tid": 68447, "pn": 7}}]}', 1231187220000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-del_buffon-engl101', 'stk-del_buffon', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68447", "n": "Mr. Thomas Telfer", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "101 كرف وقريد سيء و102 تمشي على المنهج بس قريد سيء أز أ ريزلت أت ذا ايند اوف ذا سيميستر\nما ادري عنه 214\n\nلا خليني على تيلفير أزين لي 🙂\n\nمشكورين وماقصرتوا ،،\n\nواصل في خدمة الشعب … ياحبي لك\n❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p348513", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/telfer-thomas-ronald/68447/8", "user": "DEL_BUFFON", "ts": 1231195827000, "tid": 68447, "pn": 8}}]}', 1231195827000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_don-engl101', 'stk-the_don', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68447", "n": "Mr. Thomas Telfer", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "نزلت معه 101 قبل سمسترين\nالمدرس رهيب بمعنى الكلمه\nالله يوفقه ياشيخ\nالقريد النهائي a+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p515281", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/telfer-thomas-ronald/68447/25", "user": "The_Don", "ts": 1262544000000, "tid": 68447, "pn": 25}}]}', 1262544000000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-harry_potter-engl101', 'stk-harry_potter', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68447", "n": "Mr. Thomas Telfer", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "تلفر <<<<<<<<<<<<< خذت معاه english 101 في 091\n\nالشرح : يتكلم عن الموضوع المطلوب وبس ما تاخذ منه فايده باللغه\nالتحضير: ما كان يحضر\nالتاسكات : والله كان يعطيني حقي و كتبت له تاسك 3 مرات قالي لا تجي لكلاس يوم التسليم النهائي خلاص انا صححت التاسك لك نهائياً و عطاني b+ هذاك التاسك\nالتقدير النهائي : اعطيه B\nالصوت : واضح\nالاخلاق : جداً محترم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p673849", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/telfer-thomas-ronald/68447/41", "user": "harry_potter", "ts": 1280834445000, "tid": 68447, "pn": 41}}]}', 1280834445000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5882-engl101', 'stk-user5882', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68447", "n": "Mr. Thomas Telfer", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "^\n^\nادرس عنده 101 حاليا وعشان اكون صريح ما احضر له الا يوم في الاسبوع وهو الاثنين فقط بحكم ان الكلاس الساعة 7 فمستحيل اصحى له\n\nوعرفت انه ما يحضر زاد الطين بلة , وكمان مافي ديد لاين هزلت 😆\n\nاعرف من الشباب ايش اخذوا السبت وايش اخذوا الربوع\n\nالمدرس حبيييييييييب وطيب وانا بسبب اهمالي راح عليا رايتنق تاسك 2 وما سويت ولا واجب فيه\n\nرحت له الاوفس قال عادي عندك اسبوعين كاملة واذا حبيت بجلس معاك لأخر السمستر اسحب على رايتنق تاسك 3 واشتغل على 2 جيب الاوتلاين وقت ما تحب وجيب الدرافت اذا كنت مبسوط وبعدين تعال نتفاهم على التاسك 😏\n\nحبيييب جدا ومتعاون … ومثل ما قال احد الشباب ينفع تحطه اول كلاس او اخر كلاس وتسحب عليه\n\nطبعا هذا للي مسلم امر الانقلش وعارف ان قريده ما راح يطلع عن C+\n\nاما اللي يدور القريد العالي ولغته ممتاااااااازة والف خط تحت ممتازة لا ينزل عنده\n\nلأن كثير اللي يبغوا القريد العالي بس مو كلهم عندهم مقومات اللغة العالية اللي تخليهم ياخذوا قريد بالذات عند هذا المدرس\n\n//\n\nانصح فييه وبقووووووة بتحس انك بدون انقلش وتركز على باقي المواد بدون خوف على الانقلش", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p748493", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/telfer-thomas-ronald/68447/52", "user": "user5882", "ts": 1292900070000, "tid": 68447, "pn": 52}}]}', 1292900070000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_marvel-engl101', 'stk-the_marvel', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68447", "n": "Mr. Thomas Telfer", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انقلش 101 - سمستر 101\n\nبنود التقييم :\n\nالتحضير :\n\nما يحضّر أبدا…ولا يهتم…\n\nلكن يعرف وجيه وأسماء اللي يحضرون…\n\nوإذا عرفك أكيد إنّك بتستفيد…\n\nأحيانا يشرح لـ8 طلاب…\n\nوالباقين ساحبين…\n\nطريقة الشرح :\n\nفيه بوربوينت من قسم الإنجليزي…يشرحه…\n\nويوضح لك المطلوب في التاسك…\n\nالكويزات :\n\nعلى كل رايتنق تاسك فيه كويز…بس موب شرط في نفس الوقت…\n\nخذنا 4 كويزات…متنوعة في المستوى…\n\nشي صعب وشي الآفرج 21 من 25\n\nعلى كل حال الكويزات آفرج…\n\nوأشوف إنّها متوسطة مجملا…\n\nالصوت:\n\nواضح…والرجل اسكتلندي…لهجته بريطانية اسكتلندية\n\nإضافات :\n\nأهم ميزة إنّه يقبل منك التاسك في أي وقت…\n\nحتى آخر اسبوع…\n\nلكن من تجربتي معه ومن كلامه…\n\nلو تأخره مرة…يعني عقب ما حط آفرج الرايتنق مستحيل تآخذ أكثر من سي\n\nعشان ما يخرب الآفرج…\n\nلكن لو تتأخر شوي…\n\nممكن يعطيك أي قريد حتى لو إنّك متأخر عن الطلاب…\n\nنفس الكلام بالنسبة للكويزات…\n\nكان يطلب منّا نكتب الرايتنق 3 مرات…\n\noutline,draft and final version\n\nالنسخة النهائية كان يقول اكتبها في الغرفة…\n\nيعني تعدل الأخطاء وتسلمه ثانية ويزيدك قريد !\n\nلكن في نصّ الترم خرّبوه أصدقاء السوء ! : )\n\nيقول قالوا لي زملائي طريقتك هذي سهلة…\n\nوبعدين تتعبك في تحديد الآفرج…لأن كل الطلاب بيكتبون صح\n\nصرنا نكتب النسخة النهائية في الفصل…\n\nبالنسبة للبرزنتيشن…مرة فردي ومرة مع مجموعة…\n\nمن ناحية التصحيح…\n\nلو تمشي على المطلوب وتعدل شي بسيط يعطيك درجة حلوة…\n\nويطلب منّا نجيب التاسك مطبوع…لكن ما يلزمنا…\n\nمن ناحية القريدات النهائية…\n\nعادي جدا…\n\nولا واحد خذ A في الشعبتين…\n\nوفيه 2 يمكن F والباقين بين الدي والبي بلس…\n\nأعطيه 7.5\\10", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p780065", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/telfer-thomas-ronald/68447/53", "user": "The_Marvel", "ts": 1296556351000, "tid": 68447, "pn": 53}}]}', 1296556351000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar.a-engl101', 'stk-omar.a', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68447", "n": "Mr. Thomas Telfer", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "RoN Telfer…\n\nسمستر 101 …انجلش 101 …\n\nكان ما ياخذ الغياب ابدا … الحضور شوية …5 او 4 طلاب بس\n\nتصحيح التاسكات عنده بطريقة … اوت لاين + درافت … بعدين الفاينل … ودرجة التاسك مقسمة على\n\nالاوت لاين + الدرافت + الفاينل … يعني تجيب دي في الاوت لاين ومبدع في الدرافت والفاينل تاخذ سي\n\nمدرس ماشي بشي اسمه افرج … كل شي يسوي له افرج ونورملايزيشن على افرج الكلاس الوورك\n\nالقريدات النهائية تكون مخسوووووفة جداً … حرام والله تحسفت اني نزلت 101 معاه\n\nآخذ ايه بلص في الفاينل درافت … واكون مخبص في الاوت لاين …لأنه ما يوضح لك كيف الطريقة وتاخذ قريد سيء\n\nمدرس دمار صراحة …اذا تبغا تبكي على نفسك وتحس انك مظلوم نزل معاه\n\nالقريد النهائي D …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p856831", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/telfer-thomas-ronald/68447/61", "user": "Omar.a", "ts": 1308644849000, "tid": 68447, "pn": 61}}]}', 1308644849000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_vip-engl101', 'stk-_vip', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68495", "n": "Mr. Ralph Kraft", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا اخذت معاه 101 وكان اول كورس له بالجبل\n\nالتحضير : ورقه يمشيها بس بعض الاحيان ينشب واذا صادك فكك نفسك\n\nطريقة الشرح : شرحه حليو يعني يجي منه ويحب يساعد الطالب\n\nالكويزات : ما يعطي كوزات كثير\n\nالمياجر: مشكلته بعض الاحيان ما يكون واضح زي باقي الدكاتره عن التاسكات اللي بتجيك يعني يلمح لك وش بيجيك بس ما يقولك وشو بالضبط\n\nالفاينلات : مثل المياجر\n\nالقريد النهائي: B\n\nالصوت: واضح\n\nإضافات : الانجلش معروف يبي له كرف بس ذا الدكتور يبي يشوف انك تكرف معه وبيدفك … تصحيحه شديد اشوي يعني ينشب لك على بعض النقاط\nاعرف واحد كان ناااااااااااشب له فالاوفس اور ويسوي كل شي يطلب منه وعطاه فالاخير +a … تخيلوا +a فانجلش 101 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p350799", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/kraft-ralph-david/68495/4", "user": "_vip", "ts": 1231683653000, "tid": 68495, "pn": 4}}]}', 1231683653000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kitkat-engl101', 'stk-kitkat', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68495", "n": "Mr. Ralph Kraft", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخوي بدون عنوان …\n\nانا كنت نزلت عنده يوم التسجيل الترم الثاني وجاني واحد من الشباب كان منزل عنده الترم هذا قال نصيحة اخ احذف ولو ما بقى الا هو لا تاخذه … (( تجربة صديق لي )) في ترم 081 في انقليش 101", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p370011", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/kraft-ralph-david/68495/5", "user": "KiTKaT", "ts": 1235133929000, "tid": 68495, "pn": 5}}]}', 1235133929000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-half-moon-engl101', 'stk-half-moon', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68495", "n": "Mr. Ralph Kraft", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ادرس عنده حاليا 101\nاستاذ نظامي جدا وشرحه كويس\nلكن يكرررف اليييين خلاص\nما يمر يومين الا طلب شي تسويه\nوالويب سي تي مليان الى نهاية السمستر\nاما الدرجات لسا ما خلصت الترم لكن اتوقع درجاته كويسة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p749739", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/kraft-ralph-david/68495/27", "user": "HalF-MooN", "ts": 1293031516000, "tid": 68495, "pn": 27}}]}', 1293031516000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khaled-alfa-engl101', 'stk-khaled-alfa', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68495", "n": "Mr. Ralph Kraft", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم\nكيف حالكم شباب\nانا طالب سنة تحضيرية 2011-2012\nوعديت التوفل واخذت بورموشن في الانجلش 001 و 002\nونزلت مادة الانجلش 101 تبع الفريشمان\nوحطوني عند R KRAFT\nوبعد ما قريت عنه انه كريف درجة اولى 😲\nسرت أبغا أغيره\n\nفهل أقدر أغيره؟\nواذا أقدر تنصحوني بأي مدرس؟\n\nبكرة أول حصة لي عنده في مبنى 24\nوما أعرف فين المبنى بالضبط 😐\n\nوسؤال أخير هل أنا بأدرس الكورس هذا مع طلاب فريشمان\nأو مع طلاب الأوريا اللي أخذو برموشن مثلي؟\n\nتكفون بالله جاوبوني بسرعة 😭", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p899526", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/kraft-ralph-david/68495/35", "user": "khaled-alfa", "ts": 1315793153000, "tid": 68495, "pn": 35}}]}', 1315793153000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dr.mohtaref-engl101', 'stk-dr.mohtaref', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68516", "n": "Mr. Dana Ebbett", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : بـشـكـل دوري ( بدون المحاسبة على التأخير )\nطريقة الشرح : مـمـتـازة , ودائما ما يعمل مراجعة لشرح الحصة الماضية مما يجعل من المستحيل نسيان شرحه\nالكويزات : تعتمد على نظام الـ WebCT وهذا أجمل مافي الموضوع لأن الأسئلة تأتي على شكل خيارات و تستطيع الإجابة عليها من دون قراءة السؤال ( غير أنك تستطيع إعادة الإختبار 3 مرات في حالة لم تحصل على درجة جيدة )\nالمياجر و الفاينلات : Common ENGL 101 ومن الأساس المادة لاتعتمد على المياجر\n\nالأخلاق : مدرس خلوق جدا ورسمي بزيادة\nالقريد النهائي: ِA\nالصوت: مـعـتـدل\nإضافات : , لا يـوجـد ,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p506507", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ebbett-dana-dean/68516/16", "user": "Dr.Mohtaref", "ts": 1261459267000, "tid": 68516, "pn": 16}}]}', 1261459267000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2040-engl101', 'stk-user2040', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68516", "n": "Mr. Dana Ebbett", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا درست عنده في 082 ( 101 )\nالتحضير : بيحضر كل يوم تقريبا وماله وقت معين ممكن باول الكلاس ممكن بآخره \" وحتى لو جيت متأخر يحضرك \"\nطريقة الشرح : من اروع ما يكووون\nالكويزااات : كلها عن طريق الويب سيتي \" كل اسبوع 100 كلمة \"\nالميااجر \" كومون\nالاخلاق : عالية جدا\nالقريد : a\nاضافات : اسواء شي انه ما يزود ولا بوينت , انا كان باقي لي 0.7 عشان آخذ c+ بس ماعطاني اياها برم اني رحت له وكلمته وكنت أروح ل الاوفيس اور كل اسبوووع >> حقدت عليه الصراااحه بس الحق يقال انه مدرس كشرح ممتاز ومايكرف ابد بالعكس مرن كثير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p515720", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ebbett-dana-dean/68516/18", "user": "user2040", "ts": 1262602431000, "tid": 68516, "pn": 18}}]}', 1262602431000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.small-engl101', 'stk-mr.small', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68516", "n": "Mr. Dana Ebbett", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا معاه 101 في هذا السمستر 091\n\nالتحضير: يحضر أحياناً بعد فترة من بداية الكلاس أحياناً نص أو قريب نهاية الكلاس … ما يهتم للتأخير …\nطريقة الشرح : إنجلش الجبل ما يعتمد حقيقة على الشرح … على العموم هو يقول لك كيف ترتب الرايتنغ\nفي بداية السمستر كان في الويب سي تي ريدنغ و محدد بأوقات … بعدين رايتنغ … يحاسب في الرايتنغ على كل شيء … يعني لا تقول أنا ما عندي أخطاء في القرامر … ينقصك لو ناقصنك شوي ترتيب\nالقريد النهائي: أعطيه b\nالصوت: واضح و مفهوم\nإضافات: يمدد الديد لاين لو طلبت منه + يمزح أحياناً\n\nقبل لا تسلم الرايتنغ تأكد تخليه يشوفه إذا ممكن أكثر من مرة عشان إذا مو عاجبه شي عندك فرصة تضبطه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p519132", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ebbett-dana-dean/68516/20", "user": "MR.SMALL", "ts": 1262957225000, "tid": 68516, "pn": 20}}]}', 1262957225000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-eng.3booodii-engl101', 'stk-eng.3booodii', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68556", "n": "Mr. John Carey", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كورس 101\n\nالتحضير : يومياً نهاية الكلاس وبعض الأحيان بدايته …\nطريقة الشرح : يوزع أوراق للدروس ويشرح الدروس بطريقة المحاورة والنقاش ( أسلوب رائع ))\nالكويزات : الريدنق بعض الأحيان تكون سهله وبعض الاحيان تكون صعبه\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح جداً\nإضافات : دكتور رائع جون كيري … أكن له الإحترام والتقدير\nوإلي زعلني إنه ما بينزل لا فـ الصيف ولا ترم 101 … نقول يارب ينزل فـ 102", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p637493", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/carey-john-martin/68556/23", "user": "eng.3boOodii", "ts": 1276865044000, "tid": 68556, "pn": 23}}]}', 1276865044000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4988-engl101', 'stk-user4988', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68614", "n": "Mr. Ian Davison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سلامُ عليكم\n\nengl 101 +102\n\nبأختصر الكلام على قد ما أقدر :\nالرجال ممتاز ، شرح ممتاز ، شغل رائع في الـ 101 ، و أنا شخصياً خرجت من عنده بقريد رائع\n\nلكن نجي للطامة 102\nكورس معفن ملعون أبو جده ، الرجال نفسه ما أدري إيش اللي خلاه ينقلب كذا\nلا انصح به بتاتاً لعدة أسباب :\n1 - كلاسته في الـ102 تكون بعد العصر ، و هو للأسف توقيت سيء جداً لها عائداتها السيئة على الطالب نفسه\n2 - رد الأخوة ( صبعبلي + Black@b0x ) كافي جداً لشرح الوضع في الـ102\n3 - لاحظت إن التشبيك معاه ما راح ينفع ، بل إنه ممكن بيحطك في رأسه\nو عاد شوف لو حطك في رأسه إيش بيسوي فيك ، أمثلة /\n\n* لما يجي واحد يطلب منه مساعدة في طريقة كتابة التاسك ، يقوم يساعده و يقول له بأعطيك A على هذه الطريقة ، و لما تنزل الدرجة في الويب سي تي يتفاجأ بانها صارت C بقدرة قادر !!!\n\n* فيه واحد كل شوي يمشي ورى الدكتور و يلاحقه، يساعد الدكتور يجيب له ملفاته و أوراقه و مفاتيحه ، والله ما عاد إلا شوي يبوس الجزمة و أنتوا بالكرامة ( بدون مبالغة ) ، كان على بالي إنه واحد من موظفي سراكو إلا تفاجأت إنه طلع طالب يدرس عنده 101 ، عجيب والله !!!\nصار الواحد يهين نفسه عشان القريد ( هذا إذا أعطاه أصلاً ) ، المبكي في الموضوع إن المدرس نفسه تكلم عنه في كلاسنا ( لما مر عليه الطالب ) و قال ما مقتضاه : الطالب هذا وراي وين ما أروح ، البعض يظن إن التشبيك هي الطريقة الوحيدة عشان تحصل على a+ ]\n\nالشاهد : ( التشبيك ما ينفع معاه كثير ، و ممكن بينقلب عليك )\n\nو عاد في الفاينل قريد إيش اللي صار؟؟؟\nنزل القريد مباشرةً في الترانكسيبت ، ما حط التفاصيل في الويب سيتي زي ما سوى في الـ101\nيعني انا الآن ما أعرف كم اخذت في الريبورت و الفاينل ، و التوفل اللي خوفنا بها ما أرسل قريداتها\nيعني 90% من الكلام اللي قاله عن التوفل و اللي خوفنا به طلع خراط\nأرسلت له عدة مرات أبغى أطلب منه القريدات بس سحب علينا\n\nزي ما قلت ، هو كويس في 101 بس للأسف شديد ( قد يصل لدرجة الظلم ) في 102", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p971210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ian-davison/68614/53", "user": "user4988", "ts": 1327064354000, "tid": 68614, "pn": 53}}]}', 1327064354000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khalid-f10-engl101', 'stk-khalid-f10', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68614", "n": "Mr. Ian Davison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انجلش 101 ترم 111\n\nقسم بالله انو اخيس مدرس\nظالم في القريدات ******************\nقاعد ينصب علينا من بداية السمستر انت بتاخذون a و a+\n\nوللعلم انسان كسووووووووووووووووووول على الاخر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1044647", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ian-davison/68614/59", "user": "khalid-f10", "ts": 1337980806000, "tid": 68614, "pn": 59}}]}', 1337980806000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal-fin-engl101', 'stk-faisal-fin', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68614", "n": "Mr. Ian Davison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا هالمدرس اخدت معاه 101 ترم 111\n\nطبعا كشرح ممتاز جدا وواضح خصوصا في الريدنق والرايتنق ويكرفك بصراحة\n\nلكن للامانة انسان مزااااااااجي جدا جدا جدا يعني بحكي لكم بتاسك 1 و 2 و3 كان جدا ظالم للطلاب يخسف فيك الأرض عشان غلطه صغيره و درجات الصف الله لا يوريكم ولله تفشل من كثر السي والدي مع انها مرررررره كويسه\n\nجينا على تاسك 4 كل الطلاب كتبوا كلام اهبل لانهم مو منتظرين قريد وسبحان الله يطلع لنا بمزاجية عالية ويوزع قريدات يشوف الغلط وااااضح قدامه ويمشي وعطنا إيه وبي تقريبا لكل الصف\n\nبالأخير واحد جاب بي بلس والباقي تحت\n\nاخوياي الحين منزلين معاه 102 ولله مو مصدق عيني يكب لهم درجات بشكل ما ادري وش قصته … لين لاحظت ان مزاجيته مره مره مره مؤثرة عليه تحسه نفسية !!! بصراحة ما ادري اقولكم نزلوا عنده ولا لا من ناحية شرح وفايدة وتعلم انا اضمن لكم لكن من ناحية قريد وراحة نفسية انت وحظك لو مزاجه حلو بيعطي\n\nالأوفس اور ماينفع معاه ابدن ولا يقبل المساومه في القريدات ابدن ابدن ابدن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1044654", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ian-davison/68614/60", "user": "Faisal-FIN", "ts": 1337981507000, "tid": 68614, "pn": 60}}]}', 1337981507000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abood-1991-engl101', 'stk-abood-1991', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68614", "n": "Mr. Ian Davison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذته انا بسمستر 102 بمادة 101\nالتحضير :بكل حصه واحيانا يلخبط وينسى\nطريقة الشرح :حلوه وسلسه ويعطيك الاشياء الي يبغاها وان سويتها ابشر بالقريد الحلو\nالكويزات :كثيره نوعا ما لكن الماده تطّلب\nالمياجر:كومون\nالفاينلات :كومون\nالقريد النهائي:+b\nالصوت:واضح\nإضافات :المدرس طيب جدا لكن لا تغش في الريبورت او تسوي حركه مو زينه يزعل منك وحاول تروح للاوفيس كثير وابشر بزياده بالقريد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1098770", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ian-davison/68614/63", "user": "abood-1991", "ts": 1348612193000, "tid": 68614, "pn": 63}}]}', 1348612193000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m.hussain-engl101', 'stk-m.hussain', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en68614", "n": "Mr. Ian Davison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "101 سمستر 121\n\nالتحضير : كل كلاس ونادرا ما يحضر ، ويتسامح في التأخير دائما\nطريقة الشرح : الكلاس ممتع وفيه ضحك ويركز على الكلمات والأشياء الرئيسية في الكتابة مثل الأسلوب وغيره ، وفي تصحيح التاسكات كريم بحيث ما يحب التعقيد ، بس يبيك تمشي على الأسلوب وبدون أخطاء وابشر بالa+ ، وكذلك يكون بالكلاس تمارين ، وبالنسبة للبرزنتيشن يبي شي بسيط ومختصر وما يحب التعقيد في أي شي\nالكوزات : على حسب ، مرة سهل ومرة صعب\nالصوت : جيد\nالقريد النهائي : أشوف ان المدرس ممتاز وأعطيه A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1139025", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ian-davison/68614/64", "user": "M.Hussain", "ts": 1355318285000, "tid": 68614, "pn": 64}}]}', 1355318285000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_lion013-engl101', 'stk-the_lion013', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en69101", "n": "Mr. Anthony Gibson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :\nيحضر يوميا , الاغلب في بداية الكلاس . ولكن بعض الاحيان في اخره\nولا يهتم بالتأخير حيل , لكن اذا جيت متأخر نص ساعة مثلا يسجلك LATE\n\nطريقة الشرح :\n\nيستعرض لك المطلوب من سلايدات ويعطيك امثلة ايضا من السلايدات وما يستخدم السبورة\nواذا في تمارين او شرح يوزع اوراق للطلاب وينزل جميع السلايدات اللي يستعرضها بالبلاك بورد من بداية الترم بالاضافة انه ينزل اختبارات قديمة وتمارين ع البلاك بورد مفيدة جدا جدا ولكن بدون حلول , يقول لك اذا تبي الاجابات الصحيحة , حل اللي تبي وجيبهم لي وانا اصحح لك ع\nبسبب يقول ان اذا حط الاجابات الطلاب مايستفيدون\n\nالكويزات :\n\nبالنسبة لكورس 101 مافي الا كوز ريدنق وسهالات الكويز\nوموعد الكوز محدد بالسلبس\n\nاما بالنسبة للرايتنق فالرجال عادل ويعطي قريدات حلوة واذا جيت قبل الكلاس بوقت يخليك تبدأ على طول الكتابة وهذي ميزة حلوه\n\nالمياجر:\n\nالميدتيرم كومن من الديبارتمت\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\n\nAAAAAAAAAA\nالصوت:\n\nواضح جدا جدا\nإضافات :\n\nالمدرس ايرلندي وحبوب ونكيت ( ودائما ينكت على نفسه ) ويخلي الحصة ممتعة بالسوالف حول موضوع الكلاس مع الطلاب وبعض الاحيان يسوي حركات غريبة تضحك\n\nيسمك بالميك اب بدون اي مشاكل\n\nوفي اوقات الكويز ماعنده مشكلة اذا بتسالف معاه ولا عنده تشدد في اي شي وتشوفه دائما يضحك وهادئ جدا 👍\n\nعموما انصصح فيه جدا جدا للي يبي الحصة الممتعة بالاضافة الى القريدات العادلة او الجيدة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1411294", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gibson-anthony/69101/47", "user": "The_lion013", "ts": 1415712725000, "tid": 69101, "pn": 47}}]}', 1415712725000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hammmod-engl101', 'stk-hammmod', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en69101", "n": "Mr. Anthony Gibson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انجلش 101 سمستر 141\n\nأتوقع كل مدرسين الانجلش نفس الطينة سبحان الله\n\nالتحضير يومي اول ما تدق الساعة الين اخر ثلاث أسابيع من السمستر صار ينسى ويحضر اخر الكلاس، ما عنده مشكلة مع الليت لكن يبدأ يحسب الليت من اول دقيقتين ولو تحضر وباقي 5 دقايق عادي بس يحطك ليت. عن نفسي طول الوقت طفشان في الكلاس سوالفi مخيسة وغير مفيدة أبد، كأنك أنت وخويك ماسكين خط مكة وخلصت سوالفكم وقمتوا تدورون أي موضوع تسولفون فيه، والمشكلة موووستااااحيييل يطلعك قبل ما تجي الدقيقة 50 وميزته عادي طقطق عالجوال او حل ماث ما يقول شيء.\nمهوب حق تضبيط أبد يعني عادي يسولف ويضحك معك وهو ما يدري من انت ولا جاب خبرك وهذي نقطة جيدة لاني ما احب هالحركات.\nسكشنا ما عطى ولا واحد حتى A يمكن 5 B+ وكالعادة نص الكلاس C.\nالزبدة عادي نزل معه ما يغثك، عنده بعض الهومووركات ولكن سريع في التصحيح سواء الهوموورك او الرايتنق.\n\nالتقييم العام\nC+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420841", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gibson-anthony/69101/50", "user": "hAmMmOd", "ts": 1421750968000, "tid": 69101, "pn": 50}}]}', 1421750968000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a.ee-engl101', 'stk-a.ee', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en69101", "n": "Mr. Anthony Gibson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Engl101 - 151\n\nالتحضير : يومي بالسيريال نمبر\nطريقة الشرح : المادة ما فيها شرح كثير ، لكن لو كان بيشرح يستخدم السبورة أو يشرح من سلايدات\nالكويزات : 2 ريدنق قبل الميد والفاينل ، جاب لنا نفس القطعة في الاثنين بس إنه غير شوية في الأسئلة\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: B+\nالصوت: وضح\nإضافات :\nميزة الدكتور إنه ما هو مثل بعض دكاترة القسم اللي يجيك ويتحلطم لك بالحصة ويغثك …\nروحه مرحة ومتعاون مع الطلاب ويصحح كل رايتنق ويقيمك عليه … ما يعطيك درجات أول رايتنق\nيسمح بالميك اب وما عنده ليت ، مرة حضرت وباقي ربع ساعة وحضرني نهاية الكلاس\n\nالدكتور طيب وما يكرف وصراحة أنا أرتاح للنوعية اللي كذا ونزلت عنده الكورس الجاي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437884", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gibson-anthony/69101/52", "user": "A.EE", "ts": 1451824404000, "tid": 69101, "pn": 52}}]}', 1451824404000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10775-engl101', 'stk-user10775', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en69101", "n": "Mr. Anthony Gibson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nEng101\n162\nمتقاعد حاليا\nالتحضير :\nيفتح لك الأكسل و تشوف رقمك التسلسلي و يناديك عليه بداية كل كلاس و يتجاوب مع الميكب.\nطريقة الشرح :\nبالبروجكتر من ملف لملف يفتح الكورس الرئيسي و يرفع لك أمثلة للرايتنق وكان يركز على transportation في اختبارات الرايتنق مالته و ما تتعدى هالمجال.\nالكويزات :\nكويزات من عنده قبل الكويزات اللي من القسم أحس اللي من عنده ما كان عليها درجات بس عشان تستعد للي من القسم.\nالمياجر:\ncommon\nالفاينلات :\ncommon\nالقريد النهائي:\nB+\nالصوت:\nslightly clear\nإضافات :\nمتعاون معك و يستقبلك في المكتب و يعطيك على حضورك هناك بونص.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1480662", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gibson-anthony/69101/53", "user": "user10775", "ts": 1505914881000, "tid": 69101, "pn": 53}}]}', 1505914881000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hadi14-engl101', 'stk-hadi14', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en74185", "n": "Mr. Savino Sfregola", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا منزل عنده 101\nالتحضير : بداية الكلاس عادة وعنده هذا اهم شي في الدرس\nالشرح : شرح اي كلام وكل يوم يعيد نفس الكلام\nالهوم ووركس والتاسكس تسلمهم في الويب سيتي\nكل يوم يشكيلنا همومة ومعاناته\n\nالتقييم: c", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p515653", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/savino-sfregola/74185/6", "user": "hadi14", "ts": 1262594404000, "tid": 74185, "pn": 6}}]}', 1262594404000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.fabulous-engl101', 'stk-mr.fabulous', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en74185", "n": "Mr. Savino Sfregola", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا منزل عنده 101\nالتحضير : اساسي في كل حصه لكن متسامح\nيعني مره كنت غايب وهو نسى يحضر في هالحصه اللي غبت فيها قال من غايب الحصه اللي فاتت رفعت يدي حضرني فيها\nالشرح : شرح عادي جدا يكاد يكون ممل لكن للذمة والله اني اقوم من النوم قافله وما ادخل حصته الا واطلع منها اضحك صحييح مرات يكون سامج بس مرات كنا من جد نفرقع ضحك\nاخلاق: جدا حبووب يشد شوي مرات لكن يرخي مثال تطبيقي لكلمة اذا ارخيت الحبل شد واذا شديت ارخا الحبل\nالهومورك: طبيعي ياخذ من وقتك 3 ساعات لا تحزن يعني وكل ال 101 طبيعته كذا مدري عن 102 بس الظاهر نفس الوضع وزي ما قلت لكم مرات يشد بالتصحيح بس الغرض انه يخليك تشد وان شديت معاه سهلها وفتحها بوجهك\n\nالتقييم: b+\nوالله لا يعوق بشر منزل عنده السمستر الجاي وتراه فعلا جديد وهاذي ميزه للي يعقلون 😛", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p516433", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/savino-sfregola/74185/9", "user": "Mr.Fabulous", "ts": 1262646303000, "tid": 74185, "pn": 9}}]}', 1262646303000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8975-engl101', 'stk-user8975', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en74185", "n": "Mr. Savino Sfregola", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كلمة حق سأحاسب عليها :\nدرسني إنجلش 101 ، وتقييمي له كالتالي :\n\nالتحضير :\nكل كلاس يحضر من ملف الإكسل ،\nويحضر بالأسماء مو بالأرقام “لمحة احترام” …\n\nطريقة الشرح :\nيكتب الـ Main Points لكل حصة على ركن بالسبورة ، وأحيان ما يكتبها …\nيشرح من notes يكون مجهزها ولو بغى يكتب مثال أو كذا يفتح ملف وورد ويبدأ يشرح …\nمهم عنده التعلم الذاتي ، يعني يعطيك روابط تعليمية وواجبات وما يسألك عن كثير منها ، يعني مبدأه إن هذي حياتك وأنت لو تبي تستفيد بتتعب ، أو بتعاني آخر شي …\n\nالكويزات :\nالريدنج كويزز تكون من ال Mid Terms السابقة أو Finals ، خصوصاً قبل الميد تيرم والفاينل …\nال writing tasks تكون كومن عن موضوع الكورس “في حالتنا كانت عن الصحة” …\n\nالمياجر:\nكومن ، ريدنج\n\nالفاينلات :\nكومن ، ريدنج\n\nالقريد النهائي:\nA\nواقروا الإضافات .\n\nالصوت:\nد. سافينو هو أسترالي من أصول إيطالية …\nيعني الأكسنت حقه نفس أكسنت الأستراليين …\nوالكلمات الصعبة أو الجديدة على الطلاب يعطي لها كلمات مقاربة عشان تفهم أو يضرب مثال …\nالصوت واضح بالنسبة لي “لأني أحب الأكسنت البريطاني والأسترالي” …\n\nإضافات :\nمثل ما قلت : ما ذكرته كلمة حق وسأحاسب عليها :\nالرجل عادل لأبعد حد ، وبيحاسبك من منظوره الأكاديمي ، واهتمامك بيعني له الكثير …\nيعني إذا مستواك متوسط بالإنجلش ، لا تتأمل في قريد عالي …\nوإذا مستواك عالي جداً ، فيه فرصة تجيب b+ … A … b\nوإذا مستواك عالي جداً جداً جداً ودفرة إنجلش من يوم انك صغيييير ممكن تجيب A+\n\nماني نادم على إني أخذت الإنجلش عنده ، بالعكس أحس إني استفدت …\nتعبت وبذلت جهدي وعدلت وحاولت … والحمد لله على كل حال .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1038758", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/savino-sfregola/74185/49", "user": "user8975", "ts": 1337220663000, "tid": 74185, "pn": 49}}]}', 1337220663000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-voldy-engl101', 'stk-voldy', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en74185", "n": "Mr. Savino Sfregola", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "English101 -Term 112\n\nبنود التقييم :\n\nالتحضير : ينادي على الأسماء في أي وقت من الحصة وحتى لو جيت متأخر يحسبك حاضر ما يحب أحد يغيب عنده (قد تناقشت معاه مرة في الأوفيس من كلامه يشوف ان الي يغيب يعتبر طالب غير مهتم بالمادة لو تغيب حتى مرة واحدة)\nطريقة الشرح : عادية جدا زي مدرسين الأوريا\nالكويزات : حقت الريدنج كانت سهلة في البداية واخر اثنين كانوا صعبة بحجة انه لازم ينزل الأفرج\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B\nالصوت: عادي وواضح\nإضافات : المدرس بالأمانة حقاني أنا قد شفت درجات الطلاب بنفسي في المكتب حقه يجمع درجاتك ويعطيك قريدك الي تستحق (على نظام الستاندرد) وبالأمانة انه يعطيك حق بالضبط مو زي بعض المدرسين الي يعطونك أقل من حقك بالعكس كمان فيه طلاب أعطاهم أب قريد مع انه باقيله 3 او 4 درجات على القريد الي بعده\nتصحيح الكتابة: صراحة شديد في الكتابة والآدمي له فترة في مجال العمل ويعرف اذا كلامك ولا انت حافظه يحب انك انت تكتب بأسلوبك الخاص\nالأخلاق: جدا محترم وراقي في تعامله لكن نكاته مررررة سامجة، واذا قدرت تشبك المدرس في writing خلاص بيحطك في راسه انك أنت طالب كويس\n\nEnglish214 - Term121\n\nبنود التقييم :\n\nالتحضير : ينادي على الأسماء في أي وقت من الحصة وحتى لو جيت متأخر يحسبك حاضر ما يحب أحد يغيب عنده\nطريقة الشرح : مملة\nالريبورت : بالأمانة كرفنا كرف الحمير واذا ما عجبه موضوعك من البداية فلا تتوقع قريد عالي\nالبريسينتشن: خسف في الطلاب يحاسبك بالملي ويعلمك أخطاءك بالضبط\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:C+\nالصوت: واضح جدا\nإضافات : أحسن شيء ان كل تعامله كان بالويب سيتي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1318737", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/savino-sfregola/74185/74", "user": "Voldy", "ts": 1389613458000, "tid": 74185, "pn": 74}}]}', 1389613458000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m7md3804-engl101', 'stk-m7md3804', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en76546", "n": "Mr. Josh Billam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "يعطي هووموركات كثيرة جدا جدا في كورس الـ 101 لكن ماعليها ذيك القريدات اللي تستحق 🙂\n\nشبابي ،، متفهم ،،\n\nاحضر عنده كل الكلاسات وفي نهاية الترم يسوي لك آب قريد !\n\nاخذت عنده b\n\nالكلاس يمر بسرعه وماتدري عنه … يوميا يحضر ولا تتاخر لانك بتكون آبسنت موب ليت !!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p546255", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/billam-josh/76546/24", "user": "m7md3804", "ts": 1266563250000, "tid": 76546, "pn": 24}}]}', 1266563250000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_prince-engl101', 'stk-_prince', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en76546", "n": "Mr. Josh Billam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كيفو في 214 ؟!\n\nبصراحة مادري عن 214 لكنه عموما مدرس بطل انا ماخذ معه 101 وهذا آخر سمستر يدرس 101\nلو اقدر اني انزل كل كورسات الانجلش عنده نزلتهم بدون تردد 🥰", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p767076", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/billam-josh/76546/39", "user": "_PrInCe", "ts": 1295473589000, "tid": 76546, "pn": 39}}]}', 1295473589000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-phenomenon-engl101', 'stk-phenomenon', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en76546", "n": "Mr. Josh Billam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "8\n8\nاذا شفت اسمه … نزل معه وبس ❤️\nهذا أفضل مدرس انجليزي ممكن يمر عليك في حياتك كلها\n\nأنا سبق وقيّمته لأني أخذت معه 101 … والحين خلصت 214 معه بالصيف بعد\nصراحه ماراح ألقى كلمه توصفه أو توفيه حقه …\nوبالصيف كان فلّه زياده لأنه درسنا الشهر الثاني وكان توه مخلص شهر العسل 🤠\n\nالمهم … اللي يشوف سكشنه فاتح ولا ينزّل معه … هذا مرتكب جريمه في حق نفسه وبس 🤪\nوهذي قريداته للصيف :\n\nالمجموع الكلي للي خذوا A يتراوح بين الـ88 والـ89\nالمجموع الكلي للي خذوا +B يتراوح بين الـ 84 والـ86\nالمجموع الكلي للي خذوا B يتراوح بين الـ 78 والـ84\nالقريدات الباقيه ستاندرد …\n\nA\nA\nA\nB+\nB+\nB\nB\nB\nB\nB\nB\nB\nB\nB\nB\nC+\nC+\nC+\nC+\nC+\nC+\nC+\nC\nC\nC\nD\nF\n\nطبعا القريدات هذي طلعت بالويب سيتي …\nيوم نزلت لي بالبورتال سوا لي أب قريد ❤️ ما أدري عن باقي الطلاب\n\nوإضافة إلى أن نصف الشغل كان عند رون تلفر (55%) بما انهم تقاسمو الصيفي …\nتلفر خسف بكثير من الطلاب في السورس ايفالويشن لكن جوش كالعاده كريم بالقريدات للي يشتغل 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p891004", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/billam-josh/76546/68", "user": "Phenomenon", "ts": 1314133002000, "tid": 76546, "pn": 68}}]}', 1314133002000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sad_safwa-engl101', 'stk-sad_safwa', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en76546", "n": "Mr. Josh Billam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا أخدت عنده 101 والحين عنده 102\nبصراحة مدرس شبكته ولا ماشبكته تعامله راقي وياك … ومايخليك تحس بالضغط\nودا السمستر تقريبا مافي الا كلاسين رحتهم ع التايم 😛\nهو عنده كلاسين ورا بعض في الرايتنق احضر السكشنين ولا يقول شي\nاقل قريد عطاني اياه في رايتنق او سبيكنق c\n\na+ قليلة عليه\n\nقريدات نهائية دائما تكون متوسطة , ويحرص ان واحد عنده ع الاقل ياخد a+\n\nقريدات السمستر الماضي 101 حق كلاسين\n\nc+\nd+\nd+\nc\nc\nd+\nd\nc\nc+\nc\nc\nd\nb+\nd+\nc+\nc+\nc+\nb\nc\nc\nb\nc\nc\nc+\nb+\nc+\nb\nb\nc+\nc\nd+\nc+\nc+\nc\na\nc+\nb\nb\nc+\nc\nc+\nb+\na+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1363643", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/billam-josh/76546/97", "user": "Sad_Safwa", "ts": 1399815457000, "tid": 76546, "pn": 97}}]}', 1399815457000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8671-engl101', 'stk-user8671', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en76546", "n": "Mr. Josh Billam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "The best\nأخذت معه 101 و102 وأن شا الله 214\nصح اني أخذت c+ بكل الكورسين\nلكن ماتشيل هم الكورس ابدأ\nويريحك للآخر ويعيطك حقك بالملي\nلو منزل phys نزل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1375345", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/billam-josh/76546/100", "user": "user8671", "ts": 1401630096000, "tid": 76546, "pn": 100}}]}', 1401630096000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rockwentz-engl101', 'stk-rockwentz', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en92113", "n": "Mr. Michael Hartley", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الصراحة مدرس عسل من الآخر … انا عندو 101 … رجال فاهم 😎 …\n\nالتحضير : يومي ويمشيك لو اتأخرت\nطريقة الشرح : أكثر من رائعة 👍 … تستمتع معاه بالكلاس …\nالصوت: لهجتو واضحة جداً مع أنو بريطاني لكن لهجتو مو بريطانية مرة …\nالدرجات: خليك تمام معاه وسوي الي يقلك عليه وبيعطيك ^^ …\nالقريد النهائي: A\n\nبالتوفيق للجميع … 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p727921", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hartley-michael/92113/10", "user": "RockWentz", "ts": 1288175879000, "tid": 92113, "pn": 10}}]}', 1288175879000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_z_o_y_d-engl101', 'stk-_z_o_y_d', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en92113", "n": "Mr. Michael Hartley", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سمستر:101\nكورس:انقلش 101\nالتحضير : بداية الكلااس…وما يسجل أبسنت اذا جيت الكلااس حتى لو بعد 10 دقايق…\nطريقة الشرح : ممتازة ومسلية…يوضح المطلوب بالضبط …\nالكويزات : فيه كويزات ع الويب سيتي لكن كلها ما عليها درجات…\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B+ ~ A\nالصوت: عالي و اللهجة واضحة\nإضافات : المدرس دايم مايعطي معلومات عن اللغات ويتكلم عن التاريخ…\\\nكذلك التاسك يكون في البيت…ماعدا التاسك الجاي تاسك3 بيكون في الكلااس عشان يعودنا ع الفاينال…لأنه ربما يكون رايتنج…\n😄", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p740952", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hartley-michael/92113/14", "user": "_Z_O_Y_D", "ts": 1291470433000, "tid": 92113, "pn": 14}}]}', 1291470433000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sec-ne-engl101', 'stk-sec-ne', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en92113", "n": "Mr. Michael Hartley", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "والله يا شباب الشكوى لله\n\nانا طالب ايه بلس في التحضيرية ( 002 )\nو هلحين اتمنى اني اطلع من عنده ببي او حتى سي بلس على اسواء الاحوال ( 101 )\n\nما بقي شيء ما سويته و مع ذلك هو مقتنع اني طالب افرج و مفروض ما يرفع قريداتي\nهو ياخذ اول رايتنق تاسك و يثبت درجاتك في الرايتنق تاسك الثانية على نفس الدرجة\nيعني اذا خربت الاولى … الباقية كلها خربانة …\n\nاذكر مرة جيته معترض على درجتي في الرايتنق تاسك و لمن قراها … قال ايه تستحق اكثر\nقام فتح الاكسل عشين يغيرها شاف درجاتي في التاسكات الي قبل\nقام قلي ما راح اغيرها لان تاسكاتك الاولى و الميدترم ما هي جيدة …\n\nمن الاخير بني ادمي فلة و ما يكرف … لكن انسى القريدات …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p954670", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hartley-michael/92113/57", "user": "sec-ne", "ts": 1325058196000, "tid": 92113, "pn": 57}}]}', 1325058196000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sanad_hussein-engl101', 'stk-sanad_hussein', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en92113", "n": "Mr. Michael Hartley", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ENGL 101 term 131\nالكلاس ممتع ,بعض الاحيان يشطح برى الموضوع ويتكلم عن تاريخ أوربا أو بعض المواضيع اللغوية\nمافي عمره عطانا اي هومورك\nالتاخير ما يحاسب عليه ,أذكر شباب يدخلون مو باقي على الكلاس الا نص ساعة من ساعة ونص ولا يقول لهم حاجة\nكان هو الكوردنيتير حق 101 وكان بعض الاحيان يلمح لنا عن الاسئلة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1372942", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hartley-michael/92113/68", "user": "sanad_hussein", "ts": 1401229013000, "tid": 92113, "pn": 68}}]}', 1401229013000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rhd10-engl101', 'stk-rhd10', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en92113", "n": "Mr. Michael Hartley", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 151\nكورس 101\n\nالتحضير : يوميا لكن اخر الترم صار يحضر اذا تذكر او ذكره احد\nطريقة الشرح : ممتعة ما تحس بالوقت معه رغم ان الليكتشر كان ساعة وربع مرتين في الاسبوع , و زود عليها عندك الحرية تقول اللي عندك و فلاوي و يشطح كثير واحيانا يذب +18 و يذب على الطلاب\nالكويزات : متوسطة\nالمياجر:\nالفاينلات :\nالقريد النهائي:a+\nالصوت: واضح جدا و لا هو على نغمة وحده\nإضافات : اذا تبغى مدرس ما يخليك تشيل هم الانجلش نزل عنده و اذا انت ممتاز في الانجليزي القريد مضمون بإذن الله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437873", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hartley-michael/92113/73", "user": "RHD10", "ts": 1451820787000, "tid": 92113, "pn": 73}}]}', 1451820787000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-engl101', 'stk-guest', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en94806", "n": "Mr. Jonathan Marquis", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انجلش 101 سمستر 121\n\nالتحضير: مايحضر\n\nالشرح: المادة أغلبها رايتنغ وهو متمكن في هذه الجزئية وشرحه طيب\n\nالتاسكات:أربعة تاسكات في الكلاس، لكن يلمح ببشكل واضح جدا ايش الموضوع اللي بيجي\n\nالكويزات: اذا ماني غلطان كانت كومن هذا السمستر، اذا ما عرفت الجواب وقت الاختبار اسأله وهو بيساعدك (يغششك 🤠)\n\nالهومووركات:مافي\n\nاضافات: الرجال قال من بداية الترم ودي اعطيكم درجات عالية لكن الكوردنيتر ناشب ويقول لازم تعطي كم واحد F وأنا مستحيل اعطي واحد F إلا لو كان مرة منتهي، فعموما بسهل المادة عليكم قد ما أقدر وأتساهل معاكم لكن الدرجات النهائية مو بيدي (درجات سكشني بين d وال b+) ، عموما أنا أشوف الرجال جدا ممتاز في 101 وارتحت معاه وأنصح فيه وبقوة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1152974", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marquis-jonathan/94806/23", "user": "Guest", "ts": 1357106881000, "tid": 94806, "pn": 23}}, {"id": "stk-dr-en94986", "n": "Mr. Tom Daly", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(عن بعد) Engl 101 - Term 201\n\nالتحضير : في البداية كان يحضر بشكل عشوائي خلال المحاضرة ، بعدها صار يأخذ التحضير من البلاك بورد\n\nالشرح : يستخدم سلايدات في الشرح و شرحه للمطلوب في التاسكات كويس ( ليس الافضل و لا الاسوء )\n\nاضافات : الدكتور ما يكرفك ويشغلك بالواجبات ، لكن تصحيحه افرج و ايضا يطول بالتصحيح .\n\nقريداته :\n\nhttp://https://c.top4top.io/p_1826x1j1c1.png", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527431", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/daly-tom/94986/44", "user": "Guest", "ts": 1609421514000, "tid": 94986, "pn": 44}}]}', 1357106881000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bianco-engl101', 'stk-bianco', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en94806", "n": "Mr. Jonathan Marquis", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عند ابو ماركوس انجلش 101\n\nبنود التقييم :\n\nالتحضير :\n\nبداية الترم كان يحضر بشكل يومي … بعدها صار ايام يحضر و ايام لا\n+ لاحظت ان التأخير ما يفرق معه … اذكر مرة جيت بعد 20 دقيقة و حضرني\n\nطريقة الشرح :\n\nكله على الكمبيوتر\nبالنسبة للرايتنق يشرح لك ياه على سلايدات بور بوينت و يجيب لك قطعة كـ مثال عشان تتبعها\nاما بالنسبة للفوكاب فيجيب لك ملف وورد فيه كلمات و شروح وانت توصل بينهم\nبالنسبة للقرامر فـ صراحة ما اشوفه شرحلنا قرامر ابدددا … ماعدا اللي ناخذه بالرايتنق\nاما المطلوب مننا بالكتاب ما قد فتحناه !\n\nالحلو بـ أبو ماركوس … انك لو غبت بتلاقي الشروح موجودة بالبلاك بورد\n\nالكويزات :\n\nحبه فوق و حبه تحت … على حسب الافرج\nوبالنسبة للريدنق يعطيك القطعة قبلها بيوم او يومين تذاكرها و يجيب لك اسئله عليها\nاما بالنسبة للرايتنق فيعطيك 3 او 4 مواضيع و يجي واحد منهم بالكويز\nوبالنسبة للفوكاب و القرامر … فهو يحدد لك الكلمات و القرامر اللي بيجيك بالكويز\n\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي:\n\nاعطيه b+\n\nالصوت:\nمتوسط\nإضافات :\n\nالدكتور من اصل استرالي حبييييب و اخلاااااق … ما يكرفك\nطول الترم ما عطانا واجب ابدا ! و اذا عطانا يكون مو محسوب كـ واجب\nصراحة ما كنت اشيل هم كلاساته و اختباراته …\n\nبالنسبة للقريدات فـ انا اشوفه عادل … و على كلام العيال انك لو رحت له المكتب يزودك\nلكن صراحة ما جربت اروحله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1166091", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marquis-jonathan/94806/24", "user": "Bianco", "ts": 1358600427000, "tid": 94806, "pn": 24}}]}', 1358600427000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chelsea_17-engl101', 'stk-chelsea_17', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en94806", "n": "Mr. Jonathan Marquis", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ENG 101 - Term 131\n\nالتحضير :\nنهاية كل كلاس\n\nطريقة الشرح :\nعاديه من باوربوينت\n\nالكويزات :\nاحيانا صعبه وأحيانا سهله لكن كويزات الريدينق يعطيكم القطعه قبلها بيوم ( هالشيئ ما يعجبني أبدا لأنه يخفي الفرق بين القارئ الممتاز والسيئ )\n\nالمياجر:\nميدتيرم كومون\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\nD+\n\nالصوت:\nواضح لكن تحس الدكتور أحيانا ضايع أو مفهي\n\nإضافات :\nاكتشفت متأخرا للأسف ان بعض الطلاب يرفع فيه ويبجله لأنه بالغياب يعطيك أكثر من المسموح لك + ما يعطي F …\n\nاذا انك كنت طالب كويس أو متوسط نصيحه لا تنزل عنده لأنه يرفع الطلاب اللي مستواهم نازل فيضطر ينزل من الكويسين , سكشننا كان طالبين فقط B و 3 C+ والغالبيه D-D+ كان توزيع جدا سيئ لكنه ما يبي يعطي السيئين F أو D فيضطر ينزل اللي تعبوا طول السمستر …\n\nببداية السمستر بيقول لكم أنا أعطي أبقريد تقريبا للغالبيه , وبعدين بيقول لأ لازم تجيبون لي هوموركات اختياريه عشان الأبقريد , على آخر شهر يقول ما بعطي أبقريد لكن بزيد +3 بونوس , نهاية السمستر يقول اللي باقي له اكثر من درجتين عالقريد اللي بعده لا يجيني واللي باقي له درجتين أو أقل لازم يكون سوا كل شي طلبته منه + عدد معين من الغياب + أظنه طلب تجيب له UNICORN ورماد العنقاء 🤠 ( الاخيره مزحه ) … باختصار لا تاخذ من كلامه شيئ واذا مستواك متوسط وفوق دور غيره أفضل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373631", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marquis-jonathan/94806/28", "user": "Chelsea_17", "ts": 1401324735000, "tid": 94806, "pn": 28}}]}', 1401324735000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8890-engl101', 'stk-user8890', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en94806", "n": "Mr. Jonathan Marquis", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ELD 101 - Term 132\n\nالتحضير : يحضر غالبا نهاية الكلاس قبل ما يطلعنا , متساهل بقققوه بالتأخير ( طلاب يجون بعد نص ساعة عادي)\n\nطريقة الشرح : سلايدات بالنسبة للرايتينق , أما الفوكاب ماتيريال الميد تيرم حلهن معنا وناقشنا أغلبهن بسرعة على السلايدات لكن ماتيريال الفاينل قال ذاكروهن أنتم وطبع لنا الكلمات مع تعاريف مساعدة.\n\nالكويزات : بالنسبة للريدنق عطانا كل القطع قبلها ب 24 ساعة , والأسئلة كانت شويه صعبة ويركز على معاني الكلمات عشان تذاكرها وتترجم .\n\nبالنسبة للفوكاب , جاب الكويز الاول من البلاك بورد موجود كويز على الماتيريال من 1 إلى 3 .\nوجاب الكويز الثاني أغلبه من كويز فاينل إقزام الموجود بالبلاك بورد أيضا .\n\nالقريد النهائي: +C\n\nالصوت: واضح وأسترالي المدرس .\n\nإضافات :\n\nبالبداية سمعنا عنه الأب قريد وإنه يدف حتى 3 درجات !! لكن هالشيء أبد مب صحيح .\nقالنا من قبل الميد تيرم , انا ما أدري وش مكتوب عني بالمنتدى لكن أقولها من الحين الزيادة بتكون للي باقيله درجة وحدة أو أقل وبشرط يكون جايب قريد سي على الأقل بالميد تيرم أو الفاينل وتكون غياباته أقل من 5 أظن قال أو 5 وأقل .\n\nومتشدد بالنقطة هذي , زميلي مجموعه 73.8 وما جاه أب قريد مع أنه جايب سي+ , بي بالميد والفاينل .\n\nسكشنا 25 طالب , 8 طلاب سي+ والباقي سي وتحت ( ما عطى أف)\n\nما كرفنا أبد خلال السمستر ما فيه واجبات لكن يحرصنا اننا نكتب براكتس رايتينق . وكان يطلعنا أول الوقت بدري لكن شاف محد يكتب وبدأ يجلسنا .\n\nسريع بالتصحيح وبالدرجات , الفوكاب والريدينق بالعادة بنفس اليوم أما الرايتينق بالعادة يومين.\n\nالسبيكنق متساهل فيه عطانا أغلبنا سي , سي+ … طالبين بي وطالبين دي+ على ما أظن, سوه بدري لا تأخر فيه اتوقع تفرق عنده مقارنة بالسبيكنق حقي وبالطلاب المتأخرين .\n\nخيار لا بأس به , لكن ما فيه قريد عالي معاه …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1374732", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marquis-jonathan/94806/29", "user": "user8890", "ts": 1401483451000, "tid": 94806, "pn": 29}}]}', 1401483451000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah_gh-engl101', 'stk-abdullah_gh', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en94806", "n": "Mr. Jonathan Marquis", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Engl 101 - Term 132\n\nبنود التقييم :\n\nالتحضير :\nفي بداية السمستر كان يحضر في بداية الكلاس بعدين صار يحضر في نهاية الكلاس .\n\nطريقة الشرح :\nيشرح من السلايدات من البلاك بورد وتحصلها موجودة في بداية كل اسبوع .\n\nالكويزات :\nكويزات الريدينق صعبة شوي آفرجي في الريدينق D القرامر والفوكاب C الرايتينق ( الرجال يجيب كل شي آفرج يعني ما يعطي فوق ال B )\n\nالمياجر:\nكومون مدتيرم C ،\n\nالفاينلات :\nكومون C+ ،\n\nالقريد النهائي: C+ ، وهذي أعلى درجة في سكشنا وأقل درجة D .\n\nالصوت:\nواضح ومرح ويحب البساطة , ويحب يتاكد ان الطلاب فهموا واذا عندك سؤال يجاوبك بكل شفافية .\n\nإضافات :\nمن نص السمستر صار يعطينا الشرح وكذا ويحضر ويمشينا من نص الكلاس واللي يبغى يكمل أشياؤه يجلس ، الرجال يحب الأفرج ، الرايتنق حقتي أغلبها B+ وواحد B . مريحنا جداا وما تحس بصعوبة الإنقلش . بالنسبة للريدينق كان يحطها لنا في البلاكبورد قبل قبل يوم الكويز ويسمح لنا اننا نطبع الورقة ونترجم فيها ونكتب عليها ونجيبها الاختبار .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1376150", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marquis-jonathan/94806/30", "user": "Abdullah_GH", "ts": 1401741501000, "tid": 94806, "pn": 30}}]}', 1401741501000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9305-engl101', 'stk-user9305', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en94806", "n": "Mr. Jonathan Marquis", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Jonathan Marquis\n\nنزلت عنده 101 في ترم 131 ، 102 في ترم 133 و 214 في ترم 141\n\nفي الصيف كنت منزل معه وكان كلاسه الساعة 7 الصباح وكنت منزل برمجة الساعة 1 الظهر، كنت اقدر انزل انجلش الساعة 11 مع مدرس ثاني لكني اعتقد ان الدراسة مع Marquis تستاهل التضحية هذي.\n\nحبيب ومرح وكلاسه غير ممل إطلاقاً، ما يعترف بشيء اسمه واجبات، غالباً ما يرفع آفرج السكشن في الرايتنق لأقصى حد ممكن وهو 76، وفي بعض كوزات الريدنق يكون الافرج منخفض فيزود كل الطلاب من عنده شان يرفعه، اللي يجتهد عنده يعطيه حقه بدون بخس. ما يتعرض للأديان ولا العادات في كلامه مطلقاً. يحب الطلاب يجونه في المكتب “مع اني ما رحت لمه ولا مرة” لكنه دائماً ما يقول اللي ما فهم شيء ولا عنده مشكلة يمرني في المكتب لأن هذا هو السبب اللي يخلي الجامعة تدفع لي راتبي.\n\nأوقات المياجر دائماً يخفف من الكلاسات يخليها سريعة وبعض الأحيان يلغيها، ومتفهم جداً لو رحت كلمته عن الغياب لو عندك ميجر او مشكلة. يحضر في آخر المحاضرة بالاسامي ويتغاضى عن التأخير في أغلب الاحيان، وإذا مرة فلوها الطلاب ما يعطيهم في الوجه، يجيبها بطريقة مزح.\n\nإذا تبي نصيحتي، لا تتردد انك تنزل معه ابداً لو لقيت مكانه عنده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1417215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marquis-jonathan/94806/31", "user": "user9305", "ts": 1417540536000, "tid": 94806, "pn": 31}}]}', 1417540536000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_j_h-engl101', 'stk-_j_h', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en94986", "n": "Mr. Tom Daly", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا عندو 101\n\nالمدرس ما يكرف الصراحه …\nمتفهم اذا كان فيه رايتنق تاسك بوقت مياجر نقلو يغير الموعد ويغيرو …\nالقريدات احيانا يرفعها بس بالاخير يضطر انو ينزلها عشان الافرج …\n\nالتحضير : بعض الاحيان ينسى ياخذ الأتندنس … ^^", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1124048", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/daly-tom/94986/16", "user": "_j_h", "ts": 1353879918000, "tid": 94986, "pn": 16}}]}', 1353879918000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulla_yahia-engl101', 'stk-abdulla_yahia', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en94986", "n": "Mr. Tom Daly", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "daly, tom ]\n\nENGL 101 - Term 132\n- التحضير : غالباً - ينادي بالأسماء ، لكن أحياناً ينسى ,\n\n- طريقة الشرح : يشرح على السلايدات ، شرحه جيد إلى حد ما - لكن المتيريال ما يحتاج شرح ,\n\n- الكويزات : الريدينق : 2 منهم بريريليسد - متوسطة ، الفوكاب : متوسطة ، الرايتنق : المواضيع سهلة ,\n\n- المياجر : كومن ,\n\n- الفاينلات : كومن ,\n\n- القريد النهائي : B\n\n- الصوت : متوسط - غير سلس ( صعوبة أحياناً في النطق ) ,\n\n- إضافات :الدركتور حبيب + يعطيك حقك في تصحيح الرايتنق ( يعطي A ) + لكن سلبيته أنه الدرجات يعطيك هي بالقريدات ( غير رقمية ) فأحياناً يتأثر آفرج اختباراتك بسبب هذا الأسلوب ,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1375056", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/daly-tom/94986/27", "user": "Abdulla_Yahia", "ts": 1401562904000, "tid": 94986, "pn": 27}}]}', 1401562904000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdallah_sh-engl101', 'stk-abdallah_sh', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en94986", "n": "Mr. Tom Daly", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "101-151\n\nالتحضير : من أول الترم إلى اخره نظامه يحضر آخر الحصة (يمديك تتأخر من 5 إلى 15 دقيقة 😎 بس لا تزودها) وفي بعض الأيام ينسى … و فيه أيام يتناسى (بأفصل بالإضافات)\n\nطريقة الشرح : أغلب الحصص يوزع الأوراق و تكون إما تمارين على الفوكاب أو الريدنق ( بالنسبة للرايتنق يشرح من الباوربوينت ) وشرحه ممتاز يحاول يربط بأشياء واقعية في الفوكاب\n\nالكويزات :\n\n1\\-تاسكات الرايتنق: ميزته في الرايتنق انه يخير في المواضيع اللي بتكتبها يعني اول تاسك كان defintion في الاختبار خيرنا بين اربع مواضيع لكل تعريف , الموضوع اللي بعده اعطانا pre\\-release اربع مواضيع و استمر الوضع كذا في التاسكين الباقية . 2\\-كوزات الريدنق : كوزين الواحد منها يحوي قطعتين الوحدة عليها 20 او 15 سؤال \\(طبعا يرسل ليلتها قطعة وحدة من الثنتين اللي بالاختبار , ونصيحة احتفظ بالأوراق اللي يعطيك بالكلاس لانها هي القطع\\)المياجر:كومون\n\nالفاينلات :كومون\n\nالقريد النهائي: A\n\nالصوت: الصوت واضح جدا تسمعه وما يجيب النوم\n\nإضافات : الدكتور توم حبووب و يحب يمزح و مزحه مزح محترم … أغلب الأحيان اذا تطرق لصعوبة شي في الحياة يرجع يقول welcome to kfupm 😃\n\n… إذا بتناقشه في القريدات ناقشه اذا نزلها خلال اسبوع … ما يحب اللي يجي آخر السمستر و يقول عدلي القريد\n\nبالنسبة للتعاون فهو متعاون جدا … أوقات البرزنتيشن يقول لباقي الكلاس توكلوا 🙄 , من ناحية أوقات التاسكات يقول متى تبغونها نحطها بس بحدود(التاسك الثالث مصخناها ما كتبنا الا قبل الفاينل باسبوعين :p)\n\nاذا بيحضر انتبه ممكن يغيبك بالغلط … بعض الأحيان ما يحضر عن قصد (أوقات مياجر) و يجون بعض الطلاب يذكرونه يرجع يفتح ملف التحضير و يحط الشعب كله حاضر 😏 (سواها 4 مرات)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438085", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/daly-tom/94986/32", "user": "Abdallah_SH", "ts": 1451991993000, "tid": 94986, "pn": 32}}]}', 1451991993000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-krooom-engl101', 'stk-krooom', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en94986", "n": "Mr. Tom Daly", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "161 Engl101\n\nالتحضير : من أول الترم إلى اخره نظامه يحضر آخر الحصة وغالبا ما يحضر\n\nطريقة الشرح : ترم 161 ما شرح الا حصتين والباقي تجي ما تجي ما راح تستفيد شي (الموضوع كان سلف ستدي)\n\nالكويزات :\n\n1-تاسكات الرايتنق: متساهل بشكل كبير والدرجات عالية (اخر تاسك ضيع الاوراق فقالنا تبون نعيده ولا اعطيكم الافرج حق التاسكات القديمة ).\n\n2-كوزات الريدنق : كوزين كل واحد اسهل من الثاني فحاول تضمنهم\n\nالمياجر:كومون\n\nالفاينلات :كومون\n\nالقريد النهائي: A\n\nالصوت: الصوت واضح\n\nإضافات : الدكتور توم حبووب ومتساهل وما يكرف ابد واتوقع انه كان كاره كلاسنا لانه المفروض استاذ غيره يجي فما كان يشرح زين ويلغي كلاسات ولكن كان يعوضنا بالدرجات(تعويض جهنمي)\n\nإذا بتناقشه في القريدات ناقشه ولكن التجاوب راح يكون على حسب مزاجه\n\nالدرجات (تعتبر جيدة بل ممتازة)\nB\nC+\nC+\nC+\nC+\nC+\nC\nC+\nC+\nB+\nB\nB+\nB\nC\nB\nB\nA\nC+\nC+\nC\nC+\nB+\nB+\nB\nA\nA\nA+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467076", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/daly-tom/94986/34", "user": "Krooom", "ts": 1485509939000, "tid": 94986, "pn": 34}}]}', 1485509939000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahm2d1-engl101', 'stk-ahm2d1', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en94986", "n": "Mr. Tom Daly", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ENGL 101 - Term 172\n\nالشرح : يشرح الرايتنق بطريقه غريبه ما راح تفهم شيء ولاكن افتح البلاك بورد وافهم السلايدات وبتضبط امورك انا سويت كذا والحمدلله درجاتي زي العسل …\n\nالتحضير : ما يهتم في التحضير يمكن ماحضر الا اول ثلاث اسابيع واخر ثلاث اسابيع وباقي الترم مايحضر وكثير طلاب ما يحضرون الا وقت التاسكات ، من الاخير غيب زي ماتبغى …\n\nالدكتور بشكل عام بالنسبه لي عاجبني كثير من ناحية الدرجات او من ناحية مواضيع الرايتنق اغلبها سهله و اغلبها جالسين نسمع عنها في المجتمع وهذي بتسهل عليك الافكار و كتابة الرايتنق وغالبية الدرجات من C الى B+ وقليل A يمكن واحد او اثنين بالكثير ، واتوقع الافرج عنده B الى C+ ( دكتور حق قريدات ) …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492699", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/daly-tom/94986/37", "user": "Ahm2d1", "ts": 1526680471000, "tid": 94986, "pn": 37}}]}', 1526680471000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-21m-engl101', 'stk-21m', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en94986", "n": "Mr. Tom Daly", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T-201 ENGL101\n\nالتحضير: أول شهر كان يحضر فجاة بنص الكلاس بعدين صار ياخذ التحضير من البلاك بورد .\nطريقة الشرح: طريقة عادية يستخدم عروض البوربوينت ليشرح المطلوب ويسجل المحاضرة عشان تقدر ترجع لها ويعطي امثلة.\nالكويزات: مافي.\nالمياجر: كومن\nالفاينلات: كومن\nالصوت: لهجة بريطانية واضحة\nالاضافات : يتأخر جدا بالتصحيح وتحسه يهبد درجات وبس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527087", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/daly-tom/94986/42", "user": "21M", "ts": 1607940599000, "tid": 94986, "pn": 42}}]}', 1607940599000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-2ams-engl101', 'stk-2ams', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en94986", "n": "Mr. Tom Daly", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "English 101 - Term 201\n\nالتحضير:\nأول ثلاث أسابيع كان يحضر بشكل عشوائي يطلب من كل الطلاب يرفعون يدينهم وبعدها صار ياخذ التحضير من الاسماء الموجودين في المحاضرة.\n\nطريقة الشرح:\nطريقة سلايدات يعرض فيها تقسيم الـ essay ومثال على كل جزئية الشرح في اغلب الاحيان يوصل لك المعلومة بشكل جيد.\n\nالكويزات:\nما اخذنا اي كوز.\n\nالمياجر:\nكومن.\nالفاينلات:\nكومن.\n\nالصوت:\nلهجة بريطانية واضحة.\n\nالاضافات :\nيتأخر مره في التصحيح ودايم يأجل الرايتنق تاسك وتصحيحه لك عليه درجاته حول الافرج c+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527589", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/daly-tom/94986/46", "user": "2ams", "ts": 1609817767000, "tid": 94986, "pn": 46}}]}', 1609817767000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6176-engl101', 'stk-user6176', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en96633", "n": "Mr. Lance King", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "eng101\n\nالتحضير يوميا في بداية الحصة وأحيانا إذا جيت متأخر يمشيها\nالصوت واضح شرحة ممتاز\nتصحيحه للتاسكات شدييييييييييييييييييييد جدا جدا جدا\nكتبت له تاسك وطبقت كل الي قاله وكان عندي فقط 5 غلطات صغيرة في كتابة الجمل أعطاني+D\nسألته ليه قال ماعجبتني قلت كيف قال ليست ممتازة قلت أنا طبقت كل الي قلته لي قال : صحيح بس ماعجبتني والله إن هذا الي حصل\nلذا لاتلوموني إذا أعطيته D", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1048568", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/lance-king/96633/31", "user": "user6176", "ts": 1338473274000, "tid": 96633, "pn": 31}}]}', 1338473274000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_716-engl101', 'stk-_716', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en96633", "n": "Mr. Lance King", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بصراحة ما انصح فيه القريدات زفت عنده\n\nهذا قريدات ترم 121 انجلش 101\n\na/a\\+ 1 b/b\\+ 3 c/c\\+ 16 d/d\\+ 7 f 0 w wp wf 0 dn 0 ic 0", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1154134", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/lance-king/96633/41", "user": "_716", "ts": 1357239593000, "tid": 96633, "pn": 41}}]}', 1357239593000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alhakem-engl101', 'stk-alhakem', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en96633", "n": "Mr. Lance King", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "^\nهذي درجات سكاشنه في ترم 121\n\nقارن نفسك بدرجات من تجد نفسك مقارب له\nالكوزات بالنسبة لي الفوكاب يعتمد على طريقة مذاكرتك\nالريدنق يعتمد على مهارتك لأن تقريبا لا يوجد شي تذاكره(يعطيك الموضوع اللي بيجيب عنه والباقي عليك تبحث في النت تقرأ عن هالموضوع لعل وعسى تلقط بعض الفوكاب في هذا المجال ولكنه الاحتمالات كثير كما تعرف ان الانترنت بحر)\nالقرامر عطانا سلايدات نذاكر منها وبصراحة حلوة 👍 + الكويز اللي جابه لنا كان موجود في النوتة الموجودة في الكومن سكشن في الوب سيتي\n\nالمدترم-الفاينل عليك\nالبرزنتيشن قريدك فيه يعتمد على طلاب السكشن ومن سينافسك (أقصد هل ستكون من الأسوأ مقارنة بالآخرين - هل ستكون أفرج(وسط) - أم ستكون من أحسن ناس << هي مهارة 🌹\n\nالرايتنق تاسك سو اللي يبغاه وان شاء الله خير\nاحنا أول راتنق تاسك عطانا مواضيع سهلة حيل ودرّبنا عليها كـ واجب في الوب سيتي فكان الاختبار سهل\nالرايتنق تاسك الاخير عطانا 3 مواضيع قبل الاختبار باسبوعين، نختار واحد منهم ونكتبه في الاختبار\n\nترا هالمدرس طيب واذا ماهو top فهو ليس بالسيء بالعكس رائع وتمنيته يدرس 102 🥊", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1166531", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/lance-king/96633/48", "user": "alhakem", "ts": 1358678799000, "tid": 96633, "pn": 48}}]}', 1358678799000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmad-ali-engl101', 'stk-ahmad-ali', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en96633", "n": "Mr. Lance King", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انجلش 101\nتيرم 131\n\nالتحضير:\nيحضر في بداية الكلاس ولو تأخرت تكلمه في نهاية الكلاس ويحضرك ( لو عدتها اكثر من ما بيحضرك )\n\nطريقة الشرح :\nممتع جداً انسان مثقف ورائع وحبوب جداً والكلاس ممتع بمعنى الكلمة\nوبالنسبة للمادة ما اشوف اصلاً انها تحتاج شرح لكن هو يقولك ايش يبي منك في الرايتنق ولازم تركز معاه عشان تفهم كيف تكتب\n\nالصوت :\nواضح جداً\n\nكويزات الريدنج كنت اشوفها صعبة نوعاً ما ( أعلى طالب في سكشنين للمدرس جاب b+ )\nوالرايتنق تصحيحه شديييييييييييد جداً جداً\nكان عنده سكشنين ( 40 طالب ) وكل طالب عنده 4 رايتنق تاسك\nالمجموع 160 رايتنق\nما اعطى فيهم غير 5 او 6 مرات a والباقي تحت\n\nطبيعي جداً انك تجيب b+ في الميدتيرم و a+ في الفاينل وتطلع من الكورس بـb+\nدرجات طلابه نازلة وما يعطي f ابداً\n\nلكن لو شاف انك تتحسن معاه من بداية السمستر وقاعد تبذل جهد بيساعدك فوق ما تتصور", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1318197", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/lance-king/96633/52", "user": "ahmad-ali", "ts": 1389445590000, "tid": 96633, "pn": 52}}]}', 1389445590000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-llabdulmalikll-engl101', 'stk-llabdulmalikll', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en96633", "n": "Mr. Lance King", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ENGL 101 - 151\n\n- التحضير : ببداية كل محاضرة غالباً , و أغلب الأحيان و خصوصاً بآخر فترة من الفصل صار ما يحضِّر .\n\n- طريقة الشرح : من Slides مرة يكون هو مسويها و مرة من القسم نفسه عن مواضيع الـWriting الأربعة , كنت أركِّز بالـSlides إلِّي يكون هو مسويها لأن بتقييمه بالـWriting يشوف الطالب طبِّق النصايح إلِّي قالها أو لا .\n\n- الـQuizzes : كان فيه اثنين بس للـReading من 15 إلى 18 سؤال صعبة نوعاً ما , لكن بالـWriting Task الأربع كان يعطيك الحرية دايماً بالاختيار بين ثلاث مواضيع في كل Task .\n\n- الصوت : متوسط إلى خفيف , احرص تكون بالمقدمة احتياطاً مرة يرفع و مرة ينزِّل .\n\n- الـGrade : أخذت B .\n\n- إضافات : أشوف إنَّه جيِّد بشكل عام و ما فيه أحد عليه الكلام عموماً بين كل مدرسين الـENGL , إذا لقيت فرصة نزِّل عنده أفضل من غيره .\n\nبالمرفقات درجات طلابه في ذا الفصل .\n\n!بدون عنوان.jpg|46x460](upload://haMJF21Mb01eqAcztNYutvE4A6B.jpeg)\n\n!بدون عنوان1.jpg|32x460](upload://aKGSGP9KHWWmOrbh2yttBqHjS4F.jpeg)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438127", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/lance-king/96633/59", "user": "llABDULMALIKll", "ts": 1452048166000, "tid": 96633, "pn": 59}}]}', 1452048166000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hamza_alnasser-engl101', 'stk-hamza_alnasser', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en96633", "n": "Mr. Lance King", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ENGL101 Term 151\nالتحضير : بداية الكلاس وبعض الأحيان ينسى يحضر\nطريقة الشرح : زينة, بس ما يشرح قرامر كافي, وبشكل عام الشرح ممتاز\nالكويزات : متوسط إلى صعبة\nالمياجر: A midterm exam Only\nالفاينلات : -\nالقريد النهائي:B\nالصوت:he’s a British man. Clear\nإضافات : أخلاقه حلوة, ما يعطي شغل كثير وممكن هذا عيبه الوحيد, ما يساعد الطلاب, الاعتماد عليك 80%, أنت اللي روح ابحث تمارين لل Vocab $ Grammar.\n\nذاكر للمد تيرم والفاينال صح لأنها راح ترفع القريد, والرايتينق على حسب ما عندك وطريقتك.\nالتوفيق للجميع\n…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1440159", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/lance-king/96633/61", "user": "Hamza_Alnasser", "ts": 1453465787000, "tid": 96633, "pn": 61}}]}', 1453465787000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alouchee-engl101', 'stk-alouchee', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en118628", "n": "Mr. Gordon Blazenko", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده 101 ترم 112\n\nالتحضير : متساهل نوعا ما ويسمح بالتاخير المتوسط\nطريقة الشرح : ممتازة جدا\nالكويزات : متوسطة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح واللهجة واضحة ورائعة\nإضافات :\nمدرس مممتاز متمكن من المادة مرن جدا بمواعيد الرايتنق والكوزات يحرص انه الطلاب يجيب درجة\nالشي الكويس فيه ما عمره ابدا طلب منا واجب واخذه يصححه\nالواجب عنده انك تشوف اللي طالبه وتجي تحله معه بالكلاس\nما حسيت اني منزل انقلش ابدا كل شغله بالكلاس\nتصحيحه سريع ويرسل النتايج على الويب ستي\n\nانصح فيه وبقوه !\nنزلت عنده 102 ترم 121 ولو ينزل 214 نزلت عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1042390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-blazenko-gordon/118628/14", "user": "alouchee", "ts": 1337764031000, "tid": 118628, "pn": 14}}]}', 1337764031000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8704-engl101', 'stk-user8704', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en118628", "n": "Mr. Gordon Blazenko", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا 101 انجليزي\nالتحضير :دائم\nطريقة الشرح :كان أول سمستر له صراحة فاشل و لكن يبدو عليه فاهم\nالكويزات :ممتازة\nالمياجر:كومون\nالفاينلات :كومون\nالقريد النهائي:C\nالصوت:متوسط\nإضافات :من ناحية مراعاة الظروف forget for ever يمين يسار مافيه\nالمدرس هذا يعرف يخرج نفسه خارج التكليف بطريقة رهيييييبة في بعض الأحيان و لكن في بعضها متعاون شكرا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1049777", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-blazenko-gordon/118628/16", "user": "user8704", "ts": 1338701952000, "tid": 118628, "pn": 16}}]}', 1338701952000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hisham.s-engl101', 'stk-hisham.s', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en118628", "n": "Mr. Gordon Blazenko", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا حالياً منزل معاه engl 101\n\nالتحضير يومياً يختلف وقت التحضير أحيانا اول الكلاس او وسطه او آخره\n\nالشرح : المدرس اكاديمي فاهم الماده ومتخصص باكالوريوس وماجستير باللغة الانجليزيه\n\nالكويزات : نوعا صعيبه مائله للمتوسط\n\nتصحيح الرايتنق شديد شوي\n\nالكرف: مايكرف بها الكورس والهوموركات مافيش… بس يقول حضروا الشيء الفلاني او الواجب هو تحلون السؤال الفلاني ومايدقق ابد\n\nاخلاق ومتعاون", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1123268", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-blazenko-gordon/118628/21", "user": "hisham.s", "ts": 1353793615000, "tid": 118628, "pn": 21}}]}', 1353793615000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-paatchi2013-engl101', 'stk-paatchi2013', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en118628", "n": "Mr. Gordon Blazenko", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "131 - 101\n\nبنود التقييم :\n\nالتحضير : مرات يحضر في بداية الكلاس ومرات في نهايته ماقد شفته يعصب عالمتاخرين اصلا ماقد شفته يعصب ❤️ ❤️\nطريقة الشرح : بطل بطل بكل ماتعنيه الكلمه خصوصا فالرايتنق سو اللي يقولك عليه واضمنلك قريد عالي …\nالكويزات : كويزاته حلوه وتصحيحه تمام بس كويزات الريدينق فالبدايه ماكان ينزلها قبلها بيوم لين كلمناه لانه يحسبنا نفضل طريقته يعني كلموه من البدايه واصرو عليه انه ينزلها 😆\nالمياجر: c\nالفاينلات : c\nالقريد النهائي: A+\nالصوت: واضح\nإضافات : احلا مافي ابو بلازنكو انه راعي تكنلوجيا 😆 😆 😆\nيعني كل شي يسويه فالمحاظره تلقاه فالبلاك بورد وكل شي يبيه يرسله ايميل يعني لو غبت تقدر تشيك عالبلاك بورد وامورك فالسليم 😛\n\nالقريدات للحين ماشفنها لي رجعه لما ينزلها 👋 😏", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1301619", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-blazenko-gordon/118628/28", "user": "paatchi2013", "ts": 1386373157000, "tid": 118628, "pn": 28}}]}', 1386373157000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_shaer6-engl101', 'stk-m_shaer6', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en118628", "n": "Mr. Gordon Blazenko", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "- بنود التقييم : انجلش 101 …\n\n- التحضير : تحضير يومي عن طريق الأسماء … ومايدقق ع التأخير …\n- طريقة الشرح : غالباً يجيب اوراق خارجية فيها تمارينه بطله للفوكاب والقرامر والريدنق … و شرحه هو انه يحلها مع الطلاب … ويعطي امثلة كافية ع الرايتنق تاسكس …\n- الكويزات : كومن …\n- المياجر : كمون …\n- الفاينلات : كومن …\n- القريد النهائي : B+ …\n- الصوت : واضح وكلامة مفهوم غالباً …\n- إضافات : الدكتور مشكلته أنه غالبية الطلاب درجاتهم تكون بين الـB و الـC+ … وكم طالب فوقها وتحتها …\nيعني لو مستواك كويس ممكن مايعجبك تقييمه احياناً … بس أنه التمارين الي يجيبها مفيده وكويسه …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467337", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-blazenko-gordon/118628/31", "user": "m_shaer6", "ts": 1485809518000, "tid": 118628, "pn": 31}}]}', 1485809518000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mech.e-engl101', 'stk-mech.e', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en118628", "n": "Mr. Gordon Blazenko", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ENGL101-T181\n\nالتحضير:\n\nيحضر غالبا نهاية الكلاس وحبييب مره من هالناحية لو تجي قبل لا يتنهي الكلاس بدقيقة حضّرك ما عنده مشكلة، ويقولون الشباب يسمح بالميكب بس لا تفلها مره لأنه يتضايق منها شوي.\n\nطريقة الشرح :\n\nالدكتور يعجبك انه يريحك بالبيت يعني كل شغله بالكلاس وهو دايم يقولنا اعتبروا الكلاس هو وقت مذاكرتكم الأساسي، الصراحة يعطينا واجبات اذا كان يحل معنا شيء وخلص الكلاس يقول كملوها بالبيت لكن ما يشيك عليها ودايم يرجع يحلها مره ثانيه الكلاس اللي بعده، يحاول يغطي كل شيء معنا يعني يدربنا للرايتنق قبلها بمده كافية ويورينا امثلة ويخصص كلاس كامل نتدرب فيه وبعدين يصحح لنا ويعلمنا اخطائنا ويقول اللي عنده مشكلة يجيني للمكتب وقبل الميد يخصص كم كلاس يراجع لنا ونفس الكلام للفاينل عموما اشوف شرحه ممتاز مره.\n\nالكويزات:\n\nمافي كويزات لكن بتكلم عن الرايتنق تاسكس ، المواضيع اللي يجيبها معقوله ويعطيك خيارات ودايم قبل الرايتنق يعلمنا الموضوع العام اللي بيجي يعني مثلا يقولنا بيجي عن الeducation ولا technology ويعطينا موضوع بهالمجال نتدرب عليه بالبيت ونجيه الاوفس ويصححه لنا، وبالنسبة لتصحيحه الرجال متساهل مره وسو اللي يقولك عليه ويمديك تضمن قريد كويس يعني كل التاسكات تقريبا نص الكلاس B+ وفوق.\n\nالقريد النهائي: A+\n\nالصوت: واضح.\n\nإضافات:\n\nالصراحة من اللي من اشوفه من اخوياي هو الأفضل يعني تبيه من اخلاق ولا درجات ولا شرح كل شيء الرجال من افضل الموجودين بالقسم ويعطيك حقك وزيادة بعد، وميزته بعد انه يكتب لك كل شيء بالبلاك بورد يعني تطلع من الكلاس تلقاه كاتب ٢٠ سطر وش سوينا اليوم ووش بنسوي الكلاس الجاي ووش انصحكم تسوون بالبيت ، اذا حصلته لا تفوته، كلاسه ممل شوي لان كله شرح لكنه غير اذا رحت له اوفس وتلقاه يمسك خط سوالف معك، وهذي صورة للقريدات النهائية لو تلاحظون نص الكلاس B+وفوق للسكشنين.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504064", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-blazenko-gordon/118628/35", "user": "Mech.E", "ts": 1545759573000, "tid": 118628, "pn": 35}}]}', 1545759573000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nawafmkz-engl101', 'stk-nawafmkz', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en118628", "n": "Mr. Gordon Blazenko", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "English101-191\n\nالتحضير :\nدائما قبل نهاية كل كلاس ، ما يعترف بالليت أبدا حتى لو تجي في أخر خمس دقايق\nطريقة الشرح :\nمن مميزات الدكتور تفاعله عبر الايميل، قبل كلاس يرسل وش اللي بنسويه ووش الاشياء اللي يمديك تسويها اذا تبي تحضر للدرس مثلا.\nالشرح يشرح الأشياء الأساسية الثلاث الفوكاب والريدينق والرايتنق\nالفوكاب يوزع هاند اوت تمارين لفوكاب اللستة\nالريدنق يخلي اكثر من طالب يقرا في الكلاس ويشرحها ويجاوب على الأسئلة\nالقرامر يشرح افكار اسئلة المد والفاينل مع براكتس\n.\nآخر وأهم شي في الكورس الرايتنق، يشرح فكرة كل رايتنق بالتفصيل ويوزع نموذج من عنده للطلاب، ويشرح لك بالتفصيل كيف تكتب ووشلون من عدد جمل كل برقراف إلى نوعية الجمل الخ. طبعا بعدها يطلبكم تكتبون يا كواجب او في الكلاس، ويختار نموذج من الطلاب ويشرحه ويشرح الأخطاء اللي فيه.\nالكويزات : لا يوجد\nالمياجر: ميد ترم كومن\nالفاينلات : كومن\nالصوت: واضح وقد يكون خفيف نوعا ما إذا في طلاب يسولفون\nإضافات :\n- ما يسجل ليت\n- مسموح الجوال\n- اللي يسولف ما يقوله شي > بس رجاء لا تزعجنا\n- دايما بعد كل كلاس يقول كملوا الهاند اوت او الرايتنق كواجب لكن ما يسأل عنه ولا يحاسب عليه\n- منت مجبرتكتب براكتس لكن في النهاية لازم تسلمه خمس قطع عشان درجة الرايتنق بورتفوليو\n- متواجد في الساعات المكتبية ويرحب بالطلاب\n- يرد على الايميل بسرعة\nالتصحيح:\nتصحيح الرايتنق تاسك أهم شي عنده تكتب وتوضح بطريقة صحيحة وواضحة حتى لو ما تتبع طريقته وأحيانا يحب الطالب يجيب شي جديد من عنده\nالدكتور ما يعطي F/D/D+ لكن ال A+/A نادره نوعا ما\nدايما يحاول يخلي أغلب الطلاب بين +C/B+ ممكن تكون ماخذ ب+ وأنت تستاهل A\nالقريد النهائي: حسب تجربتي A\nمرفق: قريدات الطلاب- المظللة بالأسود طلاب الدفعة الحالية 2018 اللون الآخر طلاب دفعات سابقة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518435", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-blazenko-gordon/118628/38", "user": "NawafMKZ", "ts": 1577652885000, "tid": 118628, "pn": 38}}]}', 1577652885000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-engl101', 'stk-khdsa2022', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en118628", "n": "Mr. Gordon Blazenko", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : GORDON BLAZENKO\nالمادة:ENGL101\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : مرن جدا فالتحضير لدرجة إن ماعنده ليت و لو تحضر حتى لو قبل نهاية الكلاس ب وقت قليل ادخل و عادي عنده\nطريقة الشرح : يشرح على سلايدات و منظم بشكل كبييير\nالكويزات : -------\nالمياجر: مد كومون\nالفاينلات : كومون\nالقريد النهائي: A+\nالصوت: واضح جدا\nإضافات : الرجال متعاون جدا فالتاسكات لدرجة إن كنا طول السمستر احنا آخر ناس نختبر الرايتنق فالدفعة ، أي وقت تروح له اوفس آور راح يساعدك ب أكثر شي غير إن تصحيحه للرايتنق جباااار\nنادر تشوف أحد تكون درجته C", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518743", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-blazenko-gordon/118628/39", "user": "Khdsa2022", "ts": 1578208244000, "tid": 118628, "pn": 39}}]}', 1578208244000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8697-engl101', 'stk-user8697', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en118979", "n": "Mr. Michael Stowe", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معاه 101\n\nالتحضير :في بداية الترم دايما … لكن يجلي مرات كثيرة بعدين\nطريقة الشرح : سلايدات + سبورة + شفهي\nالكويزات : في الريدنق زائد الفوكاب لازم يجيب اسئلة تعك فيها شوية\nالمياجر:كومون\nالفاينلات :كومون\nالقريد النهائي: اعطيه b\nالصوت: واضح تمام\nإضافات : روحه حلوة … وتاعمله جدا كويس … يحب يحفز الطالب ويحب يتريق عليه … لو كنت حساس راح تزعل منه وتشيل عليه كثير …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1116429", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-stowe-michael/118979/14", "user": "user8697", "ts": 1352746570000, "tid": 118979, "pn": 14}}]}', 1352746570000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-playa-engl101', 'stk-playa', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en118979", "n": "Mr. Michael Stowe", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم ,\n\nبنود التقييم :\n\nالكورس / الترم : 101 / 131\n\nالتحضير : غالبا مايحضر لكن يعرف الي يغيب والي يحضر\n\nطريقة الشرح : يشرح على سلايدز وشرحه جميل واذا ركزت معاه بتفهم 👍\n\nالكويزات : كويزاتو بصفة عامة سهلة فوكاب والريدنق اسئلته صعبه لكن بتستفيد منها بتشوف المدترم والفاينل سهليييين مقارنتا بكويزاتو. يكرف هومووركات من بداية الترم عشان يميز مين الي يشتغل ومين النايم لكن على اخر الترم مره قليلة.\n\nالمياجر: الرايتنق تاسكس ماشي مع الخطة 4 رايتنق تاسكس عليهم 35% وكان تصحيحه متوسط مائل إلى الشدة.\n\nالفاينلات : كوممون\n\nالقريد النهائي: A\n\nالصوت: الصوت مسموع واللهجة وااضحة .\n\nإضافات : الكلاس مع الآدمي دا فلللللة مرة حبوب وخفيف دم ويطقطق ع العيال احيانا 🤣 , انا انصح فيه واذا بينت له انك مهتم والله بيقدرك (اوفس اورز ) ومشاركة في الكلاس و ماتغيب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1317194", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-stowe-michael/118979/24", "user": "PLAYA", "ts": 1389175689000, "tid": 118979, "pn": 24}}]}', 1389175689000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mtaae-engl101', 'stk-mtaae', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en118979", "n": "Mr. Michael Stowe", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انجلش 101 ترم 132\n\nالتحضير : نادر وطريقة التحضير تكون عبارة عن ورقة تمر بين الطلاب\nطريقة الشرح: الكورس اغلبه رايتنق وكان شرحه بططططل واحيانا يعرض لك رايتنقز كويسة ويقول هذي a+ رايتنق\nالكويزات : الفوكاب كانت سهلة جدا والفل مارك شبه مضمون ﻻنه كان يستخدم برنامج quizlet وكانت نسخ لصق من البرنامج هذا، بالنسبة لكويزات الريدينق كانت متوسطة تميل للصعوبة احيانا\nالميدتيرم: كومون\nالفاينلات : كومون\nالقريد النهائي: اعطيه a صراحة\nالصوت: ممتاز وواضح\nإضافات :الاستاذ هذاا يعتمد كثيييير على اول نظرة ياخذها عالشخص تقدر من اول كلاس تعكس له شخصية ايجابية وراح تكسب المدرس بكل سهولة وروح له بالاوفيس اورز وما راح يقصر معاك ابدددددا وابشر بالقريدات وتراه ينكت واجد حاول تسلك وﻻ تحاول تتصادم معاه او تناقشة وﻻ تحاول تشبكه باساليب غبية مثل مدحه امام الطلاب ﻻنه يفهمها وهي طايرة ;p", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1374586", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-stowe-michael/118979/27", "user": "mtaae", "ts": 1401468126000, "tid": 118979, "pn": 27}}]}', 1401468126000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-exuse_me-engl101', 'stk-exuse_me', 'ENGL 101', 'doc', '{"docs": [{"id": "stk-dr-en118979", "n": "Mr. Michael Stowe", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سلام ،\n\nالدكتور هذا اخذت معه انقلش 101 في ترم 122\n\nواخذت معاه انقلش 102 في الصيف ( ترم 123 )\n\nتصدقون ماكنت ناوي انزل انقلش ب الصيف ، لكن يوم شفت اسمه من ضمن القائمة لاشعورياُ سجلت … وماندمت الحمدلله\n\nالتحضير : سهالات … ما اتوقع انك راح تهتم ب التحضير لأن الكلاس فله ، واذا كنت موجود هناك راح تنبسط\n\nالتصحيح : ممتاز وخصوصاُ ف الرايتنق … لكن بانقلش 102 لاحظت عليه انه صار شديد بالتصحيح ، وهو قالنا الكلام هذا … لأن انقلش 102 ينوخذ بجدية اكثر\n\nطريقة الشرح : AWESOME\n\nالكويزات : في 101 مثل ماقال الاخ mtaae نسخ لصق من كويزليت … ومادريت الا متاخر ، من جد انقهرت اني ماعرفت عن الموضوع الا ف النهاية … ركزو عليها ي شباب\n\nفي 102 كانت ريدنق ، وكان غالبا يعطينا الاوراق قبل الكويز بيوم … نترجمها ف البيت ونجي جاهزين للكويز\n\nالصوت : واضح جداَ\n\nالقريد النهائي : A+\n\nالدكتور مايخرش الميا بس لازم تشتغل معاه شوي\n\nموفقين 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1374663", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-stowe-michael/118979/28", "user": "Exuse_Me", "ts": 1401479088000, "tid": 118979, "pn": 28}}]}', 1401479088000, 1794075931, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
